function fxStar(b,x,y,s,c1,c2){ fxp(b,x,y,c2,1); for(let k=1;k<=s;k++){ const a=k===s?0.6:1; fxp(b,x+k,y,c1,a);fxp(b,x-k,y,c1,a);fxp(b,x,y+k,c1,a);fxp(b,x,y-k,c1,a);} if(s>=3){fxp(b,x+1,y+1,c1,0.7);fxp(b,x-1,y-1,c1,0.7);fxp(b,x+1,y-1,c1,0.7);fxp(b,x-1,y+1,c1,0.7);} }
