  for(let i=0;i<n;i++){ const m=b.mat[i]; if(m) px[i]=R[m][b.tone[i]]; }
  for(let y=0;y<h;y++) for(let x=0;x<w;x++){ const i=y*w+x; if(b.mat[i]) continue;
    let d=0,l=0; const ok=j=>b.mat[j]&&!NO[b.mat[j]];
    if(x>0&&ok(i-1)) d=b.mat[i-1]; else if(y>0&&ok(i-w)) d=b.mat[i-w];
    if(!d){ if(x<w-1&&ok(i+1)) l=b.mat[i+1]; else if(y<h-1&&ok(i+w)) l=b.mat[i+w]; }
    if(d) px[i]=R[d][4]; else if(l) px[i]=R[l][5];
  }
