const TROPA_ID={}; // id -> {fam,cls,pal,head,C:clase,clut}
const TROPA_MAP={rc_soldado:'soldado',rc_ballestero:'ballestero',br_guardia:'guardia'}; // ids existentes que pasan a ser tropas
// base de cada material dentro de su grupo (índice): oscuro para cuero/botas, medio para telas, claro para metal brillante
const TROPA_B={steel:3,edge:3,white:-1,teeth:-1,feather:-1,string:-1,emb:-2,og:-2,gold:-1,trim:-2,plume:-2,rose:-2,fletch:-2,skin:-1,hat:-2,hair:-3,beard:-3,lash:0,eyeA:0,eyeB:0,mouth:0,boot:1,pants:1,belt:0,leather:-1,wood:-1,quiver:0,band:1,veil:1,glove:1,capeIn:0};
for(const fam in TROPA_C) for(const cls in TROPA_C[fam]){ const C=TROPA_C[fam][cls], F=TROPA_F[fam], PN=Object.keys(F.pals);
  PN.forEach((pn,pi)=>{ const id0=fam+'_'+cls+(pi?'_'+pn:''), id=TROPA_MAP[id0]||id0; const PL=F.pals[pn], mg=Object.assign({},F.mg,PL.mg||{},C.mg||{});
    const pal={}; const pick=(m)=>{ const g=PL[mg[m]]||PL.Q; let k=TROPA_B[m]; if(k==null) k=Math.floor((g.length-1)/2)+(g.length>3?0:0); if(k<0) k=g.length+k; return g[clamp(k,0,g.length-1)]; };
    for(const m in mg) pal[m]=pick(m); pal.tab=pick('tab'); pal.cloth=pick('cloth'); pal.emb2=pick('emb2'); pal.straw=pick('straw');
    const old=SP[id]||{};
    SP[id]={k:'h',brows:1,b:C.b,hair:'troop',face:'adult',wc:old.wc||C.wc,atk:old.atk||C.atk,vic:'gen',stubble:(cls==='miliciano'||cls==='alguacil'||(cls==='guardia'&&pi===2))?1:0,
      trail:C.trail,cast:C.cast,pal};
    if(!SP[id].atk) delete SP[id].atk;
    const hd=C.heads[pi%C.heads.length]; TROPA_ID[id]={fam,cls,pal:pn,pi,head:hd,C,clut:{g:PL,mg,ol:F.ol,head:hd}}; }); }
for(const id in SP){ const s=SP[id]; if(s.pal&&s.pal.skin&&id!=='valdris') SKIN[s.pal.skin]=1; if(s.pal&&s.pal.eyeA){ EYE[s.pal.eyeA]=1; EYE[s.pal.eyeB||s.pal.eyeA]=1; } if(s.pal&&s.pal.eye) EYE[s.pal.eye]=1; s.id=id; if(s.k==='h'){ s.b=BLD[s.b]; s.pal=Object.assign({},DEF,{belt:'#5e4130',boot:'#4a3426',pants:'#3a3a40',lash:'#2b1d24'},s.pal);
  if(!s.pal.hair) s.pal.hair='#3a3030'; if(!s.pal.beard) s.pal.beard=s.pal.hair; if(!s.pal.cape) s.pal.cape='#555';
  if(id==='ilian'||s.olafOk) Object.assign(s.pal,{catfur:DEF.catfur}); }
  else s.pal=Object.assign({},DEF,s.pal); }
SP.ilian.olafOk=true;

