// ---- ojos / boca / cejas por expresión ----
function drawEyes(p,sp,expr,hb){
  const pal=sp.pal; const EA=[8,10], EB=[12,10]; // 3/4: ojo lejano angosto junto al tabique, ojo cercano adelante
  const lash='lash', br='hair~-0.45';
  const open=(x,y,eye,far)=>{ put(p,x,y,lash,1); put(p,x+1,y,lash,1); if(!far) put(p,x+2,y,lash,1);
    if(far){ put(p,x,y+1,eye,1); put(p,x+1,y+1,eye,2); put(p,x,y+2,eye,2); put(p,x+1,y+2,eye,3); }
    else { put(p,x,y+1,eye,1); put(p,x+1,y+1,'white',3); put(p,x,y+2,eye,2); put(p,x+1,y+2,eye,3); }
    if(sp.face==='child'){ put(p,x,y+3,'skin',1); } };
  const shut=(x,y,far)=>{ put(p,x,y+2,lash,1); put(p,x+1,y+2,lash,1); if(!far) put(p,x+2,y+1,lash,1); };
  const happy=(x,y)=>{ put(p,x,y+2,lash,1); put(p,x+1,y+1,lash,1); put(p,x+2,y+2,lash,1); };
  const pain=(x,y,far)=>{ if(far){ put(p,x,y,lash,1); put(p,x+1,y+1,lash,1); put(p,x,y+2,lash,1);} else { put(p,x+1,y,lash,1); put(p,x,y+1,lash,1); put(p,x+1,y+2,lash,1);} };
  const half=(x,y,eye,far)=>{ put(p,x,y+1,lash,1); put(p,x+1,y+1,lash,1); if(!far) put(p,x+2,y+1,lash,1); put(p,x,y+2,eye,1); put(p,x+1,y+2,eye,2); };
  const eA='eyeA', eB='eyeB';
  if(sp.face==='none') return;
  if(expr==='blink'||expr==='closed'||expr==='ko'){ shut(EA[0],EA[1],1); shut(EB[0],EB[1],0); }
  else if(expr==='laugh'){ happy(EA[0]-1,EA[1]); happy(EB[0],EB[1]); }
  else if(expr==='pain'){ pain(EA[0],EA[1],1); pain(EB[0],EB[1],0); }
  else if(expr==='focus'||expr==='smirk'){ half(EA[0],EA[1],eA,1); half(EB[0],EB[1],eB,0); }
  else { open(EA[0],EA[1],eA,1); open(EB[0],EB[1],eB,0); }
  // cejas
  const by=8, ang=(expr==='shout'||expr==='focus'), sad=(expr==='pain');
  if(!sp.noBrow){
    if(ang){ put(p,EA[0],by,br,1); put(p,EA[0]+1,by+1,br,1); put(p,EB[0]+1,by,br,1); put(p,EB[0],by+1,br,1); }
    else if(sad){ put(p,EA[0],by+1,br,1); put(p,EA[0]+1,by,br,1); put(p,EB[0],by,br,1); put(p,EB[0]+1,by+1,br,1); }
    else if(sp.brows){ put(p,EA[0],by,br,1); put(p,EA[0]+1,by,br,1); put(p,EB[0],by,br,1); put(p,EB[0]+1,by,br,1); }
  }
  // boca
  const mx=13,my=14;
  switch(expr){
    case 'talk': put(p,mx,my,'mouth',0); put(p,mx+1,my,'mouth',1); break;
    case 'shout': put(p,mx,my,'mouth',0); put(p,mx+1,my,'mouth',0); put(p,mx,my+1,'mouth',1); put(p,mx+1,my+1,'mouth',1); break;
    case 'laugh': put(p,mx-1,my,'teeth',2); put(p,mx,my,'teeth',2); put(p,mx+1,my,'teeth',2); put(p,mx-1,my+1,'mouth',0); put(p,mx,my+1,'mouth',0); put(p,mx+1,my+1,'mouth',1); break;
    case 'grin': put(p,mx-1,my,'mouth',1); put(p,mx,my,'teeth',2); put(p,mx+1,my,'teeth',2); put(p,mx+2,my-1,'mouth',1); break;
    case 'smirk': put(p,mx,my,'mouth',1); put(p,mx+1,my-1,'mouth',1); break;
    case 'pain': put(p,mx,my,'mouth',0); put(p,mx+1,my+1,'mouth',1); put(p,mx-1,my+1,'mouth',1); break;
    case 'ko': put(p,mx,my,'skin',0); break;
    default: put(p,mx,my,'mouth',1);
  }
  if(sp.face==='child'||sp.face==='fem') put(p,14,13,'blush',2);
  if(sp.freckles){ put(p,10,13,'skin',0); put(p,15,13,'skin',0); put(p,14,12,'skin',1); }
  if(sp.scar){ put(p,14,12,'skin',0); put(p,15,13,'skin',0); put(p,13,11,'skin',3); }
  if(sp.rednose){ put(p,16,11,'blush',1); put(p,17,11,'blush',2); put(p,16,12,'blush',1); }
  if(sp.nose){ put(p,16,10,'skin',0); put(p,17,11,'skin',1); }
  // perfil 3/4: sombra de la nariz, pómulo lejano y oreja
  put(p,16,12,'skin',1);
  put(p,5,10,'skin',1); put(p,5,11,'skin',0); put(p,5,12,'skin',1);
  if(sp.face==='old'){ put(p,EA[0]-1,EA[1]+3,'skin',1); put(p,EB[0]+2,EB[1]+3,'skin',1); }
  if(sp.stubble){ for(const q of [[11,15],[13,15],[12,16],[14,15],[10,15],[15,14]]) put(p,q[0],q[1],'skin',1); }
  if(sp.soot){ put(p,10,13,'soot',1); put(p,11,13,'soot',2); put(p,15,13,'soot',1); put(p,6,9,'soot',2); }
  if(sp.eyepatch){ put(p,12,10,'lash',1); put(p,13,10,'lash',1); put(p,14,10,'lash',1); put(p,12,11,'lash',1); put(p,13,11,'lash',2); put(p,12,12,'lash',1); put(p,13,12,'lash',1); for(const q of [[11,9],[10,9],[9,8],[8,8],[7,8],[6,7],[5,7]]) put(p,q[0],q[1],'lash',1); put(p,15,10,'lash',1); }
}
// arma la cabeza completa en un buffer chico (se cachea por id+expresión+variante)
const HEADC={};
function headBuf(sp,reg,expr,hp){
  const tl=TAIL[sp.hair]; hp=tl?(hp||0)%tl.length:0;
  const key=reg.key+'|'+expr+'|'+hp; if(HEADC[key]) return HEADC[key];
  const hb=mkBuf(34,40,8,12,reg);
  const st=HAIR[sp.hair]||[];
  if(tl){ const L=tl[hp]; const pt=part(hb,{sh:1,hl:1}); mapPut(pt,L[2],L[0],L[1],HL); commit(pt); }
  // capas de pelo traseras (moño, cola) primero si están a la izquierda
  if(sp.face!=='none'){
    const pf=part(hb,{line:false}); mapPut(pf,FACES3[sp.face]||FACES3.adult,0,1,FL);
    if(sp.hoodDeep){ // cara en sombra bajo la capucha: solo brillan los ojos
      const sm=MI(reg,'hood~-0.62'); for(const i of pf.idx){ const y=Math.floor(i/hb.w)-hb.ay; pf.m[i]=sm; pf.f[i]=(y<12?2:3); }
      if(sp.glint){ put(pf,9,11,'eyeA',3); put(pf,13,11,'eyeA',3); put(pf,8,11,'eyeA',1); put(pf,14,11,'eyeA',1); }
      else { put(pf,9,11,'eyeA',2); put(pf,13,11,'eyeA',2); }
      if(expr==='talk'||expr==='shout'){ put(pf,13,14,'hood~-0.62',0); }
    } else drawEyes(pf,sp,expr,hb);
    commit(pf);
  }
  if(sp.beard){ const bd=BEARD[sp.beard]; const pb=part(hb,{sh:1,hl:2}); mapPut(pb,bd[2],bd[0]+1,bd[1],HL); commit(pb); }
  if(sp.stache){ const bd=BEARD.stache; const pb=part(hb,{sh:1,hl:2}); mapPut(pb,bd[2],bd[0]+1,bd[1],HL); commit(pb); }
  if(sp.tattoo){ /* tatuajes en el cuello se pintan en el torso */ }
  for(const L of st){ const ph=part(hb,{sh:1,hl:1}); mapPut(ph,L[2],L[0],L[1],HL); commit(ph); }
  if(sp.hair==='hoodMask'&&expr!=='ko'){ // rendijas de la máscara con brillo rojo
    const pm=part(hb,{line:false}); for(const x of [6,7,11,12]) put(pm,x,11,'mask',0); put(pm,7,11,'eyeA',3); put(pm,12,11,'eyeA',3);
    put(pm,9,13,'trim',1); put(pm,10,14,'trim',1); commit(pm); }
  HEADC[key]=hb; return hb;
}
// copia la cabeza al buffer principal (rot 0 = de pie, 1 = acostado boca arriba)
function blitHead(b,hb,nx,ny,rot){
  const p=part(b,{line:true,keep:false,lt:1});
  for(let Y=0;Y<hb.h;Y++) for(let X=0;X<hb.w;X++){ const i=Y*hb.w+X, m=hb.mat[i]; if(!m) continue;
    const rx=X-hb.ax-8, ry=Y-hb.ay-16; let qx=rx,qy=ry; if(rot===1){ qx=ry; qy=-rx; }
    put(p,nx+qx,ny+qy,m,hb.tone[i]); }
  return commit(p);
}

