    const m={fF:[Math.round(fx),-Math.round(lf)],fB:[Math.round(bx),-Math.round(lb)],cr:(i%3===0)?1:0,ph:i,trail:2};
    if(sp.wcur==='none'||sp.wcur==='cane'||sp.wcur==='staff'){ const d=WST.none.hF(B); m.hB=[-B.sw+1+Math.round(fx*0.6),B.torso-2]; if(sp.wcur==='none') m.hF=[d[0]-Math.round(fx*0.6),d[1]]; }
