    A._hit={attack:.28};
    A.cast=[F(.12,{cr:0.5,hy:2,hr:12,ears:0.6}),F(.2,{cr:0.4,hy:1.6,hr:10,open:0.4,legs:{fn:[-2,-2]},fx:'dust'}),F(.25,{pitch:5,hr:-22,open:0.6,ears:1,legs:{fn:[1,0]},fx:'impact'}),F(.3,{hr:-4})];
    A.victory=[F(.15,{cr:0.5,hy:1.5,hr:8}),F(.12,{y:-2,pitch:7,hr:-24,open:0.6,tail:-30,legs:{fn:[1,-2],ff:[0,-1]}}),F(.4,{pitch:3,hr:-12,open:0.4,tail:-20})];
