  if(id==='garfio') L.tuft=(x,y)=>{ const q=loc(x,y); return q[0]<-sk+1.4?0.8*tri(q[1]/1.8):0; };
  if(id==='oswin') L.tuft=(x,y)=>{ const q=loc(x,y); return q[0]<-sk+1.2?0.9*tri(q[1]/2.2):0; };
  // detalles a mano
