  if(id==='arquero'){ D(1,1,'og',3); D(1.4,1.6,'og',2); for(let s=3;s<T-2;s+=2) D(s,sw-1.5,'cloth',0); }
  if(id==='soldado'&&!F.troop){ D(T-5,0.5,'rose',3); D(T-5,1.5,'rose',2); D(T-4,1,'rose',2); D(T-6,1,'rose',1); D(T-7,1,'og',1); D(T-6,0,'og',2); D(1.3,1.4,'og',3); }
  if(id==='ballestero'&&!F.troop){ D(T-5,0.6,'rose',3); D(T-5,1.6,'rose',2); D(T-4,1.1,'rose',1); D(1.3,1.4,'og',3); }
