  const pr=[E_(tp(1.2,0.2),hw+0.4,2.8,ang),C_(tp(2.4,0.3),tp(T-5,0.3),hw-0.4,sw-0.9),E_(tp(T-4.2,0.4),sw+0.2,4.2,ang),C_(tp(T-2.2,-sw+1.8),tp(T-2.2,sw-1.6),2.2,2.2)];
  if(fem) pr.push(E_(tp(T-5.4,sw-1.3),2.0,1.7,ang));
  if(big) pr.push(E_(tp(T-5,0.8),sw+0.6,5.4,ang),E_(tp(2.6,0.6),hw+1.2,3.4,ang)); // panza y pecho anchos
  if(sp.hunch) pr.push(E_(tp(T-2.6,-sw+1.4),2.8,3.2,ang));
  let sk=sp.skirt||0; if(sp.robe) sk=B.leg-2; if(sp.dress) sk=B.leg-3;
  const ph=P.ph||0, k2=ph%2, sway=[0,0.6,0,-0.6,0,0.6][ph%6]||0;
  const fl=sp.dress?3.2:(sk>=6?2.2:1.2), dk=P.lie&&(sp.robe||sp.dress)?-(fl+2):0;
  if(sk){ const a=tp(1.8,-hw-0.3),bb=tp(1.8,hw+0.3),c=tp(-sk+0.8,hw+fl+sway),d=tp(-sk+0.8,-hw-fl-dk+sway*0.5);
    pr.push(T_([a,bb,c],0.5),T_([a,c,d],0.5),C_(tp(-sk+1,-hw-fl+1-dk+sway*0.5),tp(-sk+1,hw+fl-1+sway),1.25,1.25)); }
  const apronTop=sp.dress?T-4.5:T-2.5, bib=!!sp.apron;
  const coat=sk>=6&&!sp.dress&&!sp.robe;
  const mat=(x,y)=>{ const q=loc(x,y),s=q[0],t=q[1];
    if((sp.belt||sp.rope)&&s>0.1&&s<1.9&&!(sp.apron&&sp.dress)){ if(t>0.4&&t<2.2) return s>1.2?'gold':'gold~-0.25'; return 'belt'; }
    if(sp.apron){ const front=t>-hw+0.8+(s<0?-s*0.15:0);
      if(s<=0.2){ if(front&&s>-sk+1.4) return 'apron'; }
      else if(s<apronTop&&t>-1.4&&t<sw-0.4) return 'apron';
      if(sp.dress&&s>0.1&&s<1.2&&t<=-1.4) return 'apron~-0.1'; } // tira del delantal
    if(sp.plate&&s>T-11&&s<T-1.5) return Math.abs(t-0.4)<0.6?'plate~0.14':'plate';
    if(coat||sp.trimC){ if(s<-sk+1.1) return 'trim'; if(Math.abs(t-1.0)<0.65&&s<T-0.5) return 'trim'; if(s>T-1.1&&t>-1) return 'trim'; }
    if(sp.dress&&s>T-1.3&&t>-1.5) return 'cloth~0.2'; // escote/cuello
    if(s<=0.1) return sp.dress?'cloth':'cloth~-0.08';
    return 'cloth'; };
  // pliegues: valles que nacen en la cintura y se abren hacia el ruedo, con su cresta iluminada del lado de la luz
  const FL3=sk?(sp.dress?[-hw+0.6,0.9,hw-0.1]:(sk>=5?[-hw+1,0.4,hw]:[-0.6,hw-0.8])):[];
  const fold=(x,y)=>{ const q=loc(x,y),s=q[0],t=q[1];
    if(V3S.noFold) return 0;
    if(s<0.8&&sk){ const depth=clamp((0.8-s)/(sk+0.8),0,1); let v=0;
      for(let fi=0;fi<FL3.length;fi++){ const t0=FL3[fi]; const tc=t0*(1+depth*0.5)+sway*depth*1.4+((ph+fi)&1?0.35:-0.2)*depth; const wd=0.3+depth*0.95; const d=t-tc;
        if(d>-wd*0.5&&d<wd) v=Math.min(v,-0.62*(1-Math.abs(d-wd*0.25)/wd)*(0.35+depth));
        else if(d<=-wd*0.5&&d>-wd*0.5-1.1) v=Math.max(v,0.22*depth); }
      return v; }
    if(sp.apron&&s<apronTop&&s>1.9&&t>-1.4) return -0.1*tri(t/2.2);
    if(s>1.9&&s<3.2) return -0.16*tri((t+0.5)/1.8); // arrugas sobre el cinto
    if(fem&&s>T-7.6&&s<T-6.6&&t>0) return -0.3; // sombra bajo el busto
    return 0; };
  const L={g:'torso',pr,k:2.1,R:3,cl:true,cast:true,cyl:true,mat,fold,bias:0.04,tmax:1};
  if(sk) L.tuft=(x,y)=>{ const q=loc(x,y); return q[0]<-sk+1.6?0.7*tri((q[1]+ph*0.7)/1.9):0; };
  // detalles a mano
  const D=(s,t,m,tn)=>{ const q=tp(s,t); det.push([q[0],q[1],m,tn]); };
  if(sp.apron&&sp.dress){ D(1,-hw-0.6,'apron',3); D(0,-hw-1.4,'apron',2); D(-1,-hw-1,'apron',1); D(1,-hw-1.6,'apron',2); }
  if(sp.medal){ D(T-4,sw-2,'gold',6); D(T-5,sw-2,'trim',1); D(T-4,sw-3,'gold',2); D(T-3,sw-2.5,'ribbon',2); D(T-3,sw-1.5,'ribbon',1); }
