function tplTorso(b,P,tp){ const sp=P.sp,B=sp.b, rows=tp.rows, o=tp.o, lg=tp.leg; const hip=P.hip, ch=P.chest, T=B.torso;
  const as=[(ch[0]-hip[0])/T,(ch[1]-hip[1])/T], al=Math.hypot(as[0],as[1])||1; const up=Math.abs(as[1])>0.7*al;
  const at=up?[1,0]:[P.n[0],P.n[1]]; const det=as[0]*at[1]-as[1]*at[0];
  const H=rows.length,W=rows[0].length; const smax=o[1]+0.5, smin=o[1]-H+0.5, tmin=-o[0]-0.5, tmax=W-o[0]-0.5;
  const ph=P.ph||0, sway=up?([0,0.7,0,-0.7,0,0.7][ph%6]||0):0, sk=Math.max(1,H-1-o[1]);
  let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9; for(const s of [smax,smin]) for(const t of [tmin-2,tmax+2]){ const x=hip[0]+as[0]*s+at[0]*t, y=hip[1]+as[1]*s+at[1]*t; x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y); }
  const p=part(b,{line:true,lt:0});
  for(let y=Math.floor(y0)-1;y<=Math.ceil(y1)+1;y++) for(let x=Math.floor(x0)-1;x<=Math.ceil(x1)+1;x++){
    const dx=x-hip[0], dy=y-hip[1]; const s=(dx*at[1]-dy*at[0])/det; let t=(as[0]*dy-as[1]*dx)/det; if(s<0) t-=sway*(-s/sk);
    const r=o[1]-Math.round(s), c=o[0]+Math.round(t); if(r<0||r>=H||c<0||c>=W) continue; const k=rows[r][c]; if(k==='.') continue; const L=lg[k]; if(L) put(p,x,y,L[0],L[1]); }
  return commit(p); }
