for(const id in TROPA_ID){ const p=TROPA_H[TROPA_ID[id].head]; if(p) HD3.heads[id]=p; }
function eyes15(p,sp,expr){
  const EA=[6,7], EB=[10,7], lash='lash', br='hair~-0.45';
  const open=(x,y,eye,far)=>{ put(p,x,y,lash,1); put(p,x+1,y,lash,1); if(!far) put(p,x+2,y,lash,1);
    if(far){ put(p,x,y+1,eye,1); put(p,x+1,y+1,eye,2); put(p,x,y+2,eye,2); put(p,x+1,y+2,eye,3); }
    else { put(p,x,y+1,eye,1); put(p,x+1,y+1,'white',3); put(p,x,y+2,eye,2); put(p,x+1,y+2,eye,3); } };
  const shut=(x,y,far)=>{ put(p,x,y+2,lash,1); put(p,x+1,y+2,lash,1); if(!far) put(p,x+2,y+1,lash,1); };
  const happy=(x,y)=>{ put(p,x,y+2,lash,1); put(p,x+1,y+1,lash,1); put(p,x+2,y+2,lash,1); };
  const pain=(x,y,far)=>{ if(far){ put(p,x,y,lash,1); put(p,x+1,y+1,lash,1); put(p,x,y+2,lash,1);} else { put(p,x+1,y,lash,1); put(p,x,y+1,lash,1); put(p,x+1,y+2,lash,1);} };
  const half=(x,y,eye,far)=>{ put(p,x,y+1,lash,1); put(p,x+1,y+1,lash,1); if(!far) put(p,x+2,y+1,lash,1); put(p,x,y+2,eye,1); put(p,x+1,y+2,eye,2); };
  const eA='eyeA', eB='eyeB', patch=!!sp.eyepatch;
  if(expr==='blink'||expr==='closed'||expr==='ko'){ shut(EA[0],EA[1],1); if(!patch) shut(EB[0],EB[1],0); }
  else if(expr==='laugh'){ happy(EA[0]-1,EA[1]); if(!patch) happy(EB[0],EB[1]); }
  else if(expr==='pain'){ pain(EA[0],EA[1],1); if(!patch) pain(EB[0],EB[1],0); }
  else if(expr==='focus'||expr==='smirk'||expr==='grin'){ half(EA[0],EA[1],eA,1); if(!patch) half(EB[0],EB[1],eB,0); }
  else { open(EA[0],EA[1],eA,1); if(!patch) open(EB[0],EB[1],eB,0); }
  const by=6, ang=(expr==='shout'||expr==='focus'||expr==='grin'), sad=(expr==='pain');
  if(ang){ put(p,EA[0],by,br,1); put(p,EA[0]+1,by+1,br,1); put(p,EB[0]+1,by,br,1); put(p,EB[0],by+1,br,1); put(p,EB[0]+2,by,br,1); }
  else if(sad){ put(p,EA[0],by+1,br,1); put(p,EA[0]+1,by,br,1); put(p,EB[0],by,br,1); put(p,EB[0]+1,by+1,br,1); }
  else if(sp.brows){ put(p,EA[0],by,br,1); put(p,EA[0]+1,by,br,1); put(p,EB[0],by,br,1); put(p,EB[0]+1,by,br,1); put(p,EB[0]+2,by,br,1); }
  const mx=11,my=11;
  switch(expr){
    case 'talk': put(p,mx,my,'mouth',0); put(p,mx+1,my,'mouth',1); break;
    case 'shout': put(p,mx,my,'mouth',0); put(p,mx+1,my,'mouth',0); put(p,mx,my+1,'mouth',1); put(p,mx+1,my+1,'mouth',1); break;
    case 'laugh': put(p,mx-1,my,'teeth',2); put(p,mx,my,'teeth',2); put(p,mx+1,my,'teeth',2); put(p,mx-1,my+1,'mouth',0); put(p,mx,my+1,'mouth',0); put(p,mx+1,my+1,'mouth',1); break;
    case 'grin': put(p,mx-1,my,'mouth',1); put(p,mx,my,'teeth',3); put(p,mx+1,my,sp.id==='bandido'?'mouth':'teeth',sp.id==='bandido'?0:3); put(p,mx+2,my-1,'mouth',1); break;
    case 'smirk': put(p,mx,my,'mouth',1); put(p,mx+1,my-1,'mouth',1); break;
    case 'pain': put(p,mx,my,'mouth',0); put(p,mx+1,my+1,'mouth',1); put(p,mx-1,my+1,'mouth',1); break;
    case 'ko': put(p,mx,my,'skin',0); break;
    default: if(sp.face==='fem'||sp.face==='child'){ put(p,mx,my,'mouth',1); put(p,mx+1,my,'mouth',1); } else { put(p,mx,my,'skin',0); put(p,mx+1,my,'mouth',0); }
  }
  if(sp.face==='child'||sp.face==='fem') put(p,12,10,'blush',2);
  if(sp.scar){ put(p,12,9,'skin',0); put(p,13,10,'skin',0); put(p,12,8,'skin',3); }
  if(sp.nose) put(p,14,7,'skin',1);
  put(p,13,9,'skin',1); put(p,14,8,'skin',3);                       // nariz: luz arriba, sombra abajo
  put(p,3,7,'skin',1); put(p,3,8,'skin',0); put(p,4,8,'skin',1); put(p,3,9,'skin',1); // oreja
  if(sp.face==='old'){ put(p,EA[0]-1,EA[1]+3,'skin',1); put(p,EB[0]+2,EB[1]+3,'skin',1); put(p,9,10,'skin',1); }
  if(sp.freckles){ put(p,11,10,'skin',0); put(p,13,10,'skin',0); put(p,5,9,'skin',0); }
  if(sp.rednose){ put(p,13,9,'blush',1); put(p,14,8,'blush',3); put(p,14,9,'blush',1); }
  if(sp.stubble){ for(const q of [[7,12],[9,13],[10,12],[12,12],[13,11],[8,11],[11,13]]) put(p,q[0],q[1],'beard',1); }
  if(sp.soot){ put(p,8,10,'soot',1); put(p,9,10,'soot',2); put(p,13,10,'soot',1); put(p,5,6,'soot',2); }
  if(patch){ for(let y=7;y<=9;y++) for(let x=10;x<=12;x++) put(p,x,y,'lash',y===7&&x===10?2:1); put(p,11,8,'lash',2);
    for(const q of [[9,6],[8,6],[7,5],[6,5],[5,4],[4,4],[3,3]]) put(p,q[0],q[1],'lash',1); put(p,13,7,'lash',1); }
}
const H15C={};
function headBuf15(sp,reg,expr,ph){ const h=HD3.heads[sp.id]; const tl=h.tail?(ph||0)%h.tail.length:0; const key=reg.key+'|H15|'+expr+'|'+tl; if(H15C[key]) return H15C[key];
  const D=HD3; const hb=mkBuf(34,46,12,14,reg);
  if(h.face!=='none'){ const pf=part(hb,{line:false}); mapPut(pf,D.face,0,0,FL);
    if(h.face==='shade'||h.face==='shade2'){ // capucha honda: la cara queda en sombra, solo brillan los ojos
      const deep=h.face==='shade2'; for(let y=0;y<15;y++) for(let x=0;x<15;x++){ if(D.face[y][x]==='.') continue; put(pf,x,y,deep?'hood~-0.45':(y<6?'hood~-0.4':'skin'),deep?(y>9?1:0):(y<6?1:(y<10?0:1))); }
      if(expr!=='ko'&&expr!=='blink'&&expr!=='closed'&&expr!=='pain'){ put(pf,7,8,'eyeA',deep?2:3); put(pf,11,8,'eyeA',3); put(pf,12,8,'eyeA',deep?1:2); }
      if(!deep){ put(pf,13,9,'skin',1); put(pf,11,11,'skin',0); } }
    else eyes15(pf,sp,expr);
    commit(pf); }
  if(h.beard){ const pb=part(hb,{sh:1,hl:2}); mapPut(pb,h.beard,D.x0,D.y0,HL3); commit(pb); }
  for(const k of ['coif','hair','hood']) if(h[k]){ const ph2=part(hb,{sh:1,hl:1}); mapPut(ph2,h[k],D.x0,D.y0,HL3); commit(ph2); }
  if(h.tail){ const pt=part(hb,{sh:1,hl:1}); mapPut(pt,h.tail[tl],D.x0,D.y0,HL3); commit(pt); }
  for(const k of ['extra','patch','mark']) if(h[k]){ const pe=part(hb,{sh:1,hl:1,line:k!=='mark'}); for(const q of h[k]){ const L=HL3[q[2]]; if(k==='mark') paint(hb,q[0],q[1],L[0],0); else put(pe,q[0],q[1],L[0],L[1]); } commit(pe); }
  if(sp.id==='bandido'){ paint(hb,1,1,'rope',3); }
  let o=reshade3(hb,sp,key,{crown:[5,-1],beard:[9,9]});
  if(h.helm||h.front){ o=mkBuf(hb.w,hb.h,hb.ax,hb.ay,reg); const r=HC3[key]; o.mat.set(r.mat); o.tone.set(r.tone); o.pid.set(r.pid);
    for(const k of ['helm','front']) if(h[k]){ const pk2=part(o,{sh:1,hl:1}); mapPut(pk2,h[k],D.x0,D.y0,HL3); commit(pk2); }
    if(h.coif){ for(let i=0;i<o.mat.length;i++){ if(reg.nm[o.mat[i]]==='mail'&&o.tone[i]>0){ const X=i%o.w,Y=(i-X)/o.w; if((X+Y)&1) o.tone[i]=Math.max(1,o.tone[i]-1); } } } }
  return H15C[key]=o; }
function blitHeadC(b,hb,nx,ny,rot,cx,cy){
  const p=part(b,{line:true,keep:false,lt:1});
  for(let Y=0;Y<hb.h;Y++) for(let X=0;X<hb.w;X++){ const i=Y*hb.w+X, m=hb.mat[i]; if(!m) continue;
    const rx=X-hb.ax-cx, ry=Y-hb.ay-cy; let qx=rx,qy=ry; if(rot===1){ qx=ry; qy=-rx; }
    put(p,nx+qx,ny+qy,m,hb.tone[i]); }
  return commit(p); }
function drawHuman3(b,P){
  const sp=P.sp, two=P.two;
  if(sp.cape) drawCape(b,P);
  drawBack(b,P);
  if(P.drop) dropWeapon(b,P);
  sdPass(b,[h3Leg(sp,P,'B')]);
  const armB=()=>{ const L=[h3Arm(sp,P,'B')]; if(sp.pauld&&sp.id!=='anciano') L.push(h3Pauld(sp,P,'B')); sdPass(b,L); if(!two&&!P.drop) drawWeapon(b,P,'B'); };
  if(!P.farFront){ armB(); sdPass(b,[h3Hand(sp,P,'B')]); }
  const tp=TPL3[sp.id]; if(tp){ sdPass(b,[h3Leg(sp,P,'F')]); tplTorso(b,P,tp); } else { const td=[]; sdPass(b,[h3Leg(sp,P,'F'),h3Torso(sp,P,td)],td); }
  if(sp.mantle&&!P.lie) sdPass(b,[h3Mantle(sp,P)]);
  if(P.farFront&&!P.farTop){ armB(); if(!P.fistTop) sdPass(b,[h3Hand(sp,P,'B')]); }
  const h15=!!HD3.heads&&!!HD3.heads[sp.id];
  const hb=h15?headBuf15(sp,b.reg,P.expr,P.ph):reshade3(headBuf(sp,b.reg,P.expr,P.ph),sp,b.reg.key+'|'+P.expr+'|'+(TAIL[sp.hair]?(P.ph||0)%TAIL[sp.hair].length:0));
  const u=P.u, n=P.n, nk=[P.neck[0]+u[0]*3-n[0]*1.2,P.neck[1]+u[1]*3-n[1]*1.2];
  sdPass(b,[h3Neck(sp,P,nk)]);
  const pid=h15?blitHeadC(b,hb,nk[0],nk[1],P.rot,7,14):blitHead(b,hb,nk[0],nk[1],P.rot);
  if(!P.lie){ // sombra del mentón y la nuca sobre el cuello y el pecho
    const BW=b.w; for(let i=BW;i<b.mat.length;i++){ if(b.pid[i-BW]!==pid||b.pid[i]===pid) continue; const m=b.mat[i]; if(!m||b.reg.no[m]) continue; const t=b.tone[i]; if(t>1) b.tone[i]=t===6?2:t-1; } }
  if(P.fistTop) sdPass(b,[h3Hand(sp,P,'B')]);
  if(two&&!P.drop) drawWeapon(b,P,'F');
  const shield=P.wF&&P.wF.k==='shield';
  { const L=[h3Arm(sp,P,'F')]; if(sp.pauld&&sp.id!=='anciano') L.push(h3Pauld(sp,P,'F')); sdPass(b,L); }
  if(!two&&!shield&&!P.drop) drawWeapon(b,P,'F');
  if(shield&&!P.drop) drawWeapon(b,P,'F'); else sdPass(b,[h3Hand(sp,P,'F')]);
  if(P.farTop){ armB(); sdPass(b,[h3Hand(sp,P,'B')]); }
  drawFX(b,P);
}

/* ============================================================
   F3 — FICHA DE ANIMACIÓN (Hefesto, 17/10/2026)
   Las animaciones de arriba quedan como CLAVES (la coreografía de cada
   personaje). Esta pasada las convierte en cuadros finales según la ficha:
   - reposo: 8 cuadros (respiración + manos/arma que siguen con 1 cuadro de
     retraso + ropa/pelo que se mecen), con estilo por personaje;
   - caminar: 8 cuadros por lado (contacto, bajada, paso, subida ×2), rebote
     de cadera, cabeza con retraso, brazos en contrafase, ropa/pelo atrasados;
   - ataque: arranque desde el reposo, anticipación, cuadro de ARRASTRE
     (smear) justo antes del golpe, golpe, sobrepaso y recuperación;
   - golpe recibido: impacto, retroceso máximo, vuelta, asentado;
   - KO en 3 tiempos (rodillas, caída, rebote contra el piso y quieto);
   - guardia, herido, conjuro, victoria y charla con intermedios.
   Duraciones totales y momentos de impacto (dur, hitFrame) NO cambian: los
   cuadros nuevos se reparten dentro del mismo tiempo (los combates dan
   exactamente lo mismo). PXS.f3=false vuelve a las claves (comparación).
   ============================================================ */
const F3S={on:true};
// personalidad: idle (estilo de reposo), bob (rebote al caminar), sw (balanceo de brazos), rec (retroceso al recibir), stride (+paso)
const F3D={idle:'calm',bob:1,sw:0.9,rec:1,stride:0};
const F3P={
 ilian:{idle:'light',bob:1,sw:0.9}, ilianNino:{idle:'fidget',bob:2,sw:1.3,rec:1.2},
 nach:{idle:'toes',bob:2,sw:1.3,rec:1.3,stride:1}, maela:{idle:'still',bob:1,sw:0.5,rec:0.8}, severo:{idle:'robe',bob:1,sw:0.5,rec:0.9},
 bertram:{idle:'vet',bob:1,sw:0.7,rec:0.9}, lina:{idle:'fidget',bob:2,sw:1.2,rec:1.2,stride:1},
 agnes:{idle:'calm',bob:1,sw:0.8}, bram:{idle:'heavy',bob:1,sw:0.8,rec:0.8}, tessa:{idle:'fidget',bob:2,sw:1.1,rec:1.1}, odo:{idle:'robe',bob:1,sw:0.6},
 peregrino:{idle:'robe',bob:1,sw:0.5}, encap:{idle:'still',bob:1,sw:0.4}, guardia:{idle:'still',bob:1,sw:0.6,rec:0.9}, comerciante:{idle:'calm',bob:1,sw:0.7},
 hagen:{idle:'vet',bob:1,sw:0.7}, valdris:{idle:'heavy',bob:1,sw:0.5,rec:0.6}, oswin:{idle:'heavy',bob:1,sw:0.6,rec:0.7},
 bandido:{idle:'sway',bob:1,sw:1.1,rec:1.1}, arquero:{idle:'light',bob:1,sw:0.8}, soldado:{idle:'still',bob:1,sw:0.6,rec:0.9}, ballestero:{idle:'still',bob:1,sw:0.6},
 asesino:{idle:'crouch',bob:1,sw:0.6,rec:1.1}, garfio:{idle:'fidget',bob:1,sw:1,rec:1.1},
 aldeano:{idle:'calm'}, aldeana:{idle:'calm',sw:0.8}, anciano:{idle:'vet',bob:0,sw:0.3,rec:0.8}, nino:{idle:'fidget',bob:2,sw:1.3,rec:1.2},
 cocinera:{idle:'heavy',bob:1,sw:0.7}, parroquiano:{idle:'sway',bob:1,sw:0.9}, aprendiz:{idle:'light',bob:1,sw:1}
};
for(const id in TROPA_ID) if(!F3P[id]) F3P[id]=TROPA_ID[id].C.f3; // tropas: personalidad de la clase
const f3P=id=>Object.assign({},F3D,F3P[id]||{});
const F3F=(d,m)=>({d:+d.toFixed(4),m});
const rnd0=v=>{ const r=Math.round(v); return r===0?0:r; };
// ---- interpolación de poses de humanoide (claves numéricas; lo discreto sale de la clave más cercana; fx nunca se copia) ----
function f3DefH(sp){ const B=sp.b, ws=WST[sp.wcur]||WST.none; return {hF:ws.hF(B),hB:ws.hB?ws.hB(B):WST.none.hB(B),aF:ws.wF?ws.wF.a:0,aB:ws.wB?ws.wB.a:0,fF:[B.st,0],fB:[-B.st,0],hd:[0,0]}; }
const H_NUM=['dx','dy','hx','cr','lean','br'], H_V2=['hF','hB','fF','fB','hd'], H_ANG=['aF','aB'], H_OPT=['lie','kF','kB','hFa','hBa'];
function lerpH(a,b,t,D){ const o={}, near=t<0.5?a:b;
  for(const k in near){ if(k!=='fx') o[k]=near[k]; }
  for(const k of H_NUM){ const va=a[k]||0, vb=b[k]||0; if(va||vb) o[k]=rnd0(va+(vb-va)*t); else delete o[k]; }
  for(const k of H_V2){ if(a[k]==null&&b[k]==null) continue; const va=a[k]||D[k], vb=b[k]||D[k]; o[k]=[rnd0(va[0]+(vb[0]-va[0])*t),rnd0(va[1]+(vb[1]-va[1])*t)]; }
  for(const k of H_ANG){ if(a[k]==null&&b[k]==null) continue; const va=a[k]!=null?a[k]:D[k], vb=b[k]!=null?b[k]:D[k]; o[k]=Math.round(va+(vb-va)*t); }
  for(const k of H_OPT){ if(a[k]&&b[k]) o[k]=a[k].map((v,i)=>rnd0(v+(b[k][i]-v)*t)); }
  return o; }
// ---- interpolación de poses de bestia (campos continuos: sin redondeo) ----
const Q_NUM=['x','y','cr','pitch','hy','hx','hr','ears','tail','open','dx','by','tilt'];
function lerpQ(a,b,t){ const o={}, near=t<0.5?a:b;
  for(const k in near){ if(k!=='fx') o[k]=near[k]; }
  for(const k of Q_NUM){ const va=a[k]||0, vb=b[k]||0; if(va||vb) o[k]=+(va+(vb-va)*t).toFixed(3); else delete o[k]; }
  if(a.tailC!=null&&b.tailC!=null) o.tailC=+(a.tailC+(b.tailC-a.tailC)*t).toFixed(3);
  for(const k of ['sx','sy']){ if(a[k]==null&&b[k]==null) continue; const va=a[k]==null?1:a[k], vb=b[k]==null?1:b[k]; o[k]=+(va+(vb-va)*t).toFixed(3); } // Hefesto: estiramiento (neutro = 1)
  if(a.hd||b.hd){ const va=a.hd||[0,0], vb=b.hd||[0,0]; o.hd=[Math.round(va[0]+(vb[0]-va[0])*t),Math.round(va[1]+(vb[1]-va[1])*t)]; }
  if(a.legs||b.legs){ const la=a.legs||{}, lb=b.legs||{}; if(Array.isArray(la)||Array.isArray(lb)) o.legs=near.legs; else { const L={}; for(const k of ['fn','ff','bn','bf']){ if(!la[k]&&!lb[k]) continue; const va=la[k]||[0,0], vb=lb[k]||[0,0]; L[k]=[+(va[0]+(vb[0]-va[0])*t).toFixed(3),+(va[1]+(vb[1]-va[1])*t).toFixed(3)]; } o.legs=L; } }
  return o; }
// ---- acción con golpe (ataque, disparo, conjuro, victoria): reparte cuadros dentro de cada clave ----
// s = clave de impacto. melee: arrastre al final de la clave anterior; después del impacto, sobrepaso.
function f3Act(fr,s,idle0,L,kind){
  const out=[], n=fr.length;
  for(let i=0;i<n;i++){ const f=fr[i], m=f.m, d=f.d, prev=i?fr[i-1].m:idle0, nx=i<n-1?fr[i+1].m:null; const seg=[];
    const smear=(kind==='melee'&&s>0&&i===s-1); const ease=(i===0&&d>=(smear?0.12:0.08));
    let rest=d, pre=null, post=null;
    if(ease){ const de=+(d*0.4).toFixed(3); pre=[de,L(idle0,m,0.5)]; rest-=de; }
    else if(i>0&&i<s&&d>=0.12&&!smear){ const de=+(d*0.4).toFixed(3); pre=[de,L(prev,m,0.6)]; rest-=de; }
    if(smear){ const ds=Math.min(0.04,+(d*0.4).toFixed(3)); post=[ds,f3Smear(m,fr[s].m,L)]; rest-=ds; }
    else if(s>=0&&i===s+1&&d>=0.08){ const dh=+(d*0.5).toFixed(3); post=[dh,L(m,prev,-0.3)]; rest-=dh; }          // sobrepaso: sigue de largo y vuelve
    else if(i>s+1&&d>=0.12&&nx){ const dh=+(d*0.5).toFixed(3); post=[dh,L(m,nx,0.5)]; rest-=dh; }                 // recuperación con intermedio
    else if(i===n-1&&i>s&&d>=0.12&&kind!=='vic'){ const dh=+(d*0.5).toFixed(3); post=[dh,L(m,idle0,0.6)]; rest-=dh; } // se asienta hacia el reposo
    else if(i===n-1&&kind==='vic'&&d>=0.3&&!pre&&i>0){ const dh=+(d*0.2).toFixed(3); pre=[dh,L(prev,m,1.25)]; rest-=dh; } // victoria: sobrepasa la pose final y se asienta
    if(pre) out.push(F3F(pre[0],pre[1])); out.push(F3F(rest,m)); if(post) out.push(F3F(post[0],post[1]));
  }
  return f3Fix(out,fr); }
// suma exacta: el último cuadro absorbe el error de redondeo
