  const fx=[]; for(const f of (ms.fx||[])){ if(f.t==='arc'){ const a0=m.aF!=null&&f.side!=='B'?m.aF:(m.aB!=null&&f.side==='B'?m.aB:f.a0); fx.push({t:'arc',side:f.side,a0,a1:Math.round((f.a0+f.a1)/2),fade:0.75,short:1}); }
    else if(f.t==='thrust') fx.push({t:'thrust',side:f.side,fade:0.45,short:1}); }
