  A.idle=f3Fix([F(.5,{cm:'idle0'}),F(.4,{cm:'idle1'}),F(.35,{cm:'idle0'}),F(.08,{cm:'f3blink'}),F(.07,{cm:'idle0'}),F(.3,{cm:'idle1'})],A.idle);
