/* ---- aves: caminar con cabeceo (4 cuadros) ---- */
function f3Bird(A,sp){ const B=BIRD[sp.id]; const hr=sp.id==='gallina'?4:3; const pad=f=>f.map(r=>r+'.');
  const head=(f,d)=>pad(f).map((r,j)=>j<hr?(d>0?'.'+r.slice(0,-1):r.slice(1)+'.'):r);
  const w0=B.walk[0], w1=B.walk[1];
  A.walk=f3Fix([F3F(.07,{f:pad(w0)}),F3F(.07,{f:head(w0,1)}),F3F(.07,{f:pad(w1)}),F3F(.07,{f:head(w1,-1)})],A.walk);
  A.idle=A.idle.map(f=>F3F(f.d,Object.assign({},f.m,{f:pad(f.m.f)}))); A.talk=A.idle; return A; }
/* ---- tropas (ficha de Atenea): pocas poses clave fuertes. Reposo = 4 dibujos en vaivén; ataque/disparo/conjuro ≤ 7 dibujos
   (se conserva el cuadro de impacto y el de arrastre); golpe 4; KO 5. Se fusiona el cuadro más corto con el anterior:
   la duración total y el instante del impacto no se mueven. ---- */
function tropaMerge(fr,max,hit){ fr=fr.slice(); const prot=i=>{ if(fr[i].m.smear) return true; if(hit==null) return false; let t=0; for(let k=0;k<i;k++) t+=fr[k].d; return Math.abs(t-hit)<1e-6; };
  while(fr.length>max){ let bi=-1,bd=1e9; for(let i=1;i<fr.length;i++){ if(prot(i)) continue; if(fr[i].d<bd){ bd=fr[i].d; bi=i; } } if(bi<0) break;
    fr[bi-1]={d:+(fr[bi-1].d+fr[bi].d).toFixed(4),m:fr[bi-1].m}; fr.splice(bi,1); } return fr; }
