  { const I=A.idle, k=[I[0],I[2],I[4],I[6]].map(f=>f.m), tot=I.reduce((s,f)=>s+f.d,0), d=+(tot/6).toFixed(4);
    A.idle=f3Fix([0,1,2,3,2,1].map(j=>F3F(d,k[j])),I); }
  const same=A.shoot===A.attack; A.attack=tropaMerge(A.attack,7,H.attack); A.shoot=same?A.attack:tropaMerge(A.shoot,7,H.shoot);
  const vs=A.victory===A.cast; A.cast=tropaMerge(A.cast,7,H.cast); if(vs) A.victory=A.cast;
