const PROTA_RGB=h=>{ const n=parseInt(h.slice(1),16); return [(n>>16)&255,(n>>8)&255,n&255]; };
const PROTA_LUM=c=>0.299*c[0]+0.587*c[1]+0.114*c[2];
function PROTA_near(c,list){ let best=list[0],bd=1e9; for(const q of list){ const dr=c[0]-q[0],dg=c[1]-q[1],db=c[2]-q[2], dl=PROTA_LUM(c)-PROTA_LUM(q); const d=2*dr*dr+3*dg*dg+2*db*db+6*dl*dl; if(d<bd){ bd=d; best=q; } } return best; }
const PROTA_LUTC={};
// tono de un material → color de la paleta del personaje (grupo del material; desempata por luminancia y matiz)
function PROTA_lut(reg,id){ const k=reg.key; let L=PROTA_LUTC[k]; if(L) return L; const P=PROTA_PAL[id];
  const G={}; for(const g in P.c) G[g]=P.c[g].map(PROTA_RGB); const ALL=[].concat(...Object.values(G));
  const cache={}; const st=PROTA_ST[id]||(PROTA_ST[id]={mats:{},clip:0});
  L=PROTA_LUTC[k]=(m,t)=>{ const kk=m*8+t; let v=cache[kk]; if(v!=null) return v; const nm=reg.nm[m]||'', base=baseMat(nm); st.mats[base]=1;
    const tags=(P.m[base]||'').split(' ').filter(x=>G[x]); const list=tags.length?[].concat(...tags.map(x=>G[x])):ALL;
    const c0=reg.ramps[m][t]; const c=[c0&255,(c0>>>8)&255,(c0>>>16)&255]; const q=PROTA_near(c,list);
    return cache[kk]=pk(q[0],q[1],q[2]); };
  return L; }
