  const g=cv.getContext('2d'); const img=g.createImageData(cw,ch); const d32=new Uint32Array(img.data.buffer);
  for(let y=0;y<ch;y++) for(let x=0;x<cw;x++) d32[y*cw+x]=px[(y+y0)*w+x+x0];
  g.putImageData(img,0,0);
  return {cv,ox:x0-b.ax,oy:y0-b.ay,w:cw,h:ch};
