const now=()=>(typeof performance!=='undefined'?performance.now():Date.now());
function frameKey(id,anim,fi,face,o){ const sp=SP[id];
  if(BEAST[id]||FOE[id]){ const A=animsOf(id); if(anim==='shoot'&&A.shoot===A.attack) anim='attack'; else if(anim==='victory'&&A.victory===A.cast) anim='cast'; }
  const wd=id==='ilian'&&o.weapon==='dagas'?'dagas':'', ol=id==='ilian'&&!!o.olaf?1:0;
  if(face<0&&!sp.hetero) return id+'|'+anim+'|'+fi+'|M|'+wd+'|'+ol;
  return id+'|'+anim+'|'+fi+'|'+(sp.hetero&&face<0?1:0)+'|'+wd+'|'+ol; }
