Object.defineProperty(API,'v3',{get:()=>V3S.on,set:v=>{ v=!!v; if(v===V3S.on) return; V3S.on=v; for(const k in FR) delete FR[k]; for(const k in LASTF) delete LASTF[k]; },enumerable:true});
