/* tatuaje compartido de Ilian y Maela (canon, 21/10/2026): la seña de Hagen, una punta abierta con dos rayas, en verde azulado #2B5C5E,
   del lado DERECHO del cuello (el que se ve, debajo de la oreja; en Ilian queda bajo la coleta). Va en la capa del cuello (source-atop). */
function tattoo(c,col){const T2=rgba(typeof col==='string'?col:'#2b5c5e',0.9);c.save();c.globalCompositeOperation='source-atop';
  c.strokeStyle=T2;c.lineCap='round';c.lineJoin='round';
  c.lineWidth=1.05;c.beginPath();c.moveTo(38.4,61.4);c.lineTo(41.6,55.2);c.lineTo(44.8,61.4);c.stroke(); // la punta, abierta abajo
  c.lineWidth=0.8;c.beginPath();c.moveTo(39.4,63.4);c.lineTo(43.8,63.4);c.moveTo(40.2,65.4);c.lineTo(43,65.4);c.stroke(); // las dos rayas
  c.restore();}
