function cardPaper(c,W2,H2,seed){srand(seed);const m=W2*0.035;const pts=[];
  const edge=(x0,y0,x1,y1,n,amp)=>{for(let i=0;i<n;i++){const t=i/n;pts.push([x0+(x1-x0)*t+(y1===y0?0:rr(-amp,amp)),y0+(y1-y0)*t+(x1===x0?0:rr(-amp,amp))]);}};
  const a=W2*0.012;edge(m,m,W2-m,m,40,a);edge(W2-m,m,W2-m,H2-m,56,a);edge(W2-m,H2-m,m,H2-m,40,a);edge(m,H2-m,m,m,56,a);
  for(let i=0;i<5;i++){const k=Math.floor(rr(0,pts.length));const p=pts[k];const cx=W2/2,cy=H2/2;const dx=cx-p[0],dy=cy-p[1],l=Math.hypot(dx,dy);p[0]+=dx/l*W2*rr(0.015,0.03);p[1]+=dy/l*W2*rr(0.015,0.03);}
  const P=()=>{c.beginPath();c.moveTo(pts[0][0],pts[0][1]);for(const p of pts)c.lineTo(p[0],p[1]);c.closePath();};
  c.save();P();c.shadowColor='rgba(0,0,0,0.45)';c.shadowBlur=W2*0.02;c.shadowOffsetY=W2*0.006;c.fillStyle='#e6d8b8';c.fill();c.restore();
  c.save();P();c.clip();const pp=paper();c.drawImage(pp,0,0,pp.width,pp.height,0,0,W2,H2);
  const g=c.createRadialGradient(W2*0.5,H2*0.45,W2*0.3,W2*0.5,H2*0.5,H2*0.62);g.addColorStop(0,'rgba(120,84,44,0)');g.addColorStop(1,'rgba(110,70,34,0.35)');c.fillStyle=g;c.fillRect(0,0,W2,H2);
  c.filter='blur('+(W2*0.012)+'px)';P();c.lineWidth=W2*0.035;c.strokeStyle='rgba(120,78,36,0.55)';c.stroke();c.filter='none';
  P();c.lineWidth=W2*0.004;c.strokeStyle='rgba(90,56,26,0.75)';c.stroke();c.restore();}
