try{ if(typeof window!=='undefined'&&!/^#prueba/.test(location.hash)) setTimeout(()=>{ try{ warm(ART_OFF.concat(['bertramJ']).flatMap(id=>CORE.EXPRS.map(e=>id+':'+e))); }catch(e){} },7000); }catch(e){}
