/* ---------- sellos (lienzos chicos a densidad 4: se escalan en perspectiva sin perder nitidez) ---------- */
const HDST={};
function hdStamp(key,lw,lh,fn){ return HDST[key]||(HDST[key]=hdSpr(lw,lh,4,fn)); }
function stTuft(P,i,tone){ return hdStamp(P.id+'tu'+i+'_'+tone,14,12,(g,k)=>{ const R=mkR(900+i*31+tone*7); const n=5+(R()*5|0); const base=0.18+tone*0.2; hdE(g,7,10.8,4.8,1.3,P.ao,0.3);
  for(let j=0;j<n;j++){ const x=7+(R()-0.5)*7, h=4+R()*5.5, lean=(R()-0.45)*4.2; hdBlade(g,x,11,h,lean,1.15,rh(P.grass,base+R()*0.12)); if(R()<0.75) hdBlade(g,x+lean*0.18,11-h*0.35,h*0.62,lean*0.68,0.7,rh(P.grass,clamp(base+0.3+R()*0.25+(lean<0?0.08:0),0,1))); } k.ax=7; k.ay=11; }); }
function stTall(P,i){ return hdStamp(P.id+'tt'+i,22,20,(g,k)=>{ const R=mkR(1300+i*19); hdE(g,11,18.6,7.5,1.8,P.ao,0.34); const n=12+(R()*8|0);
  for(let j=0;j<n;j++){ const x=11+(R()-0.5)*11, h=8+R()*9, lean=(R()-0.45)*7; hdBlade(g,x,19,h,lean,1.5,rh(P.grass,0.16+R()*0.2)); if(R()<0.8) hdBlade(g,x+lean*0.2,19-h*0.4,h*0.62,lean*0.7,0.9,rh(P.grass,clamp(0.5+R()*0.3+(lean<0?0.1:0),0,1))); }
  if(i%3===0) for(let j=0;j<3;j++){ const x=11+(R()-0.5)*8, y=4+R()*5; g.strokeStyle=rh(P.grass,0.7); g.lineWidth=0.4; g.beginPath(); g.moveTo(x,19); g.lineTo(x+(R()-0.5)*2,y); g.stroke(); hdE(g,x,y,0.9,1.6,rh(P.grass,0.92)); } k.ax=11; k.ay=19; }); }
function stFern(P,i){ return hdStamp(P.id+'fe'+i,20,14,(g,k)=>{ const R=mkR(1400+i*23); hdE(g,10,12.6,7,1.6,P.ao,0.34); for(let f=0;f<7;f++){ const a=-Math.PI/2+(f-3)*0.42+(R()-0.5)*0.15, Lf=6+R()*4; const t=0.3+R()*0.35+(Math.cos(a)<0?0.12:0);
  for(let s2=1;s2<=6;s2++){ const d=Lf*s2/6, x=10+Math.cos(a)*d, y=13+Math.sin(a)*d*0.8+d*d*0.025; const lw=(1-s2/7)*2.2; hdLeaf(g,x-Math.sin(a)*lw*0.6,y,lw*1.4,0.8,a-1.1,rh(P.grass,t)); hdLeaf(g,x+Math.sin(a)*lw*0.6,y,lw*1.4,0.8,a+1.1,rh(P.grass,t+0.08)); } } k.ax=10; k.ay=13; }); }
function stFlower(P,i){ return hdStamp(P.id+'fl'+i,10,9,(g,k)=>{ const R=mkR(700+i*13); const col=P.flowers[i%P.flowers.length];
  for(let j=0;j<4;j++) hdBlade(g,5+(R()-0.5)*5,8.5,3+R()*3,(R()-0.5)*2,0.9,rh(P.grass,0.3+R()*0.3));
  const n=2+(R()*4|0); for(let j=0;j<n;j++){ const x=5+(R()-0.5)*6, y=3.6+(R()-0.5)*3.4, r=0.85+R()*0.5; hdE(g,x+0.3,y+0.4,r,r*0.8,mix(col,'#1a1a10',0.5)); hdE(g,x,y,r,r*0.82,col); hdE(g,x-0.25,y-0.25,r*0.4,r*0.35,mix(col,'#ffffff',0.55)); } k.ax=5; k.ay=8.6; }); }
function stHeath(P,i){ return hdStamp(P.id+'he'+i,14,11,(g,k)=>{ const R=mkR(600+i*17); hdE(g,7,8.4,6,1.8,P.ao,0.35); hdE(g,7,7.4,5.6,2.2,rh(P.grass,0.2),0.9);
  for(let j=0;j<8;j++) hdBlade(g,7+(R()-0.5)*10,9,2.5+R()*3,(R()-0.5)*2.4,0.8,rh(P.grass,0.25+R()*0.4));
  const n=12+(R()*12|0); for(let j=0;j<n;j++){ const x=7+(R()-0.5)*9.5, y=5.6+(R()-0.5)*3.8-(Math.abs(x-7)<2.5?0.9:0); const t=clamp(0.22+(6.5-y)*0.12+(7-x)*0.03+R()*0.42,0,1); hdE(g,x,y,0.75,0.62,rh(P.heath,t)); }
  for(let j=0;j<3;j++){ const x=7+(R()-0.5)*6, y=4+R()*2; hdE(g,x,y,0.4,0.35,rh(P.heath,1),0.9); } k.ax=7; k.ay=9; }); }
function stPebble(P,i){ return hdStamp(P.id+'pb'+i,7,5,(g,k)=>{ const R=mkR(500+i*11); const n=1+(R()*3|0); for(let j=0;j<n;j++){ const x=3.5+(R()-0.5)*3.4, y=3+(R()-0.5)*1.6, r=0.7+R()*0.95;
  hdE(g,x+0.45,y+0.5,r*1.15,r*0.6,P.ao,0.4); hdE(g,x,y,r,r*0.72,rh(P.rock,0.4+R()*0.3)); hdE(g,x-r*0.3,y-r*0.3,r*0.45,r*0.3,rh(P.rock,0.88)); } k.ax=3.5; k.ay=4; }); }
