  for(let j=0;j<9;j++){ const u=(j+0.5)/9, qx=px+(ex-px)*u, qy=py+(ey-py)*u; for(const s of [-1,1]){ const na=ta+s*(0.75+R()*0.3); let tt=pass?0.18+R()*0.22+(s*sd<0?0.12:0):0.04+R()*0.08; hdLeaf(g,qx+Math.cos(na)*1.6,qy+Math.sin(na)*1.6,3+R()*1.4,0.8,na,rh(pal,tt)); } }
