// charco nítido: borde de barro húmedo, reflejo del cielo con ondas, filo de luz y matas en la orilla
function hdPuddle(c,R,hz,x,y,r,P,refl,o){ o=o||{}; const s=clamp((y-hz)/(H-hz),0,1), rx=r*(0.45+0.75*s), ry=rx*(0.14+0.16*s); const n=12, Q=[]; const ph=R()*TAU; for(let k=0;k<n;k++){ const an=k/n*TAU; const f=0.6+R()*0.5+0.16*Math.sin(an*2+ph)+0.08*Math.sin(an*3-ph); Q.push([x+Math.cos(an)*rx*f,y+Math.sin(an)*ry*f]); }
  const path=(dx,dy,sc)=>{ c.beginPath(); const q=(p)=>[x+(p[0]-x)*sc+dx,y+(p[1]-y)*sc+dy]; let a=q(Q[n-1]), b=q(Q[0]); c.moveTo((a[0]+b[0])/2,(a[1]+b[1])/2); for(let k=0;k<n;k++){ const p=q(Q[k]), p2=q(Q[(k+1)%n]); c.quadraticCurveTo(p[0],p[1],(p[0]+p2[0])/2,(p[1]+p2[1])/2); } c.closePath(); };
  path(0,0.6,1.16); c.fillStyle=rh(P.mud||P.dirt,0.22); c.globalAlpha=0.85; c.fill(); path(0,0.3,1.06); c.fillStyle=rh(P.mud||P.dirt,0.08); c.fill(); c.globalAlpha=1;
  c.save(); path(0,0,1); c.clip(); vg(c,y-ry,y+ry,[[0,mix(refl[0],refl[1],0.45)],[0.4,refl[0]],[1,o.dark||refl[0]]],x-rx*1.3,x+rx*1.3);
  for(let k=0;k<5;k++){ const yy=y-ry*0.7+R()*ry*0.9, xx=x+(R()-0.5)*rx, ln=rx*(0.25+R()*0.5); c.fillStyle=rgba(refl[1],0.25+R()*0.3); c.beginPath(); c.ellipse(xx,yy,ln,Math.max(0.3,ry*0.12),0,0,TAU); c.fill(); }
  if(o.dark) for(let k=0;k<3;k++){ const xx=x+(R()-0.5)*rx*1.4; c.strokeStyle=rgba(o.dark,0.35); c.lineWidth=0.5+s*0.8; c.beginPath(); c.moveTo(xx,y-ry*0.6); c.lineTo(xx+(R()-0.5),y+ry); c.stroke(); }
  for(let k=0;k<10;k++){ const yy=y+(R()-0.5)*ry*1.4; c.strokeStyle=rgba(refl[2],0.25+R()*0.35); c.lineWidth=0.35+s*0.3; c.beginPath(); const xx=x+(R()-0.5)*rx*1.2, ln=rx*(0.12+R()*0.3); c.moveTo(xx-ln,yy); c.lineTo(xx+ln,yy); c.stroke(); }
  c.restore(); c.strokeStyle=rgba(refl[2],0.28); c.lineWidth=0.45; c.beginPath(); c.moveTo(Q[8][0],Q[8][1]); c.quadraticCurveTo(x,y-ry*1.02,Q[10][0],Q[10][1]); c.stroke();
  const L=[]; for(let k=0;k<6+r*0.5;k++){ const an=R()*TAU; L.push([x+Math.cos(an)*rx*1.05,y+Math.sin(an)*ry*1.1+1,stTuft(P,(R()*6)|0,(R()*2)|0),0.8]); } if(o.reeds) for(let k=0;k<o.reeds;k++){ const an=Math.PI*(1.05+R()*0.9); L.push([x+Math.cos(an)*rx,y+Math.sin(an)*ry+0.5,stReed(P,(R()*6)|0,R()<0.4),0.9]); } return L; }
