function finishHD(m,R,hz,stops,vcol,va,o){ o=o||{}; if(o.np!==0) paintify(m,R,o.np||5200,6,0.42,0,hz-4); m.save(); m.globalCompositeOperation='soft-light'; m.globalAlpha=o.ga==null?0.8:o.ga; vg(m,0,H,stops); m.restore(); vignette(m,vcol,va); grain(m,o.gr==null?0.03:o.gr); }

