// árbol HD del pueblo (un poco más bajo que en el campo: el pueblo es denso)
function treeHD(kind,r,x,y){ const v=Math.floor(hash2(x,y,4)*2), rb=Math.round(r/4)*4, key='hd'+kind+rb+'_'+v; if(TCACHE[key]) return TCACHE[key]; const sd=rb*17+v*101+kind.length*7;
  const spr=kind==='pine'?MATS.pine(Math.round(rb*4.4),sd,TS_HD):(kind==='fruit'?oakT(Math.round(rb*3.6),sd,TS_HD,{fruit:1}):oakT(Math.round(rb*3.9),sd,TS_HD));
  return TCACHE[key]={spr,ox:-spr.ax,oy:-spr.ay,hd:1}; }
// roble del pueblo: el mismo dibujo que MATS.oak (misma secuencia de azar → mismo árbol), pero con lienzo holgado.
// MATS.oak arma un lienzo de 2,25·cr de ancho y h+4 de alto, y los racimos llegan a ±1,7·cr y 0,26·cr por encima: la copa salía recortada en rectángulo (M2).
function oakT(h,seed,S,o){ o=o||{}; const M=MATS, pal=o.pal||M.PAL.oak; const R=M.rng(seed||3); const cr=h*0.36, lw=Math.ceil(cr*3.6+10), lh=Math.ceil(h+6+cr*0.34);
  return M.sprS(lw,lh,S,(g,k)=>{ const cx=lw/2, by=lh-2.5, ccy=by-h+cr*1.02; const trunkTop=ccy+cr*0.55, tw=Math.max(2.4,h*0.075);
    M.ao(g,cx+1,by-0.3,tw*2.6,tw*0.7,0.55);
    const BK=M.PAL.bark;
    g.fillStyle=BK[2]; g.beginPath(); g.moveTo(cx-tw*1.35,by); g.quadraticCurveTo(cx-tw*0.55,by-tw*0.8,cx-tw*0.5,trunkTop); g.lineTo(cx+tw*0.5,trunkTop); g.quadraticCurveTo(cx+tw*0.6,by-tw*0.8,cx+tw*1.45,by); g.closePath(); g.fill();
    const tg=g.createLinearGradient(cx-tw,0,cx+tw,0); tg.addColorStop(0,BK[5]); tg.addColorStop(0.45,BK[3]); tg.addColorStop(1,BK[1]); g.fillStyle=tg; g.fill();
    for(let i=0;i<tw*5;i++){ const x=cx+(R()-0.5)*tw*1.6, y0=trunkTop+R()*(by-trunkTop); g.strokeStyle=R()<0.5?BK[1]:BK[4]; g.globalAlpha=0.55; g.lineWidth=0.4; g.beginPath(); g.moveTo(x,y0); g.lineTo(x+(R()-0.5)*0.6,y0+1.5+R()*3); g.stroke(); } g.globalAlpha=1;
    g.strokeStyle=BK[2]; g.lineWidth=tw*0.45; [[-1,0.8],[1,0.6],[-0.4,1.1]].forEach(([d,l])=>{ g.beginPath(); g.moveTo(cx,trunkTop+2); g.quadraticCurveTo(cx+d*cr*0.3,trunkTop-cr*0.2,cx+d*cr*0.55*l,trunkTop-cr*0.55*l); g.stroke(); });
    const B=[[cx,ccy,cr*0.9]]; const nb=7+(R()*5|0); for(let i=0;i<nb;i++){ const a=-Math.PI*(0.05+R()*0.9)+(R()<0.25?Math.PI*0.95:0), d=cr*(0.45+R()*0.45); B.push([cx+Math.cos(a)*d*1.15,ccy+Math.sin(a)*d*0.78,cr*(0.42+R()*0.22)]); }
    for(let i=0;i<4;i++){ const x=cx+(R()-0.5)*cr*1.5; B.push([x,ccy+cr*(0.35+R()*0.2),cr*(0.36+R()*0.16)]); }
    B.sort((a,b)=>a[1]-b[1]);
    for(const b of B) M.ell(g,b[0]+b[2]*0.08,b[1]+b[2]*0.1,b[2]*1.02,b[2]*0.92,pal[1]);
    for(const [bx,byy,br] of B){ const gN=(byy-ccy)/cr, gX=(bx-cx)/cr;
      M.ell(g,bx+br*0.06,byy+br*0.12,br*0.98,br*0.86,M.rampH(pal,clamp(0.16-gN*0.08,0,1)));
      const LS=1+Math.max(0,cr-22)*0.018, nL=Math.round(br*br*1.15/(LS*LS));
      for(let i=0;i<nL;i++){ const a=R()*TAU, d=Math.sqrt(R()); const nx=Math.cos(a)*d, ny=Math.sin(a)*d; const x=bx+nx*br*1.02, y=byy+ny*br*0.9;
        let t=0.42-nx*0.3-ny*0.42+(1-d)*0.05-gN*0.18-gX*0.1+(R()-0.5)*0.24; if(i<nL*0.35) t-=0.18;
        const ang=Math.PI*0.5+nx*0.9+(R()-0.5)*0.9; M.leaf(g,x,y,(2.6+R()*1.8)*LS,(1.25+R()*0.5)*LS,ang,M.rampH(pal,clamp(t,0.04,0.97))); }
      for(let i=0;i<br*1.3;i++){ const a=-Math.PI*(0.55+R()*0.4), d=0.7+R()*0.3; const x=bx+Math.cos(a)*br*d, y=byy+Math.sin(a)*br*0.85*d; M.leaf(g,x,y,2.2+R(),1.1,Math.PI*0.5+Math.cos(a)*0.8,M.rampH(pal,0.84+R()*0.15)); } }
    if(o.fruit) for(let i=0;i<cr*1.4;i++){ const a=R()*TAU, d=Math.sqrt(R())*cr*0.85; const x=cx+Math.cos(a)*d*1.1, y=ccy+Math.sin(a)*d*0.75; M.ell(g,x,y,0.95,0.95,'#b8322a'); M.ell(g,x-0.3,y-0.3,0.35,0.35,'#f4a080'); }
    k.ax=cx; k.ay=by; k.canopy=[cx,ccy,cr]; }); }
