function roomKit(def){ const M=MATS, w=def.w,h=def.h,WH=def.wallH; const base=M.canvasS(w,h,TS_HD), g=base.g; const R=mkR(def.seed||7); const objs=[], rects=[], lights=[], spots={};
  const K={w,h,WH,g,M,R,base,objs,rects,lights,spots,doorX:def.doorX,
    obj(x,y,spr,ox,oy,sh){ const o={x,y,spr,ox:ox==null?-(spr.ax||0):ox,oy:oy==null?-(spr.ay||0):oy}; objs.push(o); if(sh!==false&&spr.lw) M.softEll(g,x+3,y+1,spr.lw*0.42,3.2,'#0a0604',0.32); return o; },
    anim(y,draw){ const o={y,draw}; objs.push(o); return o; },
    block(x,y,ww,hh){ rects.push([x,y,ww,hh]); },
    light(x,y,r,col,a,flick){ lights.push({x,y,r,col,a,flick:flick||0,ph:hash2(x,y,9)*9}); },
    spot(k,x,y){ spots[k]={x,y}; } };
  return K; }
// piso de tablas: hileras con juntas desfasadas, clavos, desgaste en el paso y oclusión al pie del muro
function floorBoards(K,y0,o){ const {g,M,R,w,h}=K; o=o||{}; const pal=o.pal||M.PAL.woodWarm, bh=o.bh||8;
  for(let y=y0,row=0;y<h;y+=bh,row++){ let x=-R()*70; while(x<w){ const L=48+R()*74, xa=Math.max(0,x), xb=Math.min(w,x+L); if(xb-xa>1) M.planks(g,xa,y,xb-xa,Math.min(bh,h-y),{pal,pw:bh,seed:row*131+(x|0)+7,lit:(R()-0.5)*0.14+(o.lit||0)});
      g.fillStyle=M.rgba(M.PAL.ao,0.6); g.fillRect(x+L-0.5,y,0.9,bh); M.ell(g,x+L-2.6,y+bh*0.3,0.5,0.5,M.PAL.iron[2]); M.ell(g,x+L-2.6,y+bh*0.72,0.5,0.5,M.PAL.iron[2]); x+=L; } }
  for(let i=0;i<w*h/2600;i++) M.softEll(g,R()*w,y0+20+R()*(h-y0-30),8+R()*18,3+R()*5,R()<0.5?'#2a1a0c':'#e8c890',0.07); }
