function frontRimHD(K){ const M=MATS, {w,doorX}=K; return M.sprS(w,12,TS_HD,(g,k)=>{ g.fillStyle='#1a100a'; g.fillRect(0,2,w,10); M.planks(g,0,2,w,3,{pal:M.PAL.timber,pw:3,seed:4,lit:-0.1}); g.clearRect(doorX-16,0,32,12); g.fillStyle='#4a3020'; g.fillRect(doorX-18,0,2.4,12); g.fillRect(doorX+15.6,0,2.4,12); k.ax=0; k.ay=0; }); }
function shadeCanvas(K,dark){ const {w,h}=K; const k=cv(w,h), x=k.getContext('2d'); x.fillStyle='rgba(12,8,22,'+dark+')'; x.fillRect(0,0,w,h); x.globalCompositeOperation='destination-out';
  K.lights.forEach(l=>{ const g=x.createRadialGradient(l.x,l.y,0,l.x,l.y,l.r); g.addColorStop(0,'rgba(0,0,0,'+Math.min(1,l.a*1.3)+')'); g.addColorStop(0.55,'rgba(0,0,0,'+(l.a*0.6)+')'); g.addColorStop(1,'rgba(0,0,0,0)'); x.fillStyle=g; x.fillRect(l.x-l.r,l.y-l.r,l.r*2,l.r*2); });
  x.globalCompositeOperation='source-over'; const vg2=x.createRadialGradient(w/2,h*0.55,Math.min(w,h)*0.35,w/2,h*0.55,Math.max(w,h)*0.75); vg2.addColorStop(0,'rgba(8,6,16,0)'); vg2.addColorStop(1,'rgba(8,6,16,.35)'); x.fillStyle=vg2; x.fillRect(0,0,w,h); return k; }
// luz cálida pintada sobre el cuarto (tono, no solo hueco en la penumbra)
function warmLight(K){ const {g}=K; g.save(); g.globalCompositeOperation='soft-light'; K.lights.forEach(l=>{ const gr=g.createRadialGradient(l.x,l.y,0,l.x,l.y,l.r); gr.addColorStop(0,MATS.rgba(l.col,Math.min(0.55,l.a*0.6))); gr.addColorStop(1,MATS.rgba(l.col,0)); g.fillStyle=gr; g.fillRect(l.x-l.r,l.y-l.r,l.r*2,l.r*2); }); g.restore(); }
function finishRoom(K,def){ const {w,h,WH}=K; if(def.stairs) stairGapHD(K); else doorGapHD(K); sideWallsHD(K); warmLight(K); const base=K.base; const front=frontRimHD(K); const shadeK=shadeCanvas(K,def.dark==null?0.4:def.dark);
  K.objs.sort((a,b)=>a.y-b.y);
  const exit={x:K.doorX,y:h-7}, spawn={x:K.doorX,y:h-22};
  function collide(x,y){ if(x<12||x>w-12||y<WH+5) return true; if(y>h-13){ if(Math.abs(x-K.doorX)>10||y>h-3) return true; } for(const r of K.rects) if(x>=r[0]&&x<r[0]+r[2]&&y>=r[1]&&y<r[1]+r[3]) return true; return false; }
  function draw(c,cam,dt,ents){ c.save(); c.fillStyle='#050408'; c.fillRect(0,0,W,H); c.imageSmoothingEnabled=false; c.translate(-Math.round(cam.x),-Math.round(cam.y)); c.drawImage(base,0,0,w,h);
    const list=K.objs.slice(); (ents||[]).forEach(e=>list.push({y:e.y,ent:e})); list.sort((a,b)=>a.y-b.y);
    for(const o of list){ if(o.ent) o.ent.draw(c); else if(o.draw) o.draw(c); else { const s=o.spr, S=s.S||1; c.drawImage(s,o.x+o.ox,o.y+o.oy,s.width/S,s.height/S); } }
    c.drawImage(front,0,h-12,w,12); c.drawImage(shadeK,0,0);
    c.globalCompositeOperation='lighter'; for(const l of K.lights){ if(!l.flick) continue; const f=0.75+0.18*Math.sin(T*7+l.ph)+0.08*Math.sin(T*17+l.ph*2); c.globalAlpha=clamp(l.a*l.flick*f,0,1); const r=l.r*(0.95+0.05*f); c.drawImage(sprGlow(l.col),l.x-r,l.y-r,r*2,r*2); }
    c.globalAlpha=1; c.globalCompositeOperation='source-over'; c.restore(); }
  function drawOver(c,cam,dt){ if(!def.motes) return; c.save(); c.translate(-Math.round(cam.x),-Math.round(cam.y)); c.fillStyle='rgba(255,236,190,.55)'; for(let i=0;i<18;i++){ const ph=hash2(i,3,def.seed||1)*9; const x=def.motes[0]+((i*37+T*(3+i%3))%def.motes[2]), y=def.motes[1]+((i*23+Math.sin(T*0.6+ph)*8+T*2)%def.motes[3]); if(Math.sin(T*1.5+ph)>-0.2) c.fillRect(Math.round(x),Math.round(y),1,1); } c.restore(); }
  return {id:def.id,name:def.name,w,h,wallH:WH,spawn,exit,spots:K.spots,collide,draw,drawOver,_objs:K.objs}; }
// hogar de piedra (pecho de chimenea saliente, repisa, boca con brasas) — pintado en el muro
function hearthHD(K,x0,ww,mouthW,mouthH,o){ const {g,M,WH}=K; o=o||{}; const top=o.top==null?0:o.top, mx=x0+ww/2;
  M.stoneWall(g,x0,top,ww,WH+6-top,{seed:x0+3,rh:6.6}); const sg=g.createLinearGradient(x0,0,x0+ww,0); sg.addColorStop(0,'rgba(255,230,190,.1)'); sg.addColorStop(0.6,'rgba(0,0,0,0)'); sg.addColorStop(1,'rgba(10,8,14,.35)'); g.fillStyle=sg; g.fillRect(x0,top,ww,WH+6-top);
  const my=WH+4-mouthH; g.fillStyle='#120804'; g.beginPath(); g.moveTo(mx-mouthW/2,WH+4); g.lineTo(mx-mouthW/2,my+8); g.quadraticCurveTo(mx,my-6,mx+mouthW/2,my+8); g.lineTo(mx+mouthW/2,WH+4); g.closePath(); g.fill();
  const ig=g.createRadialGradient(mx,WH,2,mx,WH-mouthH*0.3,mouthH); ig.addColorStop(0,'rgba(255,140,40,.55)'); ig.addColorStop(1,'rgba(255,140,40,0)'); g.fillStyle=ig; g.fill();
  const R=mkR(x0); for(let i=0;i<30;i++) M.ell(g,mx+(R()-0.5)*mouthW*0.8,WH+1+R()*2.4,1+R()*1.6,0.8+R()*0.6,R()<0.5?'#ff8a28':'#3a1a0a',0.9);
  M.planks(g,x0-5,my-8,ww+10,4.4,{pal:M.PAL.woodWarm,pw:4.4,seed:x0,lit:0.12}); g.fillStyle='rgba(10,8,6,.5)'; g.fillRect(x0-5,my-3.6,ww+10,1.6);
  M.planks(g,x0-2,WH+4,ww+4,4,{pal:M.PAL.stone,pw:4,seed:x0+9,lit:0.1}); }
// estante de pared con botellas y frascos
function shelfHD(K,x,y,ww){ const {g,M,R}=K; M.planks(g,x,y,ww,3,{pal:M.PAL.woodWarm,pw:3,seed:x+y,lit:0.15}); g.fillStyle='rgba(10,6,4,.45)'; g.fillRect(x,y+3,ww,2.4); [x+4,x+ww-6].forEach(bx=>{ g.fillStyle=M.PAL.woodWarm[2]; g.beginPath(); g.moveTo(bx,y+3); g.lineTo(bx+2,y+3); g.lineTo(bx+2,y+9); g.closePath(); g.fill(); });
  let k=x+3; while(k<x+ww-7){ const hh=7+(R()*8|0), bw=3.4+R()*2.4, col=['#2e6a44','#7a2a1e','#c8a040','#3a4a8a','#8a5a9a','#d8d0b8','#4a3a20'][R()*7|0]; const gr=g.createLinearGradient(k,0,k+bw,0); gr.addColorStop(0,shade(col,0.35)); gr.addColorStop(0.4,col); gr.addColorStop(1,shade(col,-0.4)); g.fillStyle=gr;
    if(R()<0.6){ M.rrect(g,k,y-hh+3,bw,hh-3,1); g.fill(); g.fillRect(k+bw/2-0.8,y-hh,1.6,3.4); g.fillStyle='#6a4a2a'; g.fillRect(k+bw/2-0.9,y-hh-0.8,1.8,1.2); } else { M.rrect(g,k,y-hh*0.7,bw+1.6,hh*0.7,1.4); g.fill(); g.fillStyle='#e8dcc0'; g.fillRect(k-0.2,y-hh*0.7-1,bw+2,1.4); }
    g.fillStyle='rgba(255,255,255,.35)'; g.fillRect(k+0.6,y-hh+4,0.6,hh*0.4); k+=bw+2+R()*2.4; } }
// alfombra (pintada en el piso)
function rugHD(K,x,y,ww,hh,pal,edge){ const {g,M}=K; M.softEll(g,x+ww/2+2,y+hh/2+2,ww*0.55,hh*0.6,'#0a0604',0.2); g.fillStyle=edge; M.rrect(g,x,y,ww,hh,2); g.fill(); const gr=g.createLinearGradient(x,y,x+ww,y+hh); gr.addColorStop(0,M.rampH(pal,0.7)); gr.addColorStop(1,M.rampH(pal,0.35)); g.fillStyle=gr; g.fillRect(x+3,y+3,ww-6,hh-6);
  g.save(); g.beginPath(); g.rect(x+3,y+3,ww-6,hh-6); g.clip(); for(let i=0;i<ww/8;i++) for(let j=0;j<hh/8;j++){ if((i+j)%2) continue; const cx=x+6+i*8, cy=y+6+j*8; g.fillStyle=M.rgba(M.rampH(pal,0.9),0.35); g.beginPath(); g.moveTo(cx,cy-3); g.lineTo(cx+3,cy); g.lineTo(cx,cy+3); g.lineTo(cx-3,cy); g.closePath(); g.fill(); } g.restore();
  g.strokeStyle=edge; g.lineWidth=0.6; for(let q=x+2;q<x+ww-1;q+=1.8){ g.beginPath(); g.moveTo(q,y+hh); g.lineTo(q,y+hh+1.6); g.moveTo(q,y); g.lineTo(q,y-1.6); g.stroke(); } }
