const rgba=(h,a)=>{ const v=rgb(h); return 'rgba('+v[0]+','+v[1]+','+v[2]+','+a+')'; };
function hash2(x,y,s){ let h=(x*374761393+y*668265263+(s||0)*982451653)|0; h=Math.imul(h^(h>>>13),1274126177); h^=h>>>16; return (h>>>0)/4294967296; }
function vn(x,y,sc,s){ x/=sc; y/=sc; const xi=Math.floor(x), yi=Math.floor(y), xf=x-xi, yf=y-yi; const u=xf*xf*(3-2*xf), v=yf*yf*(3-2*yf); const a=hash2(xi,yi,s),b=hash2(xi+1,yi,s),c=hash2(xi,yi+1,s),d=hash2(xi+1,yi+1,s); return a+(b-a)*u+(c-a)*v+(a-b-c+d)*u*v; }
const BAY=[0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5];
const bay=(x,y)=>(BAY[(y&3)*4+(x&3)]+0.5)/16;
const qpal=(pal,v,x,y)=>pal[clamp(Math.floor(v*(pal.length-1)+bay(x,y)),0,pal.length-1)];
const mkR=s=>()=>{ s|=0; s=s+0x6D2B79F5|0; let t=Math.imul(s^s>>>15,1|s); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; };
const fi=(n,rate,ph)=>((Math.floor(T*rate+(ph||0))%n)+n)%n;
function segD(px,py,ax,ay,bx,by){ const vx=bx-ax, vy=by-ay; const t=clamp(((px-ax)*vx+(py-ay)*vy)/(vx*vx+vy*vy||1),0,1); return Math.hypot(px-ax-vx*t,py-ay-vy*t); }
function catmull(P,steps){ const out=[]; for(let i=0;i<P.length-1;i++){ const p0=P[Math.max(0,i-1)],p1=P[i],p2=P[i+1],p3=P[Math.min(P.length-1,i+2)]; for(let k=0;k<steps;k++){ const t=k/steps,t2=t*t,t3=t2*t; const f=(a,b,c2,d)=>0.5*(2*b+(-a+c2)*t+(2*a-5*b+4*c2-d)*t2+(-a+3*b-3*c2+d)*t3); out.push([f(p0[0],p1[0],p2[0],p3[0]),f(p0[1],p1[1],p2[1],p3[1])]); } } out.push(P[P.length-1]); return out; }

/* ---------- lienzo de píxeles (mismo pincel que el pueblo de Hollin) ---------- */
function PB(w,h){ const k=zcv(w,h), x=k.getContext('2d'); const id=x.createImageData(Math.max(1,w|0),Math.max(1,h|0)), d=id.data;
  const P={w,h,k,d,
    set(px,py,col,a){ px=Math.floor(px); py=Math.floor(py); if(px<0||py<0||px>=w||py>=h||!col) return; const i=(py*w+px)*4, c=rgb(col);
      if(a==null||a>=1){ d[i]=c[0]; d[i+1]=c[1]; d[i+2]=c[2]; d[i+3]=255; return; } const da=d[i+3]/255, oa=a+da*(1-a); if(oa<=0) return;
      d[i]=(c[0]*a+d[i]*da*(1-a))/oa; d[i+1]=(c[1]*a+d[i+1]*da*(1-a))/oa; d[i+2]=(c[2]*a+d[i+2]*da*(1-a))/oa; d[i+3]=oa*255; },
    dark(px,py,k2){ px|=0; py|=0; if(px<0||py<0||px>=w||py>=h) return; const i=(py*w+px)*4; if(!d[i+3]) return; d[i]*=1-k2*0.92; d[i+1]*=1-k2*0.95; d[i+2]=Math.min(255,d[i+2]*(1-k2*0.9)); },
    alpha(px,py){ px|=0; py|=0; if(px<0||py<0||px>=w||py>=h) return 0; return d[(py*w+px)*4+3]; },
    rect(x0,y0,ww,hh,col,a){ for(let yy=y0;yy<y0+hh;yy++) for(let xx=x0;xx<x0+ww;xx++) P.set(xx,yy,col,a); },
    fn(x0,y0,ww,hh,f){ for(let yy=Math.floor(y0);yy<y0+hh;yy++) for(let xx=Math.floor(x0);xx<x0+ww;xx++){ const c=f(xx,yy); if(c) P.set(xx,yy,c); } },
    line(x0,y0,x1,y1,col,a){ x0|=0;y0|=0;x1|=0;y1|=0; const dx=Math.abs(x1-x0), dy=-Math.abs(y1-y0), sx=x0<x1?1:-1, sy=y0<y1?1:-1; let e=dx+dy; for(;;){ P.set(x0,y0,col,a); if(x0===x1&&y0===y1) break; const e2=2*e; if(e2>=dy){ e+=dy; x0+=sx; } if(e2<=dx){ e+=dx; y0+=sy; } } },
    ell(cx,cy,rx,ry,col,a){ for(let yy=Math.floor(cy-ry);yy<=cy+ry;yy++) for(let xx=Math.floor(cx-rx);xx<=cx+rx;xx++){ const u=(xx+0.5-cx)/rx, v=(yy+0.5-cy)/ry; if(u*u+v*v<=1) P.set(xx,yy,col,a); } },
    poly(pts,col,a,f){ let mn=1e9,mx=-1e9; pts.forEach(p=>{ mn=Math.min(mn,p[1]); mx=Math.max(mx,p[1]); });
      for(let yy=Math.floor(mn);yy<=mx;yy++){ const xs=[]; const sy=yy+0.5; for(let i=0;i<pts.length;i++){ const p=pts[i], q=pts[(i+1)%pts.length]; if((p[1]<=sy&&q[1]>sy)||(q[1]<=sy&&p[1]>sy)) xs.push(p[0]+(sy-p[1])/(q[1]-p[1])*(q[0]-p[0])); } xs.sort((a2,b2)=>a2-b2);
        for(let i=0;i+1<xs.length;i+=2) for(let xx=Math.round(xs[i]);xx<Math.round(xs[i+1]);xx++){ const c=f?f(xx,yy):col; if(c) P.set(xx,yy,c,a); } } },
    outline(k2){ k2=k2==null?0.55:k2; const src=new Uint8ClampedArray(d); const A=(xx,yy)=>xx>=0&&yy>=0&&xx<w&&yy<h?src[(yy*w+xx)*4+3]:0;
      for(let yy=0;yy<h;yy++) for(let xx=0;xx<w;xx++){ const i=(yy*w+xx)*4; if(src[i+3]>40) continue; let best=-1; for(const [ox,oy] of [[1,0],[-1,0],[0,1],[0,-1]]){ if(A(xx+ox,yy+oy)>200){ best=((yy+oy)*w+xx+ox)*4; break; } }
        if(best>=0){ d[i]=src[best]*(1-k2)*0.85; d[i+1]=src[best+1]*(1-k2)*0.82; d[i+2]=Math.min(255,src[best+2]*(1-k2)+12); d[i+3]=255; } } },
    done(){ x.putImageData(id,0,0); return k; } };
  return P; }
function sprite(w,h,f,ol){ const P=PB(w,h); f(P); if(ol!==false) P.outline(0.55); return P.done(); }

