/* ============================================================
   MOTOR DE ZONA: arma suelo + máscara + objetos y los cachea
   ============================================================ */
const COLW=96;
const STATE={ chests:{}, flags:{} };
// estado visible (cofres abiertos, banderas de historia). Por defecto lee G.world; el motor puede reemplazar ZONES.isOpen / ZONES.flag.
function gWorld(){ try{ return (typeof G!=='undefined'&&G&&G.world)?G.world:null; }catch(e){ return null; } }
function isOpen(id){ const w=gWorld(); return !!((w&&w.chests&&w.chests[id])||STATE.chests[id]); }
function hasFlag(k){ const w=gWorld(); if(STATE.flags[k]) return true; try{ if(typeof G!=='undefined'&&G&&G.flags&&G.flags[k]) return true; }catch(e){} return !!(w&&w.flags&&w.flags[k]); }
function caravanAt(){ const w=gWorld(); return STATE.caravan||(w&&w.caravan)||null; }

// A1 (fix 2): un árbol de primer plano que tapa a un personaje se redibuja translúcido sobre él (se ve la copa y también al grupo)
const CFADE=0.3;
// fix 3 (N3): el árbol que tapa a un personaje ya no se redibuja al 30 % recortado al rectángulo del personaje (dejaba un parche
// rectangular y follaje sobre la cara). Se redibuja con una máscara elíptica suave centrada en el cuerpo: casi transparente sobre
// cara y torso, un velo leve en el contorno (se nota que está detrás) y 0 en el borde de la elipse, así no queda ningún corte recto.
const OCCM={c:null,g:null}, OCCA=[[0,0.04],[0.45,0.07],[0.78,CFADE*0.62],[0.93,CFADE*0.3],[1,0]];
function softOcc(c,spr,os,sx,sy,iw,ih,ix,iy,ex,feet,rx,ah){ // ex,feet: centro de los pies; rx: medio ancho; ah: alto del sprite
  const pw=Math.max(1,Math.ceil(iw*os)), ph=Math.max(1,Math.ceil(ih*os));
  if(!OCCM.c){ OCCM.c=document.createElement('canvas'); OCCM.c.width=128; OCCM.c.height=192; OCCM.g=OCCM.c.getContext('2d'); }
  if(OCCM.c.width<pw||OCCM.c.height<ph){ OCCM.c.width=Math.max(OCCM.c.width,pw); OCCM.c.height=Math.max(OCCM.c.height,ph); OCCM.g=OCCM.c.getContext('2d'); }
  const g=OCCM.g; g.setTransform(1,0,0,1,0,0); g.globalAlpha=1; g.imageSmoothingEnabled=false; g.globalCompositeOperation='copy';
  g.drawImage(spr,sx,sy,pw,ph,0,0,pw,ph);
  const cy=feet-ah*0.55, ry=ah*0.55+5; // elipse de apenas debajo de los pies a apenas arriba de la cabeza
  g.globalCompositeOperation='destination-in'; g.setTransform(os,0,0,os*ry/rx,(ex-ix)*os,(cy-iy)*os);
  const gr=g.createRadialGradient(0,0,0,0,0,rx); for(const [t,a] of OCCA) gr.addColorStop(t,'rgba(0,0,0,'+a+')'); g.fillStyle=gr;
  g.fillRect(-(ex-ix)-1,-(cy-iy)*rx/ry-1,pw/os+2,(ph/os)*rx/ry+2);
  g.setTransform(1,0,0,1,0,0); g.globalCompositeOperation='source-over';
  c.drawImage(OCCM.c,0,0,pw,ph,ix,iy,iw,ih); }
