        if(sh==='poly'){ const pts=a; let mn=1e9,mx=-1e9; pts.forEach(p=>{ mn=Math.min(mn,p[1]); mx=Math.max(mx,p[1]); }); for(let y=Math.max(0,Math.floor(mn));y<=Math.min(h-1,mx);y++){ const xs=[]; const sy=y+0.5; for(let i=0;i<pts.length;i++){ const p=pts[i], q=pts[(i+1)%pts.length]; if((p[1]<=sy&&q[1]>sy)||(q[1]<=sy&&p[1]>sy)) xs.push(p[0]+(sy-p[1])/(q[1]-p[1])*(q[0]-p[0])); } xs.sort((u,v)=>u-v); for(let i=0;i+1<xs.length;i+=2) for(let x=Math.max(0,Math.round(xs[i]));x<Math.min(w,Math.round(xs[i+1]));x++) TM[y*w+x]=code; } return; }
