        const pq=(z.props||[]).find(q=>q.id===id)||{}; const hid=()=>{ if(!pq.need) return false; try{ return !WORLD.can(pq.need); }catch(e){ return false; } }; // misiones: la caja con need no se ve ni choca hasta que aparece
