      mojon(x,y){ if(S>1){ B.hobj(memo('hmojon',()=>hdMojon(S)),x,y); B.blockE(x,y-2,6,3); return; } B.obj({x,y,spr:mojonSpr(),ox:-8,oy:-26,top:0}); B.blockE(x,y-2,6,3); B.shadow(x+3,y,8,2.5,0.3); },
