    let FB=new Uint8Array(w*h), FT=new Uint8Array(w*h); for(let x=0;x<w;x++){ let run=99; for(let y=h-1;y>=0;y--){ const k=y*w+x; if(TM[k]===T_ROCK) run=Math.min(99,run+1); else run=0; FB[k]=run; } run=99; for(let y=0;y<h;y++){ const k=y*w+x; if(TM[k]===T_ROCK) run=Math.min(99,run+1); else run=0; FT[k]=run; } }
