      GI.GV=GV; GI.DV=DV; z._fld=()=>GI; const NT=hdFineTex(S); const shadeF=z.groundHD||(HP?hdGroundBio:hdGroundDefault); const P=HP||MATS.PAL; GI.HP=P; const GP=z.grassLift?memo('glift'+z.id,()=>liftPal(P.grass,z.grassLift[0],z.grassLift[1])):P.grass, FK=z.fineK||1; GI.GP=GP; GI.FK=FK;
