/* ---------- pincel de suelo genérico ---------- */
function groundPix(x,y,k,t,rd,wd,hl,fb,ft,pal,s,FH){
  const n=vn(x,y,7,s), n2=vn(x,y,2.6,s+1), hh=hash2(x,y,s);
  if(t===T_PLANKH||t===T_PLANKV){ const along=t===T_PLANKH?x:y, across=t===T_PLANKH?y:x; let v=0.62+(hash2(Math.floor(along/5),0,3)-0.5)*0.3; if(along%5===4) v=0.12; if(hash2(along>>2,across>>3,7)<0.08) v-=0.2; return qpal(C.wood,clamp(v,0,1),x,y); }
  if(t===T_BRIDGE){ const ry=Math.floor(y/5), off=(ry%2)*4, cx=Math.floor((x+off)/7); const ux=((x+off)%7)-3, uy=(y%5)-2; const e=Math.max(Math.abs(ux)/3.5,Math.abs(uy)/2.5); let v=0.68+(hash2(cx,ry,5)-0.5)*0.3-e*e*0.35-(ux+uy)*0.04; if(e>0.92) v=0.12; return qpal(C.cob,clamp(v,0,1),x,y); }
  if(wd<0&&t!==T_FORD){ const dep=-wd; if(dep<1.3&&hh<0.6) return C.foam; let v=0.86-Math.min(dep,14)/14*0.7+(n2-0.5)*0.18+(Math.sin((x+y*0.3)*0.25+n*6)>0.92?0.2:0); return qpal(pal.water,clamp(v,0,1),x,y); }
  if(t===T_FORD){ if(hh<0.05) return qpal(C.stone,0.5+n2*0.5,x,y); if(hash2(x,y,s+4)<0.07) return C.foam; return qpal(pal.water,clamp(0.72+(n2-0.5)*0.3+(wd>-3?0.15:0),0,1),x,y); }
  if(wd<2.6){ return qpal(pal.mud,clamp(0.35+(n-0.5)*0.5+wd*0.08+(hh<0.05?0.3:0),0,1),x,y); }
  if(t===T_ROCK){ const pr=pal.rock; if(fb<=FH){ // cara del acantilado: estratos, grietas verticales, borde de luz arriba y sombra al pie
      const band=Math.floor((y+vn(x,0,18,s+4)*8)/5), bx=Math.floor((x+band*3)/(6+(band%3)*2)); let v=0.5+(hash2(bx,band,s+5)-0.5)*0.32-(1-fb/FH)*0.18+(n2-0.5)*0.12;
      if(((y+Math.round(vn(x,0,18,s+4)*8))%5)===0) v-=0.2; if(hash2(bx,band,s+6)<0.12&&(x+band*3)%(6+(band%3)*2)===0) v-=0.3; if(fb>=FH-1) v+=0.28; if(fb<=2) v-=0.32; return qpal(pr,clamp(v,0,1),x,y); }
    let v=0.6+(vn(x,y,9,s+2)-0.5)*0.5+(n2-0.5)*0.22+(ft<2?0.28:(ft<4?0.12:0)); if(Math.abs(vn(x,y,13,s+7)-0.5)<0.018) v-=0.38; if(hh<0.03) v+=0.25;
    const mv=vn(x,y,11,s+9); if(mv>0.7&&hash2(x,y,s+8)<0.75) return qpal(C.moss,clamp(0.35+(mv-0.66)*3+(n2-0.5)*0.3,0,1),x,y); if(vn(x,y,6,s+11)>0.8) return qpal(pal.grass,clamp(v-0.1,0,1),x,y); return qpal(pr,clamp(v,0,1),x,y); }
  if(t===T_DEEP) return qpal(pal.water,clamp(0.2+n2*0.2,0,1),x,y);
  if(rd<0){ let v=0.5+(n-0.5)*0.45+(n2-0.5)*0.25+(rd>-2.2?-0.22:0); if(hh<0.02) v+=0.35; if(hash2(x,y,s+3)<0.025) v-=0.35; return qpal(pal.dirt,clamp(v,0,1),x,y); }
  if(rd<2&&hh<0.5) return qpal(pal.dirt,clamp(0.3+n*0.3,0,1),x,y);
  if(t===T_MUD) return qpal(C.mud,clamp(0.45+(n-0.5)*0.6+(n2-0.5)*0.3+(hh<0.03?0.3:0),0,1),x,y);
  if(t===T_YARD){ let v=0.45+(n-0.5)*0.4+(n2-0.5)*0.2; if(hh<0.03) v+=0.3; if(hash2(x,y,s+21)<0.06) return qpal(pal.grass,0.4+n2*0.3,x,y); return qpal(pal.dirt,clamp(v,0,1),x,y); }
  if(t===T_FIELD){ return ((y%6)<2)?pal.dirt[1]:qpal(pal.dirt,0.5+(hh-0.5)*0.3,x,y); }
  if(t===T_FLOOR){ let v=0.4+(n-0.5)*0.5+(n2-0.5)*0.3; if(hh<0.04) return hash2(x,y,9)<0.5?'#7a5a30':'#5a4a2a'; return qpal(pal.grass,clamp(v-0.15,0,1),x,y); }
  let v=0.52+(n-0.5)*0.62+(n2-0.5)*0.28+hl; if(hh<0.045) v+=0.3; else if(hash2(x,y+1,s)<0.045) v-=0.3;
  if(t===T_HEATH){ const hv=vn(x,y,5,s+5); if(hv>0.6&&hash2(x,y,s+6)<0.55) return qpal(C.heath,clamp(0.3+(hv-0.6)*2.2+(n2-0.5)*0.3+hl,0,1),x,y); return qpal(HEATHG,clamp(v-0.04,0,1),x,y); }
  if(t===T_MOSS){ if(vn(x,y,4,s+13)>0.48) return qpal(C.moss,clamp(v*0.85+0.1,0,1),x,y); return qpal(pal.grass,clamp(v-0.12,0,1),x,y); }
  return qpal(pal.grass,clamp(v,0,1),x,y); }

/* ============================================================
   REMASTER (fase 1): suelo HD genérico, árboles y piezas HD de MATS para zonas con ss>1
   Guía: /home/claude/gdd/las-doce-coronas-direccion-arte-v2.md (§4 proporciones, §5 materiales, §6 sombras)
   ============================================================ */
const PRGB=new Map(); function prgb(pal){ let v=PRGB.get(pal); if(!v){ v=pal.map(rgb); PRGB.set(pal,v); } return v; }
const HDO=[0,0,0];
function rampTo(pal,t,out){ const P=prgb(pal); t=(t<0?0:t>0.9999?0.9999:t)*(P.length-1); const i=t|0, f=t-i, A=P[i], B2=P[i+1]||A; out[0]=A[0]+(B2[0]-A[0])*f; out[1]=A[1]+(B2[1]-A[1])*f; out[2]=A[2]+(B2[2]-A[2])*f; return out; }
const hdFineTex=S=>MATS.fineTex(S);
function lerp3(a,b,t,out){ out[0]=a[0]+(b[0]-a[0])*t; out[1]=a[1]+(b[1]-a[1])*t; out[2]=a[2]+(b[2]-a[2])*t; return out; }
const HDA=[0,0,0], HDB=[0,0,0];
// tamaño de árbol HD (alto en px lógicos) a partir del radio de colisión r; guía §4: frondoso 1.9–2.9 alturas de personaje, pino 2.2–3
function hdTree(kind,r,x,y,S,o){ o=o||{}; const k=o.k||1, v=Math.floor(hash2(x,y,4)*2); r=r>=24?r:Math.round(r/4)*4; const key='ht'+kind+r+'_'+v+'_'+k+(o.palK||'');
  return memo(key,()=>{ const sd=r*17+v*101+(kind.length*7); const pal=o.pal||null;
    if(kind==='pine') return edgeFade(MATS.pine(Math.round(r*6.2*k),sd,S,{pal}));
    if(kind==='birch') return edgeFade(MATS.birch(Math.round(r*5.6*k),sd,S));
    if(kind==='fruit') return edgeFade(MATS.oak(Math.round(r*5*k),sd,S,{fruit:1,pal}));
    if(kind==='blossom') return edgeFade(MATS.oak(Math.round(r*5*k),sd,S,{blossom:1,pal}));
    return edgeFade(MATS.oak(Math.round(r*5.4*k),sd,S,{pal})); }); }
// fix 3 (N3): el follaje de los pinos/robles HD se sale del lienzo del sprite y quedaba cortado en recto (se veía como un
// «parche» rectangular en el bosque cerrado, sobre todo en Hondo bajo el farol). Se esfuman los bordes laterales y el de arriba.
function edgeFade(k){ try{ if(!k||!k.getContext) return k; const g=k.getContext('2d'), S=k.S||1, Wd=k.width, Ht=k.height, f=Math.max(2,Math.round(5*S));
  g.save(); g.setTransform(1,0,0,1,0,0); g.globalCompositeOperation='destination-out';
  const st=(gr)=>{ gr.addColorStop(0,'rgba(0,0,0,1)'); gr.addColorStop(0.35,'rgba(0,0,0,.55)'); gr.addColorStop(0.7,'rgba(0,0,0,.18)'); gr.addColorStop(1,'rgba(0,0,0,0)'); return gr; };
  g.fillStyle=st(g.createLinearGradient(0,0,f,0)); g.fillRect(0,0,f,Ht);
  g.fillStyle=st(g.createLinearGradient(Wd,0,Wd-f,0)); g.fillRect(Wd-f,0,f,Ht);
  g.fillStyle=st(g.createLinearGradient(0,0,0,f)); g.fillRect(0,0,Wd,f);
  g.restore(); }catch(e){} return k; }
// mojón del cuervo (piedra hincada con el cuervo tallado)
function hdMojon(S){ return MATS.sprS(20,32,S,(g,k)=>{ const R=mkR(7); const cx=10, by=30; MATS.ao(g,cx+1,by,7,1.8,0.55);
  g.beginPath(); g.moveTo(cx-6.5,by); g.lineTo(cx-6,by-17); g.quadraticCurveTo(cx-5,by-25,cx-1,by-27); g.quadraticCurveTo(cx+4,by-27.5,cx+5.6,by-21); g.lineTo(cx+6.6,by); g.closePath();
  const gr=g.createLinearGradient(cx-6,0,cx+7,0); gr.addColorStop(0,'#a8a693'); gr.addColorStop(0.45,'#7a7a6c'); gr.addColorStop(1,'#3c3e37'); g.fillStyle=gr; g.fill(); g.save(); g.clip();
  for(let i=0;i<70;i++) MATS.ell(g,cx+(R()-0.5)*13,by-R()*27,0.4+R()*0.8,0.3+R()*0.5,R()<0.5?'#4f5148':'#c0bdaa',0.35);
  for(let i=0;i<26;i++) MATS.ell(g,cx-4+R()*8,by-2-R()*6,0.9+R()*0.8,0.6,MATS.rampH(MATS.PAL.grass,0.3+R()*0.4),0.8);
  const vg=g.createLinearGradient(0,by-8,0,by); vg.addColorStop(0,'rgba(10,14,18,0)'); vg.addColorStop(1,'rgba(10,14,18,.45)'); g.fillStyle=vg; g.fillRect(0,by-8,20,8); g.restore();
  // cuervo tallado (bajo relieve: sombra abajo-derecha, luz arriba-izquierda)
  const crow=(dx,dy,col)=>{ g.fillStyle=col; g.beginPath(); g.moveTo(cx-3+dx,by-16+dy); g.quadraticCurveTo(cx-1+dx,by-20+dy,cx+2+dx,by-19+dy); g.lineTo(cx+3.4+dx,by-20.4+dy); g.lineTo(cx+2.6+dx,by-18+dy); g.quadraticCurveTo(cx+3+dx,by-14+dy,cx-0.5+dx,by-13.5+dy); g.lineTo(cx-3.6+dx,by-12+dy); g.closePath(); g.fill(); };
  crow(0.45,0.45,'#d4d0bc'); crow(0,0,'#2a2c26'); MATS.ell(g,cx+1.6,by-18.6,0.35,0.35,'#c8a040');
  k.ax=cx; k.ay=by; }); }
// suelo HD genérico: pasto / brezo / tierra / barro / agua con rampas continuas; lo demás cae al pincel viejo (convertido)
function hdGroundDefault(x,y,k,t,rd,wd,gv,dv,fine,GI,s,fb,ft,FH){ const P=MATS.PAL;
  if(t===T_PLANKH||t===T_PLANKV||t===T_BRIDGE||t===T_ROCK||t===T_FIELD||t===T_YARD||t===T_FLOOR||t===T_DEEP||t===T_FORD||t===T_MOSS) return rgb(groundPix(x|0,y|0,k,t,rd,wd,0,fb,ft,GI.pal,s,FH));
  if(wd<0){ const dep=-wd; let v=0.8-Math.min(dep,14)/14*0.62+(dv-0.55)*0.3+fine*0.5+(Math.sin(x*0.35+dv*9+y*0.06)>0.93?0.1:0); if(dep<1.2) v=0.9; return rampTo(P.water,v,HDO); }
  if(wd<2.8){ return rampTo(P.mud,0.38+(dv-0.55)*0.9+wd*0.1+fine,HDO); }
  const grassC=t===T_HEATH?rampTo(P.heathBase,gv+0.06+fine*0.8*(GI.FK||1),HDA):rampTo(GI.GP||P.grass,gv+fine*(GI.FK||1),HDA);
  if(rd<2.6){ const inside=-rd; let v=dv+fine*1.2; if(inside<2.2) v-=(2.2-inside)*0.1;
    const r1=Math.abs(inside-7.2); if(r1<1.5) v-=0.17*(1-r1/1.5); else if(r1<2.8) v+=0.05;
    if(inside>11.5) v+=0.05; const hh=hash2(x*2|0,y*2|0,s+22); if(hh<0.03) v+=0.3; else if(hh<0.055) v-=0.26;
    const dirtC=rampTo(P.dirt,v,HDB); if(rd<=-0.2) return dirtC; const tt=clamp((rd+0.2)/2.8+(dv-0.55)*1.1+fine*2,0,1); return lerp3(dirtC,grassC,tt*tt*(3-2*tt),HDO); }
  return grassC; }

