// fondo del desfiladero: paredes en estratos que bajan a la sombra, río con espuma; el puente proyecta sombra hacia el sur
function puenteChasmPx(x,y,dv,fine,HP){ const cxm=620+Math.sin(y*0.05)*6, dx=x-cxm, ad=Math.abs(dx); const sh=(y>BRG.y1&&y<BRG.y1+16)?(1-(y-BRG.y1)/16)*0.3:0; const rw=13+Math.sin(y*0.11)*3;
  if(ad<rw){ let v=0.52+Math.sin(y*0.4+dx*0.3)*0.16+fine*1.5-sh-(ad/rw)*0.18; rampTo(HP.water,v,HDO); const fv=vn(dx*1.6,y*0.35,3,77); if(fv>0.6) lerp3(HDO,FOAM,Math.min(0.85,(fv-0.6)*4)*(1-sh*2),HDO); if(ad>rw-1.4) lerp3(HDO,FOAM,0.45,HDO); return HDO; }
  const dl=x-chL(y), dr=chR(y)-x, de=Math.min(dl,dr); if(de<2.6) return rampTo(HP.rock,0.82+fine-(2.6-de)*0.04,HDO);
  const depth=clamp(de/46,0,1), wob=vn(x,0,10,6)*6, by=(y+wob)/4, band=Math.floor(by), fr=by-band; let v=0.64-depth*0.5+(hash2(Math.floor(x/4),band,5)-0.5)*0.24-sh+fine*1.2+(dv-0.55)*0.2; if(fr<0.22) v-=0.13*(1-fr/0.22); if(dx<0) v+=0.08; if(ad<rw+3) v-=0.15;
  return rampTo(HP.rock,v,HDO); }
function puenteHD(B){ const HP=B.hp, M=MATS, st=bioSt(HP); const w=B.w,h=B.h;
  // vida en las mesetas de roca (ya no caminables): peñascos, matas de monte y algún pino bajo
  const R0=mkR(5051); let n=0; for(let i=0;i<500&&n<26;i++){ const x=10+R0()*(w-20), y=8+R0()*(h-16); if(atF(B,B.TM,x,y)!==T_ROCK||atF(B,B.TM,x,y+8)!==T_ROCK||atF(B,B.TM,x,y-6)!==T_ROCK) continue; const q=R0(); let spr;
    if(q<0.45){ const r=4+(R0()*5|0); spr=memo('prk'+r+(i%2),()=>M.rock(r,r*13+i%2,2,{pal:HP.rock,moss:i%2===0})); } else if(q<0.85){ const r=4+(R0()*3|0); spr=memo('pbu'+r+(i%3),()=>M.bush(r,r*17+i%3,2,{pal:HP.scrub,flowers:i%3===0?['#f6d860','#fff4a0']:null})); } else spr=memo('ppi'+(i%2),()=>M.pine(52+(i%2)*10,i%2+5,2));
    if(B.deco(spr,x,y,{fw:6})) n++; }
  paintBio(B,HP,{tuft:16,flower:0.6,tall:3,banks:false,under:10,pebble:2.4,fernK:0.1});
  B.paint(g=>{ // adoquines del puente (piedra por piedra), cascotes al pie de las paredes, suelo chamuscado y flechas clavadas
    g.save(); g.beginPath(); g.rect(BRG.x0,BRG.y0,BRG.x1-BRG.x0,BRG.y1-BRG.y0); g.clip(); M.cobbles(g,BRG.x0-4,BRG.y0,BRG.x1-BRG.x0+8,BRG.y1-BRG.y0,{bw:15,bh:10.5,seed:505,inside:(x,y)=>x<BRG.x0+3||x>BRG.x1-3?0.5:1}); const sg=g.createLinearGradient(0,BRG.y0,0,BRG.y0+6); sg.addColorStop(0,'rgba(10,12,16,.4)'); sg.addColorStop(1,'rgba(10,12,16,0)'); g.fillStyle=sg; g.fillRect(BRG.x0,BRG.y0,BRG.x1-BRG.x0,6); g.restore();
    M.sprinkle(g,2600,5052,0,0,w,h,(x,y,R)=>{ const t=atF(B,B.TM,x,y); return t!==T_ROCK&&t!==T_CHASM&&t!==T_BRIDGE&&(atF(B,B.TM,x,y-3)===T_ROCK||atF(B,B.TM,x,y+5)===T_ROCK)&&R()<0.6?st.pebble[(R()*4)|0]:null; });
    M.softEll(g,512,140,60,16,'#140c08',0.45); M.softEll(g,505,137,34,9,'#0a0604',0.4); const R=mkR(5053); for(let i=0;i<90;i++){ const a=R()*TAU, d=Math.sqrt(R()); M.ell(g,512+Math.cos(a)*d*56,140+Math.sin(a)*d*15,0.4+R()*0.8,0.3+R()*0.4,R()<0.6?'#2a2420':'#6a625a',0.6); }
    for(let i=0;i<18;i++){ const x=420+R()*160, y=118+R()*92; if(atF(B,B.TM,x,y)===T_CHASM||atF(B,B.TM,x,y)===T_BRIDGE) continue; const a=-2.2+(R()-0.5)*0.8, L=5+R()*2; const x2=x+Math.cos(a)*L, y2=y+Math.sin(a)*L*0.6;
      g.strokeStyle='rgba(0,0,0,.3)'; g.lineWidth=0.5; g.beginPath(); g.moveTo(x+1,y); g.lineTo(x2+3,y2+1.6); g.stroke(); g.strokeStyle='#6a5a46'; g.lineWidth=0.55; g.beginPath(); g.moveTo(x,y); g.lineTo(x2,y2); g.stroke(); M.ell(g,x2,y2,1.1,0.6,'#c8c8c8',0.95,a); M.ell(g,x2-0.3,y2+0.4,0.9,0.4,'#8a8a8a',0.9,a); } }); }
function hondoHD(B){ const HP=B.hp, M=MATS, st=bioSt(HP); const w=B.w,h=B.h;
  paintBio(B,HP,{tuft:5,flower:0,tall:7,tallN:0.5,fernK:0.65,banks:false,under:5,floorTuft:0.1,pebble:0.6});
  B.paint(g=>{ // borde del sendero: raíces que cruzan, agujas y hojas, musgo; algún hongo
    M.sprinkle(g,5200,6061,0,0,w,h,(x,y,R)=>{ const rd=atF(B,B.RD,x,y); if(rd>12) return null; const q=R(); if(rd>-2&&rd<6) return q<0.12?st.root[(R()*3)|0]:(q<0.42?st.needle[(R()*3)|0]:(q<0.62?st.litter[(R()*3)|0]:(q<0.75?st.moss[(R()*3)|0]:(q<0.8?st.mush[(R()*4)|0]:null)))); return q<0.35?st.needle[(R()*3)|0]:(q<0.45?st.twig[(R()*3)|0]:null); }); }); }
function aldeaHD(B){ const HP=B.hp, M=MATS, st=bioSt(HP); const w=B.w,h=B.h;
  // contra las paredes de las cabañas (dentro de lo bloqueado por cada casa): leña apilada, tonel, hacha en un tronco
  [[134,156],[300,138],[566,148],[140,408]].forEach(([x,y],i)=>B.deco(memo('astackU'+i,()=>upS(hdWoodStack(2*1.3,20+i),1.3)),x,y,{fw:8}));
  B.deco(memo('abarrel',()=>MATS.barrel(2,71,{water:1})),48,156,{fw:5}); B.deco(memo('abarrel2',()=>MATS.barrel(2,72)),480,148,{fw:5});
  animHens(B,[[180,200],[294,190],[600,206]]);
  paintBio(B,HP,{tuft:18,flower:0.6,tall:4,lily:0.4,bankReed:3,under:16,yardTuft:0.05});
  B.paint(g=>{ // aserrín y astillas alrededor del aserradero y los tocones, paja en el patio, rocío que brilla
    const R=mkR(7071); for(let i=0;i<900;i++){ const a=R()*TAU, d=Math.sqrt(R()); const x=548+Math.cos(a)*d*96, y=418+Math.sin(a)*d*36; M.ell(g,x,y,0.4+R()*0.6,0.3,R()<0.5?'#d8b880':'#b89460',0.8); }
    [[300,318],[430,322]].forEach(([x0,y0])=>{ for(let i=0;i<60;i++){ const a=R()*TAU, d=5+R()*16; const x=x0+Math.cos(a)*d, y=y0+Math.sin(a)*d*0.5; g.fillStyle=R()<0.5?'#c8a070':'#9a7448'; g.save(); g.translate(x,y); g.rotate(R()*TAU); g.fillRect(-1,-0.3,2+R()*1.5,0.6); g.restore(); } });
    M.sprinkle(g,1100,7072,140,190,460,150,(x,y,R)=>atF(B,B.TM,x,y)===T_YARD&&R()<0.4?st.straw[(R()*3)|0]:null);
    M.sprinkle(g,580,7073,0,0,w,h,(x,y,R)=>B.clear(x,y,4)&&R()<0.5?st.glint[0]:null); }); }

/* ---------- calcomanías reutilizables ---------- */
function decFlora(B,n,cond,kind,seed){ B.decal((P)=>{ const R=mkR(seed||n); for(let i=0;i<n;i++){ const x=R()*B.w|0, y=R()*B.h|0; if(!cond(x,y)) continue;
  if(kind==='heath'){ const n0=5+(R()*5|0); for(let k=0;k<n0;k++){ const xx=x+(R()-0.5)*8|0, yy=y+(R()-0.5)*4|0; P.set(xx,yy+2,'#2e3a22'); P.set(xx,yy+1,C.heath[1]); P.set(xx,yy,R()<0.45?C.heath[3]:C.heath[2]); if(R()<0.4) P.set(xx,yy-1,C.heath[4]); } }
  else if(kind==='flower'){ const col=C.flower[(R()*5)|0]; for(let k=0;k<4;k++){ const xx=x+(R()-0.5)*7|0, yy=y+(R()-0.5)*4|0; P.set(xx,yy,col); P.set(xx,yy+1,'#3e7a34'); } }
  else if(kind==='tuft'){ const g=C.grass; for(let k=0;k<5;k++){ P.set(x+k-2,y-(k%2)-(k===2?2:0),k===2?g[4]:g[3]); P.set(x+k-2,y,g[1]); } }
  else if(kind==='pebble'){ P.set(x,y,C.stone[3]); P.set(x+1,y,C.stone[2]); P.set(x,y+1,C.stone[1]); }
  else if(kind==='leaves'){ for(let k=0;k<6;k++) P.set(x+(R()-0.5)*8,y+(R()-0.5)*5,['#7a5a2a','#8a6a30','#5a4a24','#9a7a3a'][(R()*4)|0]); }
  else if(kind==='fern'){ const g=['#1e3a24','#2c5232','#3e6a40','#5a8a50']; for(let k=0;k<5;k++){ const a=-Math.PI/2+(k-2)*0.55; for(let r=1;r<6;r++){ const xx=x+Math.cos(a)*r*1.3|0, yy=y+Math.sin(a)*r*0.8|0; P.set(xx,yy,g[Math.min(3,1+(r>>1))]); if(r%2) P.set(xx+1,yy+1,g[0]); } } }
  else if(kind==='lily'){ P.ell(x,y,3,1.6,'#4a7a3a'); P.set(x+1,y,'#2a4a2a'); if(R()<0.4) P.set(x-1,y-1,'#f0e0f0'); }
  else if(kind==='root'){ let xx=x, yy=y; const a=R()*TAU; for(let k=0;k<14;k++){ xx+=Math.cos(a+Math.sin(k)*0.4); yy+=Math.sin(a+Math.sin(k)*0.4)*0.6; P.set(xx,yy,'#2a2016'); P.set(xx,yy-1,'#4a3a26'); } }
  else if(kind==='track'){ P.set(x,y,'#3a2e22'); P.set(x+1,y,'#3a2e22'); P.set(x-1,y-1,'#3a2e22'); P.set(x+2,y-1,'#3a2e22'); P.set(x,y-2,'#3a2e22'); P.set(x+1,y-2,'#3a2e22'); }
} }); }
function scatter(B,n,seed,cond,fn){ const R=mkR(seed); const pts=[]; for(let i=0;i<n*6&&pts.length<n;i++){ const x=8+R()*(B.w-16)|0, y=10+R()*(B.h-14)|0; if(!cond(x,y,R)) continue; if(pts.some(p=>Math.abs(p[0]-x)<14&&Math.abs(p[1]-y)<10)) continue; pts.push([x,y]); fn(x,y,R); } return pts; }

/* ---------- luz de la hora (encima de todo, también de los personajes) ---------- */
const OVC={};
function hourOverlay(key,stops,op){ if(OVC[key]) return OVC[key]; const k=zcv(W,H), x=k.getContext('2d'); const g=x.createLinearGradient(0,0,W*0.7,H); stops.forEach(s=>g.addColorStop(s[0],s[1])); x.fillStyle=g; x.fillRect(0,0,W,H); k.op=op||'source-over'; return OVC[key]=k; }
function vignetteSpr(col,a){ const key='v'+col+a; if(OVC[key]) return OVC[key]; const k=zcv(W,H), x=k.getContext('2d'); const g=x.createRadialGradient(W/2,H*0.5,W*0.25,W/2,H*0.5,W*0.7); g.addColorStop(0,rgba(col,0)); g.addColorStop(1,rgba(col,a)); x.fillStyle=g; x.fillRect(0,0,W,H); return OVC[key]=k; }
function glowSpr(col){ const key='g'+col; if(OVC[key]) return OVC[key]; const k=zcv(64,64), x=k.getContext('2d'); const g=x.createRadialGradient(32,32,0,32,32,32); g.addColorStop(0,rgba(col,1)); g.addColorStop(0.25,rgba(col,0.55)); g.addColorStop(0.6,rgba(col,0.14)); g.addColorStop(1,rgba(col,0)); x.fillStyle=g; x.fillRect(0,0,64,64); return OVC[key]=k; }
function mistSpr(col){ const key='m'+col; if(OVC[key]) return OVC[key]; const k=zcv(160,48), x=k.getContext('2d'); const R=mkR(9); for(let i=0;i<12;i++){ const g=x.createRadialGradient(0,0,0,0,0,1); g.addColorStop(0,rgba(col,0.22)); g.addColorStop(1,rgba(col,0)); x.save(); x.translate(80+(R()-0.5)*100,24+(R()-0.5)*14); x.scale(26+R()*30,8+R()*8); x.fillStyle=g; x.beginPath(); x.arc(0,0,1,0,TAU); x.fill(); x.restore(); } return OVC[key]=k; }
function cloudShadowSpr(){ if(OVC.cs) return OVC.cs; const k=zcv(220,120), x=k.getContext('2d'); const R=mkR(5); for(let i=0;i<8;i++){ const g=x.createRadialGradient(0,0,0,0,0,1); g.addColorStop(0,'rgba(10,26,40,.55)'); g.addColorStop(1,'rgba(10,26,40,0)'); x.save(); x.translate(110+(R()-0.5)*110,60+(R()-0.5)*40); x.scale(34+R()*30,20+R()*12); x.fillStyle=g; x.beginPath(); x.arc(0,0,1,0,TAU); x.fill(); x.restore(); } return OVC.cs=k; }
const PT={};
function parts(key,n,init){ if(!PT[key]){ PT[key]=[]; for(let i=0;i<n;i++) PT[key].push(init({},i)); } return PT[key]; }
function fxPollen(c,key,dt,n,col){ const P=parts(key,n,p=>{ p.x=Math.random()*W; p.y=Math.random()*H; p.ph=Math.random()*9; return p; }); c.fillStyle=col; for(const p of P){ p.x+=(6+Math.sin(T+p.ph)*4)*dt; p.y+=Math.sin(T*0.8+p.ph)*5*dt; if(p.x>W) p.x=0; const b=0.5+0.5*Math.sin(T*2+p.ph); c.globalAlpha=0.35+b*0.5; c.fillRect(p.x|0,p.y|0,1,1); } c.globalAlpha=1; }
function fxFlies(c,key,dt,n,col,cx,cy){ const P=parts(key,n,p=>{ p.x=Math.random()*(W+200)-100; p.y=Math.random()*H; p.ph=Math.random()*9; return p; }); const g=glowSpr(col); c.save(); c.globalCompositeOperation='lighter';
  for(const p of P){ p.x+=Math.sin(T*0.7+p.ph)*10*dt; p.y+=Math.cos(T*0.9+p.ph)*7*dt; const b=Math.max(0,Math.sin(T*1.6+p.ph)); if(b<0.05) continue; const sx=((p.x-cx*0.15)%(W+40)+W+40)%(W+40)-20, sy=((p.y-cy*0.15)%(H+20)+H+20)%(H+20)-10; c.globalAlpha=b*0.9; c.drawImage(g,sx-6,sy-6,12,12); c.fillStyle='#fffbe0'; c.fillRect(sx|0,sy|0,1,1); } c.restore(); c.globalAlpha=1; }
function fxMist(c,key,dt,n,col,y0,y1,a,cx){ const S=mistSpr(col); const P=parts(key,n,p=>{ p.x=Math.random()*(W+300)-150; p.y=y0+Math.random()*(y1-y0); p.v=3+Math.random()*4; p.s=0.8+Math.random()*0.8; return p; }); c.globalAlpha=a; for(const p of P){ p.x+=p.v*dt; const sx=((p.x-cx*0.4)%(W+320)+W+320)%(W+320)-160; c.drawImage(S,sx,p.y,160*p.s,48*p.s); } c.globalAlpha=1; }
function fxLeaves(c,key,dt,n,cols){ const P=parts(key,n,p=>{ p.x=Math.random()*W; p.y=Math.random()*H; p.v=10+Math.random()*10; p.ph=Math.random()*9; p.c=cols[(Math.random()*cols.length)|0]; return p; }); for(const p of P){ p.y+=p.v*dt; p.x+=Math.sin(T*1.5+p.ph)*14*dt; if(p.y>H+4){ p.y=-4; p.x=Math.random()*W; } c.fillStyle=p.c; const f=Math.sin(T*4+p.ph)>0; c.fillRect(p.x|0,p.y|0,f?2:1,f?1:2); } }
function fxButterflies(c,key,dt,n,cx,cy,zw,zh){ const P=parts(key,n,(p,i)=>{ p.x=hash2(i,1,2)*zw; p.y=hash2(i,2,2)*zh; p.ph=hash2(i,3,2)*9; p.col=['#f4f0e0','#f6d860','#e88aa8','#a8c8f0'][i%4]; return p; });
  for(const f of P){ f.x+=Math.sin(T*0.7+f.ph)*14*dt+4*dt; f.y+=Math.cos(T*0.9+f.ph*1.3)*10*dt; if(f.x>zw) f.x=0; const sx=Math.round(f.x-cx), sy=Math.round(f.y-cy+Math.sin(T*3+f.ph)*3); if(sx<-4||sy<-4||sx>W+4||sy>H+4) continue; const open=Math.sin(T*16+f.ph)>0; c.fillStyle=f.col; if(open){ c.fillRect(sx-2,sy,2,2); c.fillRect(sx+1,sy,2,2); } else { c.fillRect(sx-1,sy-1,1,2); c.fillRect(sx+1,sy-1,1,2); } c.fillStyle='#2a2a2a'; c.fillRect(sx,sy,1,2); } }
function fxCloudShadows(c,cx,cy,zw,zh,a){ const cs=cloudShadowSpr(); c.globalAlpha=a; for(let i=0;i<3;i++){ const wx=((T*7+i*420)%(zw+440))-220, wy=((T*3+i*260)%(zh+240))-120; const sx=wx-cx, sy=wy-cy; if(sx>W||sy>H||sx<-220||sy<-120) continue; c.drawImage(cs,sx,sy); } c.globalAlpha=1; }
function fxBirds(c,key,dt,n){ const P=parts(key,n,(p,i)=>{ p.x=-hash2(i,4,2)*600; p.y=30+hash2(i,5,2)*140; p.v=30+hash2(i,6,2)*14; p.ph=i; return p; }); c.fillStyle='#2a2630'; for(const b of P){ b.x+=b.v*dt; if(b.x>W+40){ b.x=-40-Math.random()*500; b.y=20+Math.random()*160; } const fl=Math.sin(T*10+b.ph)>0; const x=Math.round(b.x), y=Math.round(b.y+Math.sin(T+b.ph)*3); c.fillRect(x,y,1,1); if(fl){ c.fillRect(x-2,y-1,2,1); c.fillRect(x+1,y-1,2,1); } else { c.fillRect(x-2,y+1,2,1); c.fillRect(x+1,y+1,2,1); } } }
function fxEmbers(c,key,dt,n,wx,wy,cx,cy,spread){ const P=parts(key,n,p=>{ p.l=Math.random(); p.ox=(Math.random()-0.5)*spread; p.ph=Math.random()*9; return p; }); c.save(); c.globalCompositeOperation='lighter'; for(const p of P){ p.l+=dt*0.45; if(p.l>1){ p.l=0; p.ox=(Math.random()-0.5)*spread; } const x=wx+p.ox+Math.sin(T*2+p.ph)*6*p.l-cx, y=wy-p.l*70-cy; c.globalAlpha=(1-p.l)*0.9; c.fillStyle=p.l<0.3?'#fff0a0':'#ff8a30'; c.fillRect(x|0,y|0,1,1); } c.restore(); c.globalAlpha=1; }
// llama pixel art: 4 cuadros por tamaño, núcleo claro y lenguas que suben
function flameFrames(sz){ return memo('fl'+sz,()=>{ const out=[]; const w=sz*2+4, h=Math.round(sz*3.4)+2; const pal=['#7a1a0a','#c83a10','#ff7a1a','#ffb43a','#ffe28a','#fff8e0'];
  for(let f=0;f<4;f++){ out.push(sprite(w,h,P=>{ const cx=w/2; for(let y=0;y<h;y++) for(let x=0;x<w;x++){ const t=1-y/h; const wob=Math.sin(y*0.7+f*1.6)*sz*0.18*(1-t); const r=sz*(t<0.25?t/0.25:1)*(0.55+0.45*Math.sin(Math.min(1,(1-t))*Math.PI*0.95)); const dx=Math.abs(x+0.5-cx-wob)/Math.max(0.5,r);
      if(dx>1) continue; const tongue=hash2(x,(y+f*3)>>1,7)<0.18&&t>0.55; if(dx>0.8&&tongue) continue; const heat=(1-dx)*0.7+(1-t)*0.55+(hash2(x,y+f*5,3)-0.5)*0.25; P.set(x,y,pal[clamp(Math.floor(heat*5.2),0,5)]); } },false)); } return out; }); }
function flamePix(c,x,y,sz,ph){ const F=flameFrames(sz); const fr=F[fi(4,9,ph)]; c.drawImage(fr,Math.round(x-fr.width/2),Math.round(y-fr.height)); }
function flameAt(c,x,y,s,ph){ c.save(); c.globalCompositeOperation='lighter'; const cols=['#ff5a1a','#ff9a2a','#ffd36a','#fff2c0']; for(let k=0;k<4;k++){ const hh=(9-k*2)*s*(0.85+0.15*Math.sin(T*11+k+ph)), ww=(4-k*0.8)*s; c.fillStyle=cols[k]; c.globalAlpha=0.9; c.beginPath(); c.moveTo(x-ww,y); c.quadraticCurveTo(x-ww*0.6,y-hh*0.6,x+Math.sin(T*7+k+ph)*1.2*s,y-hh); c.quadraticCurveTo(x+ww*0.6,y-hh*0.6,x+ww,y); c.closePath(); c.fill(); } c.restore(); c.globalAlpha=1; }
// oscuridad con agujero de luz (Bosque Hondo y noches)
let DARK=null; function darkness(c,col,a,holes){ if(!DARK){ DARK=zcv(W,H); } const x=DARK.getContext('2d'); x.globalCompositeOperation='source-over'; x.clearRect(0,0,W,H); x.fillStyle=rgba(col,a); x.fillRect(0,0,W,H); x.globalCompositeOperation='destination-out';
  for(const hl of holes){ const g=x.createRadialGradient(hl.x,hl.y,hl.r*0.62,hl.x,hl.y,hl.r*1.2); g.addColorStop(0,'rgba(0,0,0,'+(hl.k||1)+')'); g.addColorStop(1,'rgba(0,0,0,0)'); x.fillStyle=g; x.fillRect(hl.x-hl.r*1.3,hl.y-hl.r*1.3,hl.r*2.6,hl.r*2.6); } x.globalCompositeOperation='source-over'; c.drawImage(DARK,0,0); }

/* ---------- animaciones de objetos (frames cacheados) ---------- */
function animSheep(B,x,y,face){ const f0=memo('sh0',()=>sheepSpr(0)), f1=memo('sh1',()=>sheepSpr(1)); const fl=face<0; const ph=hash2(x,y,2)*9; B.blockE(x,y-2,7,3); B.anim({x,y,sort:true,bx:x-10,by:y-16,bw:20,bh:17,draw:(c)=>{ const fr=Math.sin(T*1.2+ph)>0.6?f1:f0; const bob=Math.sin(T*1.2+ph)>0.6?1:0; c.save(); c.translate(x,y); if(fl) c.scale(-1,1); c.drawImage(fr,-9,-14+bob); c.restore(); }}); }
function animHorse(B,x,y,face,col){ if(!MAPA_CABALLOS) return; const k='hr'+(col?col[0]:''); const f0=memo(k+0,()=>horseSpr(0,col)), f1=memo(k+1,()=>horseSpr(1,col)); const ph=hash2(x,y,3)*9; B.blockE(x,y-3,15,4); B.shadow(x,y,15,3.5,0.25); B.anim({x,y,sort:true,bx:x-18,by:y-30,bw:36,bh:31,draw:(c)=>{ const fr=Math.sin(T*0.9+ph)>0.7?f1:f0; c.save(); c.translate(x,y); if(face<0) c.scale(-1,1); c.drawImage(fr,-17,-29); c.restore(); }}); }
function animHeron(B,x,y,face){ const f0=memo('he0',()=>heronSpr(0)), f1=memo('he1',()=>heronSpr(1)); const ph=hash2(x,y,5)*9; B.anim({x,y,sort:true,bx:x-8,by:y-26,bw:16,bh:27,draw:(c)=>{ const fr=Math.sin(T*0.5+ph)>0.85?f1:f0; c.save(); c.translate(x,y); if(face<0) c.scale(-1,1); c.drawImage(fr,-8,-25); c.restore(); c.fillStyle='rgba(216,240,246,.55)'; const s=fi(4,3,ph); c.fillRect(x-4-s,y+1,3,1); c.fillRect(x+2+s,y+1,2,1); }}); }
function animFire(B,x,y,big,vis){ if(B.hd){ B.hobj(hdFireRing(2),x,y-1,{cast:false}); B.blockE(x,y-3,10,4); B.anim({x,y,sort:true,vis,bx:x-12,by:y-30,bw:24,bh:30,draw:(c)=>{ flameAt(c,x,y-4,big||1,0); flameAt(c,x-3,y-3,(big||1)*0.6,2); flameAt(c,x+3,y-3,(big||1)*0.55,4); }}); return; } const ring=sprite(26,12,P=>{ for(let a=0;a<10;a++){ const an=a/10*TAU; const xx=13+Math.cos(an)*10, yy=6+Math.sin(an)*4; P.ell(xx,yy,2.4,1.8,qpal(C.stone,0.4+(Math.sin(an)+1)*0.25,a,0)); } P.line(7,7,19,4,C.wood[1]); P.line(7,4,19,8,C.wood[2]); P.ell(13,6,5,2,'#2a1a10'); }); B.obj({x,y:y-1,spr:ring,ox:-13,oy:-9}); B.blockE(x,y-3,10,4);
  B.anim({x,y,sort:true,vis,bx:x-12,by:y-30,bw:24,bh:30,draw:(c)=>{ flameAt(c,x,y-4,big||1,0); flameAt(c,x-3,y-3,(big||1)*0.6,2); flameAt(c,x+3,y-3,(big||1)*0.55,4); }}); }
// A2 (fix 2): un sprite de MATS armado a densidad S·sc y re-etiquetado como densidad S con medidas ×sc (mismo dibujo, más grande y nítido)
function upS(k,sc){ if(k._up||sc===1) return k; k.S=k.S/sc; k.lw*=sc; k.lh*=sc; if(k.ax!=null) k.ax*=sc; if(k.ay!=null) k.ay*=sc; k._up=sc; return k; }
function animWindmill(B,x,y,sc){ sc=sc||1; if(B.hd){ const mill=sc===1?hdMill(2):memo('hmillU'+sc,()=>{ const k=hdMill(2*sc); const M=MATS, g=k.g; if(g){ M.doorHD(g,9.6,62-24.5,12.8,24.5,{}); g.fillStyle=M.PAL.stone[5]; g.fillRect(8.6,61.2,14.8,0.8); } return upS(k,sc); });
    B.hobj(mill,x,y,{top:1}); B.block(x-11*sc,y-8*sc,22*sc,8*sc); const RB=Math.round(19*sc); const FR=[]; for(let f=0;f<6;f++) FR.push(memo('hbl'+RB+'_'+f,()=>hdBlades(RB,f/6*Math.PI/2,2)));
    B.anim({x,y:y+1,sort:true,bx:x-RB-2,by:y-50*sc-RB-2,bw:RB*2+4,bh:RB*2+4,draw:(c)=>{ const fr=FR[fi(6,5)]; c.drawImage(fr,x-fr.ax,y-50*sc-fr.ay,fr.lw,fr.lh); }}); return; }
  const tw=windmillTower(); B.obj({x,y,spr:tw,ox:-15,oy:-62,top:1}); B.block(x-11,y-8,22,8); B.shadow(x+10,y+2,16,4,0.26); const RB=17; const FR=[]; for(let f=0;f<6;f++) FR.push(memo('bl'+f,()=>bladesFr(RB,f/6*Math.PI/2)));
  B.anim({x,y:y+1,sort:true,bx:x-RB-2,by:y-56-RB,bw:RB*2+4,bh:RB*2+4,draw:(c)=>{ c.drawImage(FR[fi(6,5)],x-RB-1,y-55-RB-1); }}); }

