    importante: { label: 'Importante', bg: ['#25344f', '#1d2a42', '#162034'], hi: '#f0cf6a', lo: '#8a6420', rim: '#0b0d16', accent: '#fff3c0' },
    secreto:    { label: 'Secreto',    bg: ['#382650', '#2c1d42', '#221634'], hi: '#c9a6f0', lo: '#5e3f8a', rim: '#0c0814', accent: '#f1dcff' }
