// Lluvia de flechas sobre los objetivos (o.targets, o.n, o.dur)
def('rain',{d:1.3,lay:'over',init(e){ const o=e.o, T0=o.targets&&o.targets.length?o.targets:[{x:o.x,y:o.y,h:40}], n=o.n||60; e.ar=[]; const span=Math.max(0.2,e.dur-0.4);
  for(let i=0;i<n;i++){ const t=T0[i%T0.length]; const lx=t.x+rnd(-22,22), ly=t.y+rnd(-8,6); e.ar.push({t0:i/n*span+rnd(-0.02,0.02),fl:rnd(0.14,0.2),lx,ly,sx:lx+rnd(26,40)*(o.face>0?-1:1),sy:-24-rnd(0,30),hit:false}); } },
  tick(e){ const o=e.o; for(const r of e.ar){ if(!r.hit&&e.age>=r.t0+r.fl){ r.hit=true; burst(r.lx,r.ly-2,3,pk(o,'lacre'),{a0:-Math.PI,a1:0,v0:30,v1:80,g:200,s:[1,2],l0:0.15,l1:0.3,sh:'sq'}); } } },
  draw(c,e,p,a){ const o=e.o, k=pk(o,'lacre'), P=PAL[k]; c.globalCompositeOperation='lighter';
    for(const r of e.ar){ const ta=a-r.t0; if(ta<0) continue; if(ta<r.fl){ const q=ta/r.fl; const x=lerp(r.sx,r.lx,q), y=lerp(r.sy,r.ly-6,q); const ang=Math.atan2(r.ly-6-r.sy,r.lx-r.sx), ca=Math.cos(ang), sa=Math.sin(ang); line(c,x-ca*34,y-sa*34,x,y,1,P[3]); line(c,x-ca*18,y-sa*18,x,y,2,P[2]); line(c,x-ca*10,y-sa*10,x,y,2,P[1]); line(c,x-ca*6,y-sa*6,x,y,1,P[0]); blit(c,orbSpr(k,4),x,y,1,1,0.9); }
      else if(ta<r.fl+0.35){ const al=1-(ta-r.fl)/0.35; c.globalAlpha=al; const ang=Math.atan2(r.ly-6-r.sy,r.lx-r.sx); line(c,r.lx-6-Math.cos(ang)*8,r.ly-6-Math.sin(ang)*8,r.lx-Math.cos(ang)*1,r.ly-6+2,1,P[2]); if(ta-r.fl<0.06) star(c,r.lx,r.ly-5,5,4,0.6,P[0],1); c.globalAlpha=1; } }
    c.globalCompositeOperation='source-over'; }});
// Balanza dorada en el cielo
def('scales',{d:2.4,lay:'over',draw(c,e,p,a){ const o=e.o, P=PAL.gold; const x=o.x, y=(o.top!=null?o.top:70)+Math.round(Math.sin(a*2)*2)-Math.round((1-eOut(a/0.4))*30); const al=Math.min(1,a/0.3)*Math.min(1,(e.dur-a)/0.35);
  c.save(); c.translate(x,y); c.scale(o.scale||1.6,o.scale||1.6); c.translate(-x,-y); const tilt=a<0.9?Math.sin(a*7)*0.12*(1-a/0.9):lerp(0,0.32,eOut((a-0.9)/0.5)); c.globalAlpha=al; c.globalCompositeOperation='lighter'; blit(c,orbSpr('gold',14),x,y-8,1,1,0.35);
  line(c,x,y-22,x,y+16,2,P[2]); rect(c,x-6,y+16,12,2,P[2]); rect(c,x-2,y-25,4,4,P[1]); const L=30, bx=Math.cos(tilt)*L, by=Math.sin(tilt)*L; line(c,x-bx,y-14-by,x+bx,y-14+by,2,P[1]); rect(c,x-1,y-15,2,2,P[0]);
  for(const sg of [-1,1]){ const ex=x+sg*bx, ey=y-14+sg*by; line(c,ex,ey,ex-7,ey+14,1,P[2]); line(c,ex,ey,ex+7,ey+14,1,P[2]); for(let r=0;r<3;r++) rect(c,ex-8+r,ey+14+r,16-r*2,1,r?P[2]:P[1]); }
  c.restore(); c.globalCompositeOperation='source-over'; c.globalAlpha=1; }});
// Libro de leyes ardiendo en dorado
def('tome',{d:1.4,lay:'over',tick(e,dt){ const o=e.o, dir=o.face||-1; if(Math.random()<dt*40) part({x:o.x+dir*10+rnd(-6,6),y:o.y-(o.h||44)*0.6-4,vx:rnd(-6,6),vy:-rnd(30,60),life:rnd(0.3,0.6),s:pick([1,2]),pal:'gold',add:true,sh:'em'}); },
  draw(c,e,p,a){ const o=e.o, P=PAL.gold, dir=o.face||-1, x=Math.round(o.x+dir*10), y=Math.round(o.y-(o.h||44)*0.6+Math.sin(a*4)*1.5); const al=Math.min(1,a/0.15)*Math.min(1,(e.dur-a)/0.2); c.globalAlpha=al;
    rect(c,x-8,y-1,16,7,'#5a2a14'); rect(c,x-7,y-2,7,6,'#f4ead0'); rect(c,x+1,y-2,6,6,'#e8dcc0'); rect(c,x,y-2,1,7,'#7a4a20'); for(let i=0;i<3;i++){ rect(c,x-6,y-1+i*2,5,1,'#b89a6a'); rect(c,x+2,y-1+i*2,4,1,'#b89a6a'); }
    const pf=Math.floor(a*10)%3; if(pf) rect(c,x+(pf===1?-3:1),y-4,3,4,'#fffaf0'); c.globalCompositeOperation='lighter'; blit(c,orbSpr('gold',7),x,y,1,1,0.55); c.globalCompositeOperation='source-over'; c.globalAlpha=1; }});
// Condena / Marca sobre el objetivo
def('condena',{d:1.3,lay:'over',init(e){ const o=e.o; burst(o.x,o.y-(o.h||44)-10,10,pk(o,'holy'),{v0:30,v1:90,sh:'ln',l0:0.2,l1:0.4}); },
  draw(c,e,p,a){ const o=e.o, P=PAL[pk(o,'holy')], x=o.x, y=o.y-(o.h||44)-14, s=eOut(a/0.2)*(o.scale||1), al=Math.min(1,(e.dur-a)/0.3); c.globalAlpha=al; c.globalCompositeOperation='lighter';
    const r=11*s, rot=a*1.5; pring(c,x,y,r,r,1,P[1]); for(let i=0;i<3;i++){ const a1=rot+i*TAU/3-Math.PI/2, a2=rot+(i+1)*TAU/3-Math.PI/2; line(c,x+Math.cos(a1)*r*0.85,y+Math.sin(a1)*r*0.85,x+Math.cos(a2)*r*0.85,y+Math.sin(a2)*r*0.85,1,P[2]); }
    rect(c,x-3,y-1,6,3,P[0]); rect(c,x-1,y-1,2,3,P[3]); if(o.chains!==false){ for(let j=0;j<6;j++){ if((j+Math.floor(a*10))&1) rect(c,x-1,y+r+2+j*4,2,2,P[2]); } }
    c.globalCompositeOperation='source-over'; c.globalAlpha=1; }});
// Fragmentos (mejoras anuladas / armadura perforada)
