      const rot=a*0.9; for(let i=0;i<12;i++){ const an=rot+i/12*TAU; const g=GLY[i%GLY.length]; const gx=x+Math.cos(an)*(r2+5), gy=y+Math.sin(an)*(r2+5); for(let j=0;j<9;j++) if(g[j]) rect(c,gx-1+(j%3),gy-1+((j/3)|0),1,1,P[0]); }
      for(let i=0;i<3;i++){ const an=-a*1.6+i/3*TAU, gx=x+Math.cos(an)*r1, gy=y+Math.sin(an)*r1; rect(c,gx-1,gy-3,2,6,P[0]); rect(c,gx-3,gy-1,6,2,P[0]); }
