function validate(){ const err=[]; for(const k of REQUIRED) if(!S[k]) err.push('falta '+k);
  for(const k in S){ const q=S[k]; let last=-1; q.forEach(s=>{ if(s.t<last) err.push(k+': t decreciente'); last=s.t; if(s.fx&&!DEF[s.fx]) err.push(k+': efecto '+s.fx); });
    const e=q[q.length-1]; if(!e||!e.end) err.push(k+': sin end al final'); if(!OFFENSIVE_NOT.includes(k)&&!q.some(s=>s.hit)) err.push(k+': sin hit');
    if(OFFENSIVE_NOT.includes(k)&&!k.startsWith('st_')&&k!=='escudo_roto'&&!q.some(s=>s.apply)) err.push(k+': sin apply'); }
  return err; }
// Versión REDUCED: comprime 0,72, sin cut-in ni destellos, sacudidas ≤1,2, zoom ≤1,08, sin franjas
function get(key){ const q=S[key]; if(!q) return null; if(!red()) return q; return q.filter(s=>!s.cutin&&!s.flash&&!(s.fx==='bars'||s.fx==='speed'||s.fx==='whiteout')).map(s=>{ const n=Object.assign({},s,{t:+(s.t*0.72).toFixed(3)}); if(n.shake) n.shake=Math.min(1.2,n.shake*0.2); if(n.cam) n.cam=Object.assign({},n.cam,{zoom:Math.min(1.08,n.cam.zoom)}); if(n.dur) n.dur*=0.72; return n; }); }
