function enemy(key,name){ return ENAME[name]||basic(key); }

// Precalienta la caché: ejecuta en seco cada coreografía fuera de pantalla. Llamar FX.warm(ms) por cuadro (p. ej. 3) en menús/carga
// hasta que devuelva true, o FX.warm(Infinity) una vez al cargar el combate.
let wq=null; const wcv={}; let WS=null;
// En trozos: cada llamada avanza el ensayo paso a paso (un update + dibujo por paso) y corta al agotar el presupuesto;
// el ensayo en curso se guarda y sigue en la próxima llamada (ningún cuadro carga una coreografía entera).
function warm(budget){
  // con atlas horneado, el ensayo no hace falta: todo lo que generaría ya viene recortable (lo que falte se arma al vuelo, como antes)
  if(typeof BAKE!=='undefined'&&!FXB.skip&&BAKE.has('f','vign')){ if(BAKE.pending('f','vign')) return false; if(CACHE.has('vign')||bakedFx('vign')){ vign(); return true; } }
  if(!wq) wq=Object.keys(S).filter((k,i,arr)=>arr.indexOf(k)===i); if(!wq.length&&!WS) return true; const t0=performance.now();
  if(!wcv.g){ wcv.c=mk(W,H); wcv.g=wcv.c.getContext('2d'); } const g=wcv.g; const sL=live.splice(0), sP=parts.splice(0), sCam=Object.assign({},cam), sScr=Object.assign({},scr), sClock=clock;
  const tg=[{x:184,y:152,h:46},{x:172,y:188,h:46},{x:116,y:140,h:46}];
  try{ while(performance.now()-t0<budget){
      if(!WS){ if(!wq.length) break; WS={k:wq.shift(),fi:0,i:0,go:false,L:[],P:[],cam:null,scr:null,clock:sClock}; }
      live.push(...WS.L); parts.push(...WS.P); WS.L=[]; WS.P=[]; if(WS.cam){ Object.assign(cam,WS.cam); Object.assign(scr,WS.scr); clock=WS.clock; }
      if(!WS.go){ const face=WS.fi?1:-1; for(const st of S[WS.k]){ if(!st.fx) continue; const o=Object.assign({x:face<0?300:150,y:190,h:46,ux:300,uy:190,uh:46,tx:face<0?160:320,ty:175,th:46,face,targets:tg,uid:typeof PXS!=='undefined'?'ilian':null},st.o||{}); delete o.delay; delete o.stagger; spawn(st.fx,o); } WS.go=true; WS.i=0; }
      while(WS.i<120&&(live.length||parts.length)&&performance.now()-t0<budget){ update(1/24); drawLayer(g,'under'); drawLayer(g,'over'); drawLayer(g,'screen'); WS.i++; }
      if(WS.i>=120||!(live.length||parts.length)){ live.length=0; parts.length=0; WS.go=false; WS.cam=null; if(++WS.fi>1) WS=null; }
      else { WS.L=live.splice(0); WS.P=parts.splice(0); WS.cam=Object.assign({},cam); WS.scr=Object.assign({},scr); WS.clock=clock; break; } } }
  finally{ live.length=0; parts.length=0; live.push(...sL); parts.push(...sP); Object.assign(cam,sCam); Object.assign(scr,sScr); clock=sClock; }
  vign(); return !wq.length&&!WS; }
// lo del próximo combate primero: coreografías cuyo nombre menciona alguno de los ids
function warmPrio(ids){ if(!wq) wq=Object.keys(S).filter((k,i,arr)=>arr.indexOf(k)===i); const hit=[],rest=[]; for(const k of wq) ((ids||[]).some(id=>k.indexOf(id)>=0)?hit:rest).push(k); wq.length=0; wq.push(...hit,...rest); }
const API={spawn,update,draw,drawUnder,drawScreen,camera,clear,camTo,dimTo,flash,shake,title,get,basic,enemy,validate,seq:S,defs:DEF,warm,warmPrio,
  poseDur,drawPose,art:artGet,
  egida, EGIDA:{presets:EGP,formas:EGF,manifestar:egida,forma:egForm}, emblem:k=>k==='sena'?senaSpr():uembSpr(), PAL,
  setReduced(v){ FXR=v; }, misses(){ return MISS.splice(0); }, stats(){ return {fx:live.length,parts:parts.length,cache:CACHE.size,baked:FXB.hits}; }};
if(typeof window!=='undefined'&&window.__LDC_BAKER) window.__LDC_BAKER.FX={api:API,CACHE,reset(){ wq=null; WS=null; },skip(v){ FXB.skip=!!v; }};
