/* ============================================================
   ARTE: capa de reemplazo por PNG (window.LDC_ART) sobre PXS / PXP / ENV
   ============================================================ */
const ARTIMG=new Map();
const PREIMG=(typeof window!=='undefined'&&window.LDC_PRE)||null; // v27: el arte crítico ya bajado por js/loader.js (<img> por ruta, sin data: URI)
function artImage(src){ if(!src) return null; let im=ARTIMG.get(src); if(!im){ im=PREIMG&&PREIMG[src]; if(!im){ im=new Image(); im.src=src; } ARTIMG.set(src,im); } return (im.complete&&im.naturalWidth)?im:null; }
function artEntry(k){ return window.LDC_ART?window.LDC_ART[k]:null; }
function drawBG(c,zone,dt){ const im=artImage(artEntry('bg:'+zone)); if(im){ const sm=c.imageSmoothingEnabled; c.imageSmoothingEnabled=true; c.drawImage(im,0,0,W,H); c.imageSmoothingEnabled=sm; return; } ENV.bg(c,zone,dt); }
const LOOPA={idle:1,walk:1,talk:1,sit:1,low:1};
// silueta blanca de una hoja (para el destello de golpe)
const ARTWHITE=new Map();
function artWhite(src,im){ let w=ARTWHITE.get(src); if(w) return w; try{ w=document.createElement('canvas'); w.width=im.naturalWidth; w.height=im.naturalHeight; const g=w.getContext('2d'); g.drawImage(im,0,0); g.globalCompositeOperation='source-in'; g.fillStyle='#fff'; g.fillRect(0,0,w.width,w.height); ARTWHITE.set(src,w); return w; }catch(e){ return null; } }
/* v21 · KO apoyado en el piso (hojas PNG). Los cuadros "tendido" de la fila ko de las hojas derivadas (gen_pl.py: rot90 del cuerpo
   de pie) quedan con el pie de atrás, la capa o el arma tocando el borde de abajo y el TORSO en el aire (se veía "flotando").
   Para cada hoja (y su espejo srcL) se mide una vez el cuadro de reposo: por columna, el tramo opaco más largo (el cuerpo);
   el borde inferior de ese tramo en el 60 % central de las columnas da la línea de la espalda/torso. Todos los cuadros tendidos
   (desde a.koLie, por defecto n-4; n-5 si la fila tiene ≥12 cuadros) bajan esa diferencia, así el torso toca el piso (los
   miembros/armas que quedan más abajo se leen "hacia la cámara") y la sombra se ensancha bajo el cuerpo acostado.
   Hoja con koRest:false = sin ajuste; koRest:<número> = bajada fija en px de la hoja. */
const KOREST=new Map();
function koLie0(a,n){ return a.koLie!=null?a.koLie:(n>=12?n-5:n-4); }
function koRest(img,key,a,row,n){ let r=KOREST.get(key); if(r) return r;
  const fw=a.fw, fh=a.fh, oy=a.oy||0; r={dy:0,x0:fw*0.3,x1:fw*0.7};
  try{ const g=document.createElement('canvas'); g.width=fw; g.height=fh; const x=g.getContext('2d',{willReadFrequently:true}); x.drawImage(img,(n-1)*fw,row*fh,fw,fh,0,0,fw,fh);
    const d=x.getImageData(0,0,fw,fh).data, op=(i,j)=>d[(j*fw+i)*4+3]>40; let x0=fw, x1=-1;
    for(let i=0;i<fw;i++) for(let j=0;j<fh;j++) if(op(i,j)){ if(i<x0) x0=i; x1=i; break; }
    if(x1>=x0){ r.x0=x0; r.x1=x1; const w=x1-x0+1, bots=[];
      for(let i=x0+Math.floor(w*0.12);i<=x1-Math.floor(w*0.12);i++){ let best=0,bot=-1,j=0; while(j<fh){ if(op(i,j)){ const s=j; while(j<fh&&op(i,j)) j++; if(j-s>best){ best=j-s; bot=j-1; } } else j++; } if(best>=4) bots.push(bot); }
      if(bots.length){ bots.sort((p,q)=>p-q); const core=bots[Math.min(bots.length-1,Math.floor(bots.length*0.6))]; r.dy=clamp((fh-oy-1)-core,0,Math.round(fh*0.3)); } }
    if(typeof a.koRest==='number') r.dy=a.koRest; else if(a.koRest===false) r.dy=0;
  }catch(e){ return r; } // sin medir (p. ej. imagen todavía sin decodificar): no se guarda, se reintenta
  KOREST.set(key,r); return r; }
// variantes de hoja por capítulo: Simona lleva dos vueltas de faja desde el Cap. 3 (sprite:simonaC3, user-art/simona-128/c3)
const sprVar=id=>(id==='simona'&&typeof G!=='undefined'&&G&&(G.chap||1)>=3&&artEntry('sprite:simonaC3'))?'simonaC3':id;
const SPR={
  sheet(id){ id=sprVar(id); const a=artEntry('sprite:'+id); if(!a||!a.src) return null; const im=artImage(a.src); return im?{a,im}:null; },
  draw(c,id,x,y,o){ o=o||{};
    // B18 (provisorio hasta el arte de Brian): Olaf ya no va pintado en el hombro (se leía como un papel blanco); camina o se sienta
    // al lado de Ilian con su sprite de gato, como en combate. Con Ilian de batida (Cap. 3) no se dibuja.
    if(id==='ilian'&&o.olaf){ const fc=o.face==null?-1:(o.face<0?-1:1), off=!(G&&G.away&&G.away.ilian); o=Object.assign({},o,{olaf:false});
      // arte de Brian (21/10/2026): Olaf de pie (PixelLab) camina al lado; quieto, se sienta (el Olaf sentado de siempre)
      if(off&&!(o.anim==='ko')){ const mv=o.anim==='walk'||o.anim==='run', oa=mv?'walk':(o.dir==='n'||o.dir==='s'?'idle':'sit'); try{ SPR.draw(c,'olaf',Math.round(x-fc*(o.dir==='n'||o.dir==='s'?13:17)),Math.round(y+(o.dir==='n'?-3:2)),{anim:oa,face:fc,t:o.t,alpha:o.alpha,dir:o.dir}); }catch(e){} } }
    // NPC genéricos (js/npc.js): modelo PixelLab con variante por semilla; si la hoja no está lista, el sprite de antes
    if(o.npc!=null&&o.npc!==''&&NPCV.draw(c,id,o.npc,x,y,o)) return;
    id=sprVar(id); const s=this.sheet(id);
    if(!s){ PXS.draw(c,PXFB[id]||id,x,y,o); return; }
    const {a,im}=s; const an=a.anims||{}; let k=o.anim||'idle'; if(!an[k]) k=an.idle?'idle':Object.keys(an)[0];
    // 8 direcciones (explorando): o.dir 'e' | 's' | 'n' elige la fila de caminar de perfil, de frente o de espaldas, y la quieta de frente o de espaldas
    if(o.dir&&(k==='walk'||k==='idle')&&an[k+'_'+o.dir]) k+='_'+o.dir; else if(o.olaf&&an[k+'_o']) k+='_o'; const spec=an[k]||[0,1,1];
    const t=o.t==null?T:o.t; let f=Math.floor(t*(spec[2]||8)); f=LOOPA[k.split('_')[0]]?f%spec[1]:Math.min(spec[1]-1,f);
    const sc=(o.scale||1)*(a.sc||1), fw=a.fw, fh=a.fh, X=Math.round(x), Y=Math.round(y), bw=(k==='sit'&&a.sitBw)||a.bw||fw*0.6; // sentado real: la sombra abarca el banco
    c.save(); c.imageSmoothingEnabled=false; c.globalAlpha*=(o.alpha==null?1:o.alpha);
    // hoja espejada propia (srcL): mirando a la izquierda sin invertir (p. ej. heterocromía de Ilian)
    const left=(o.face==null?-1:o.face)<0, imL=left&&a.srcL?artImage(a.srcL):null; let img=im;
    // v21: KO tendido apoyado en el piso (ver koRest); la sombra pasa a cubrir el cuerpo acostado
    const lie=k==='ko'&&a.koRest!==false&&f>=koLie0(a,spec[1]), kr=lie?koRest(imL||im,id+(imL?'|L|':'|R|')+spec[0]+'|'+spec[1],a,spec[0],spec[1]):null, ky=kr?kr.dy:0;
    const sx0=(k==='sit'&&a.sitSx)?a.sitSx*(left?-1:1)*sc:0; // sentado real: la sombra va centrada bajo el banco
    if(o.shadow!==false&&!kr) ellipse(c,X+sx0,Y,bw*0.4*sc,bw*0.13*sc,'rgba(18,14,26,.44)'); // v17: sombra un poco más marcada (igual que PXS)
    c.translate(X,Y); if(imL) img=imL; else if(left) c.scale(-1,1);
    if(kr&&o.shadow!==false) ellipse(c,((kr.x0+kr.x1)/2-fw/2)*sc,0,Math.max(bw*0.4,(kr.x1-kr.x0)*0.44)*sc,Math.max(3,bw*0.15)*sc,'rgba(18,14,26,.44)');
    c.drawImage(img,f*fw,spec[0]*fh,fw,fh,-fw*sc/2,-(fh-(a.oy||0)-ky)*sc,fw*sc,fh*sc);
    if(o.flash>0){ const wh=artWhite(img===im?a.src:a.srcL,img); if(wh){ c.globalAlpha*=clamp(o.flash,0,1); c.drawImage(wh,f*fw,spec[0]*fh,fw,fh,-fw*sc/2,-(fh-(a.oy||0)-ky)*sc,fw*sc,fh*sc); } }
    c.restore(); },
  size(id){ id=sprVar(id); const a=artEntry('sprite:'+id); if(a&&a.fw&&this.sheet(id)){ const k=a.sc||1; return {w:Math.round((a.bw||a.fw)*k),h:Math.round((a.bh||a.fh)*k)}; } return PXS.size(PXFB[id]||id); },
  dur(id,anim,wp){ id=sprVar(id); const a=artEntry('sprite:'+id); if(a&&a.anims&&a.anims[anim]){ const s=a.anims[anim]; return s[1]/(s[2]||8); } return PXS.dur(PXFB[id]||id,anim,wp); },
  hitFrame(id,anim,wp){ id=sprVar(id); const a=artEntry('sprite:'+id); if(a&&a.anims&&a.anims[anim]) return (a.hit&&a.hit[anim]!=null)?a.hit[anim]:this.dur(id,anim)*0.5; return PXS.hitFrame(PXFB[id]||id,anim,wp); },
  has(id){ return !!artEntry('sprite:'+id); }
};
