const hasPortrait=id=>PXP.ids.includes(id);
function nameOf(id){ return NPCNAME[id]||(PXP.name?PXP.name(id):id)||id; }
// Arte del usuario (window.LDC_ART, ver ref-art.js): bustos de ~120 px escalados CON suavizado
/* expresiones: n h a s o m t + d (determinación) y x (herido); si falta una, cae en su pariente (d→a, x→s) y después en n */
const EXPRFB={d:'a',x:'s'};
function exprChain(e){ e=e||'n'; const out=[e]; if(EXPRFB[e]) out.push(EXPRFB[e]); if(e!=='n') out.push('n'); return out; }
function artPortrait(id,expr){ for(const e of exprChain(expr)){ const s=artEntry('portrait:'+id+':'+e); if(s) return artImage(s); } return null; }
function pxpExpr(e){ const ok=(PXP.exprs||['n','h','a','s','o','m','t']); return exprChain(e).find(x=>ok.includes(x))||'n'; }
/* v26-fix M1: espera solo lo que ya vino embebido (data: URI: lo crítico, ver modules.json › refCritical); el arte diferido
   (ruta relativa) se precarga de fondo, de a 3, 1,5 s después del título y en orden de uso probable (bustos del diálogo, vecinos,
   enemigos, el resto). Si algo se usa antes, artImage lo pide en el momento y mientras tanto se dibuja el respaldo de siempre. */
function preloadArt(){ const A=window.LDC_ART||{}; const srcs=[...new Set(Object.values(A).flatMap(v=>typeof v==='string'?[v]:(v?[v.src,v.srcL,v.mask]:[])).filter(Boolean))];
  const CR=window.LDC_CRIT||{}, isNow=s=>/^data:/.test(s)||!!CR[s]; // crítico: data: URI (HTML único) o ya bajado por el cargador (v27)
  const now=srcs.filter(isNow), later=srcs.filter(s=>!isNow(s));
  if(later.length){ const pr=s=>/retrato-px/.test(s)?0:/\/npc\//.test(s)?1:/sprite/.test(s)?2:3; later.sort((a,b)=>pr(a)-pr(b));
    setTimeout(()=>{ let i=0; const next=()=>{ if(i>=later.length) return; const src=later[i++]; let im=ARTIMG.get(src); if(!im){ im=new Image(); im.src=src; ARTIMG.set(src,im); }
      if(im.complete) next(); else { im.addEventListener('load',next,{once:true}); im.addEventListener('error',next,{once:true}); } }; for(let k=0;k<3;k++) next(); },1500); }
  return Promise.all(now.map(src=>new Promise(r=>{ artImage(src); const im=ARTIMG.get(src); if(im.complete&&im.naturalWidth) r(); else { im.addEventListener('load',r,{once:true}); im.addEventListener('error',r,{once:true}); setTimeout(r,1500); } }))); }
// recorte de la cara del busto (fracciones x, y, lado) para las cabecitas y miniaturas
const FACEBOX={ilian:[.14,0,.86],nach:[.24,.08,.68],ilianNino:[.22,.12,.58],ilianNinoV:[.22,.12,.58],severo:[.22,.06,.58],maela:[.12,0,.86],lina:[.22,.06,.58]};
const FACEC=new Map();
function faceCrop(id,size){ const im=artPortrait(id,'n'); if(!im) return null; const k=id+'|'+size; if(FACEC.has(k)) return FACEC.get(k);
  const f=FACEBOX[id]||[.22,.08,.6]; const c=document.createElement('canvas'); c.width=c.height=size; const g=c.getContext('2d'); g.imageSmoothingEnabled=true; g.imageSmoothingQuality='high';
  const w=im.naturalWidth,h=im.naturalHeight; g.drawImage(im,f[0]*w,f[1]*h,f[2]*w,f[2]*w,0,0,size,size); FACEC.set(k,c); return c; }
function thumbOf(c,id,expr,size){ if(pxPortraitSrc(id)){ pxThumb(c,id,size); return; } /* menú-retratos: retrato pixel fijo (sin expresiones) */ if(PORTALIAS[id]&&!artPortrait(id,expr)) id=PORTALIAS[id]; const fc=faceCrop(id,size); if(fc){ c.drawImage(fc,0,0,size,size); return; }
  if(PXP.thumb&&hasPortrait(id)){ try{ PXP.thumb(c,id,pxpExpr(expr),size); return; }catch(e){} } const p=document.createElement('canvas'); p.width=p.height=192; paintPortrait(p.getContext('2d'),id,expr,192); c.imageSmoothingEnabled=true; c.drawImage(p,0,0,size,size); }
function paintPortrait(c,id,expr,S){
  const cv=c.canvas; if(cv&&!arguments[4]) cv._ppk=(cv._ppk||0)+1; const tk=cv?cv._ppk:0; // un pedido nuevo en el mismo lienzo cancela los reintentos del anterior
  if(!PXOFF&&!PXSPR&&pxPortraitSrc(id)){ pxPaint(c,id,S,cv,tk); return; } // menú-retratos: el retrato pixel de PixelLab en todos lados (cut-ins, busto de la ficha…), fijo
  if(PORTALIAS[id]&&!artPortrait(id,expr)) id=PORTALIAS[id];
  const im=PXSPR?null:artPortrait(id,expr); if(im){ c.save(); c.clearRect(0,0,S,S); c.imageSmoothingEnabled=true; c.imageSmoothingQuality='high'; c.drawImage(im,0,0,S,S); c.restore(); return; }
  const nv=NPCV.resolve(DLGNPC[id]||id), nseed=nv?(NPCV.lastSeed[id]||(NPCV.GEN[nv.seed]?id:nv.seed)):null, nsz=nv?NPCV.size(nv.g,nseed):null; // NPC genéricos: busto de su variante (también los que tenían retrato pintado)
  if(hasPortrait(id)&&!nsz&&!PXSPR){ c.clearRect(0,0,S,S); PXP.paint(c,id,pxpExpr(expr),S); return; }
  // aldeanos sin retrato: busto del sprite ampliado sin suavizado
  const g=c.createLinearGradient(0,0,0,S); g.addColorStop(0,'#3a4c72'); g.addColorStop(1,'#141c32'); c.fillStyle=g; c.fillRect(0,0,S,S);
  // el sprite se dibuja aparte: si todavía no está listo (PXS lo arma en segundo plano: la primera línea de Quina en el epílogo salía
  // con el cuadro vacío), se reintenta cada 120 ms mientras ese lienzo siga mostrando a la misma persona
  // hojas de arte (LDC_PL128, 43–68 px de alto): busto con la coronilla al 6 % y la mitad de arriba del cuerpo; las de PXS, como siempre
  const sid=nsz?nv.g:sprId(id), sz=nsz||SPR.size(sid), art=!!nsz||(SPR.has(sid)&&!!SPR.sheet(sid)); const k=art?Math.max(1,Math.round(S/(sz.h*0.52))):Math.max(1,Math.round(S/40)); const o=document.createElement('canvas'); o.width=o.height=S; const q=o.getContext('2d');
  q.imageSmoothingEnabled=false; q.translate(S/2,art?Math.round(S*0.06+sz.h*k):S+sz.h*k*0.32); q.scale(k,k); try{ SPR.draw(q,sid,0,0,{face:1,anim:'idle',t:0,shadow:false,npc:nsz?nseed:null}); }catch(e){}
  let any=false; try{ const d=q.getImageData(0,0,S,S).data; for(let i=3;i<d.length;i+=16) if(d[i]>40){ any=true; break; } }catch(e){ any=true; }
  if(any){ c.drawImage(o,0,0); return; }
  const n=(arguments[4]|0)+1; if(n===1) try{ if(PXS.prio) PXS.prio([PXFB[sid]||sid]); }catch(e){} // que PXS lo arme primero
  if(cv&&n<=40) setTimeout(()=>{ if(cv._ppk===tk) paintPortrait(c,id,expr,S,n); },120); }
/* B17 (pulido del Arco I): los que no tienen retrato ilustrado (reclutas del Arco I con sprite de spx.js, jefes y tropas nuevas) usan
   la MISMA cara en todos lados: busto del sprite en el diálogo, en Personajes y en las láminas, y su cabeza recortada del mismo sprite en
   Grupo y en la barra de turnos (antes PXP.head caía en una cara genérica igual para todos). Gaspar usa el retrato del comerciante. */
const PORTALIAS={}; // Gaspar tenía el retrato del comerciante (B17); con su hoja propia (LDC_PL128) su cara sale de su sprite, como los demás reclutas
const SHEAD=new Map();
function spriteHead(id,size){ const k=sprVar(sprId(id))+'|'+size; /* v26: con la variante (Simona C3) en la clave: al pasar al Cap. 3 la cabecita se rehace sin recargar */ if(SHEAD.has(k)) return SHEAD.get(k); const sid=sprId(id); if(SPR.has(sid)&&!SPR.sheet(sid)) return null; /* v26-fix M1: hoja diferida todavía en camino: no se guarda la cara de respaldo (headCanvas reintenta) */ let sz; try{ sz=SPR.size(sid); }catch(e){ return null; } if(!sz||!sz.h) return null;
  const W0=72, H0=sz.h+12, c=document.createElement('canvas'); c.width=W0; c.height=H0; const g=c.getContext('2d'); g.imageSmoothingEnabled=false;
  try{ SPR.draw(g,sid,W0/2,H0-4,{face:1,anim:'idle',t:0,shadow:false}); }catch(e){ return null; }
  let d; try{ d=g.getImageData(0,0,W0,H0).data; }catch(e){ return null; } let x0=W0,x1=-1,y0=H0,y1=-1; for(let y=0;y<H0;y++) for(let x=0;x<W0;x++) if(d[(y*W0+x)*4+3]>40){ if(x<x0)x0=x; if(x>x1)x1=x; if(y<y0)y0=y; if(y>y1)y1=y; }
  if(x1<0) return null; // el sprite todavía no está: headCanvas reintenta
  const bw=x1-x0+1, bh=y1-y0+1, hum=bh>bw*1.15; let side, cx, top;
  if(hum){ side=Math.max(14,Math.min(20,Math.round(bh*0.36))); top=y0-1; let sx=0,n=0; for(let y=y0;y<Math.min(H0,y0+6);y++) for(let x=x0;x<=x1;x++) if(d[(y*W0+x)*4+3]>40){ sx+=x; n++; } cx=n?sx/n:(x0+x1)/2; }
  else { side=Math.max(14,Math.round(Math.min(bw,bh)*0.75)); top=y0-1; cx=x1-side/2+1; }
  const o=document.createElement('canvas'); o.width=o.height=size; const q=o.getContext('2d'); q.imageSmoothingEnabled=false; const pad=1;
  q.drawImage(c,Math.round(cx-side/2),top,side,side,pad,pad,size-2*pad,size-2*pad);
  if(size<=40){ const id2=q.getImageData(0,0,size,size), D=id2.data, A=new Uint8Array(size*size); for(let i=0;i<size*size;i++) A[i]=D[i*4+3]>60?1:0; // contorno de 1 px para que se lea a 24
    for(let y=0;y<size;y++) for(let x=0;x<size;x++){ const i=y*size+x; if(A[i]) continue; if((x>0&&A[i-1])||(x<size-1&&A[i+1])||(y>0&&A[i-size])||(y<size-1&&A[i+size])){ D[i*4]=18; D[i*4+1]=12; D[i*4+2]=20; D[i*4+3]=230; } } q.putImageData(id2,0,0); }
  SHEAD.set(k,o); return o; }
function headOf(id,size){ if(pxPortraitSrc(id)){ const h=pxHead(id,size||24); if(h) return h; const sh=spriteHead(id,size||24); return sh; } /* menú-retratos: cara del retrato pixel; mientras llega, la del sprite */
  if(SPR.has(sprId(id))) return spriteHead(id,size||24); /* sin retrato pixel pero con hoja PixelLab (enemigos, tropas): cabeza recortada de esa hoja, nunca el busto viejo por código (null mientras la hoja llega) */
  const fc=faceCrop(id,size||24); if(fc) return fc; if(PORTALIAS[id]&&!artPortrait(id,'n')) return headOf(PORTALIAS[id],size);
  if(PXP.headIds&&!PXP.headIds.includes(id)) return spriteHead(id,size||24);
  try{ return PXP.head(id,size); }catch(e){ return null; } }
// B16: precalentado de los retratos y cabecitas del grupo entero (al cargar la partida y al sumar a alguien): Grupo y Personajes abren sin siluetas
function warmPartyArt(ids){ try{ ids=ids||Object.keys((G&&G.party)||{}).concat(Object.keys((G&&G.away)||{})); pxWarm(ids); /* menú-retratos: retratos pixel del grupo, ya */ const P=[]; ids.forEach(id=>{ const pid=PORTALIAS[id]&&!artPortrait(id,'n')?PORTALIAS[id]:id;
    if(PXP.headIds&&PXP.headIds.includes(pid)) [128,64,48,36,24].forEach(z=>P.push('head:'+pid+':'+z)); else [128,64,48,36,24].forEach(z=>spriteHead(id,z));
    if(hasPortrait(pid)) ['n','h','a','s','o','m','t'].forEach(e=>P.push(pid+':'+e)); }); // todas las expresiones: el cuadro de diálogo no abre con el retrato vacío
  try{ warmArt(null,ids); if(PXS.prio) PXS.prio(ids.map(sprId)); }catch(e){} // los sprites también: de ellos sale la cabecita provisoria
  ids.forEach(id=>{ let n=0; const tr=()=>{ if(spriteHead(id,48)||++n>60) return; setTimeout(tr,150); }; tr(); });
  if(P.length&&PXP.warm) PXP.warm(P); }catch(e){} npcWarm(); }
// v27 · B1 (Poseidón): las hojas de los modelos NPC genéricos (guardia, aldeanos…) se piden ya al cargar o al abrir el Libro, no en la cola de fondo
function npcWarm(){ if(AUTO) return; try{ const A=window.LDC_ART||{}; Object.keys(A).forEach(k=>{ if(k.indexOf('npcmodel:')===0&&A[k]){ artImage(A[k].src); artImage(A[k].mask); } }); }catch(e){} }
// personajes que ya aparecieron (para el Libro de retratos)
function markMet(id){ if(!id||!G||!G.flags) return; const m=G.flags.met||(G.flags.met={}); m[id]=1; }
// tamaño mínimo de texto en el canvas: 12 px reales en pantalla
const FSZ=px=>Math.max(px,Math.ceil(12/Math.max(0.3,SCALE)));
// precalentado (caché de cuadros y fondos) — se llama en fundidos y pantallas de carga
const WARMED=new Set();
function warmArt(zones,ids){ (Array.isArray(zones)?zones:[zones]).forEach(z=>{ if(z && !WARMED.has('z:'+z)){ ENV.prewarm([z]); WARMED.add('z:'+z); } });
  (ids||[]).map(sprId).forEach(id=>{ if(!WARMED.has(id) && PXS.ids.includes(id)){ PXS.warm([id]); WARMED.add(id); } });
  // cabecitas de la línea de turnos (24 y 36 px): se arman fuera del hilo del juego, en el orden en que se piden
  if(PXP.warm&&PXP.headIds) (ids||[]).forEach(id=>{ if(!WARMED.has('h:'+id) && PXP.headIds.includes(id)){ WARMED.add('h:'+id); PXP.warm(['head:'+id+':24','head:'+id+':36']); } }); }
const WARMQ=[];
function warmLater(list){ list.forEach(x=>WARMQ.push(x)); if(!warmLater.on){ warmLater.on=true; const step=()=>{ const x=WARMQ.shift(); if(x==null){ warmLater.on=false; return; } if(x==='town'){ if(!WARMED.has('town')){ ENV.town.build(); WARMED.add('town'); } } else if(x==='map'){ if(!WARMED.has('map')){ ENV.map.build(); WARMED.add('map'); } } else if(x.startsWith('z:')) warmArt(x.slice(2),[]); else warmArt(null,[x]); setTimeout(step,AUTO?0:45); }; setTimeout(step,AUTO?0:120); } }

