/* Etapa 15 (modelo de Atenea): curva 1–30. EXP de L a L+1: d(L) = redondeo a 10 de (5L²+5L+10)·(1+0,1·max(0,L−6)).
   Niveles 2 a 7 idénticos a la tabla anterior (0/40/110/220/380/600); el 8 pasa de 900 a 920. El nivel 1 no se usa. */
const EXP_TABLE=(()=>{ const t={2:0}; for(let L=2;L<30;L++) t[L+1]=t[L]+Math.round((5*L*L+5*L+10)*(1+0.1*Math.max(0,L-6))/10)*10; return t; })();
// EXP por diferencia de nivel Δ = nivel del enemigo − nivel del personaje (reemplaza el clamp(1+0,1Δ; 0,2; 2) de la Etapa 4)
const EXP_DNEG=[1,0.7,0.35,0.1,0.03];
const fExp=d=>d>=0?Math.min(1.75,1+0.15*d):(d<=-5?0.01:EXP_DNEG[-d]);
// oro y probabilidad de botín por Δ (enemigo − nivel promedio del grupo, redondeado) y por rareza: SOLO en aleatorios y rivales
// (cfg.random / cfg.rival). Los fijos (historia y de lugar) pagan oro y botín como antes y gastan el mismo LR.
const fOro=d=>d>=0?Math.min(1.5,1+0.1*d):Math.max(0.5,1+0.1*d);
const fDrop=d=>d>=0?Math.min(1.5,1+0.1*d):(d<=-3?0.25:[1,0.75,0.5][-d]);
const RARITY={comun:{exp:1,oro:1,drop:1},importante:{exp:1.5,oro:2,drop:1.5},secreto:{exp:2.5,oro:3,drop:2}};
let G;
function newGame(){
  G={cp:'prologo',oro:60,items:{pocion:5,antidoto:2,pluma:1},flags:{},sealed:[],party:{},start:Date.now(),equip:{},gear:{},order:null,codex:{enemies:{}}}; // codex: ver codexEnemy() en p4
  ['ilian','nach','maela','bertram','lina'].forEach(id=>G.party[id]=mkMember(id,2));
  ENV.flags.valdris=false; ENV.flags.carruaje=false; ENV.town.chestOpen=false;
}
function mkMember(id,lvl){ const m={id,lvl,exp:EXP_TABLE[lvl]||0,imp:0,row:CHAR[id].row,weapon:id==='ilian'?'arco':null}; if(G&&G.equip&&!G.equip[id]) G.equip[id]=Object.assign({},EQUIP.start[id]); const s=stats(m); m.pv=s.pv; m.pm=s.pm; return m; }
/* ---------- EQUIPO ----------
   G.equip[id] = {arma, arma2, armadura, accesorio} (ids de EQUIP.items o null) · G.gear[itemId] = cantidad sin equipar.
   Punto único de estadísticas: stats(m) = round(naked + crecimiento·(nivel−3)) + Σ deltas del equipo puesto.
   Ilian con dagas usa la ranura 'arma2' en lugar de 'arma' (reemplaza el "atk−4, cri+10" fijo de v1). */
function ensureEquip(g){ g=g||G; if(!g) return; if(!g.equip) g.equip={}; if(!g.gear) g.gear={}; if(g.order===undefined) g.order=null; if(!g.flags) g.flags={};
  Object.keys(g.party||{}).forEach(id=>{ if(!g.equip[id]) g.equip[id]=Object.assign({},EQUIP.start[id]); }); }
function equipOf(m){ return (G&&G.equip&&G.equip[m.id])||EQUIP.start[m.id]||{}; }
function activeSlots(m){ return [m.id==='ilian'&&m.weapon==='dagas'?'arma2':'arma','armadura','accesorio']; }
function slotsOf(id){ return id==='ilian'?['arma','arma2','armadura','accesorio']:['arma','armadura','accesorio']; }
function stats(m,over){ const nk=EQUIP.naked[m.id], g=CHAR[m.id].gr, L=m.lvl-3; const r={}; for(const k in nk) r[k]=Math.round(nk[k]+(g[k]||0)*L);
  const eq=Object.assign({},equipOf(m),over||{}); activeSlots(m).forEach(sl=>{ const it=eq[sl]&&EQUIP.items[eq[sl]]; if(it) for(const k in it.stats) r[k]+=it.stats[k]; }); return r; }
function hasTag(u,tag){ if(!u||u.side!=='p') return false; const m=u.ref||u; const eq=equipOf(m); return activeSlots(m).some(sl=>{ const it=eq[sl]&&EQUIP.items[eq[sl]]; return it&&it.tags.includes(tag); }); }
function gearAdd(id,n){ G.gear[id]=(G.gear[id]||0)+(n==null?1:n); if(G.gear[id]<=0) delete G.gear[id]; }
// al irse un personaje, sus mejoras vuelven al inventario; el equipo inicial se va con él
function memberLeaves(id){ const eq=G.equip&&G.equip[id]; if(eq) Object.values(eq).forEach(it=>{ if(it&&EQUIP.items[it]&&EQUIP.items[it].source!=='inicial') gearAdd(it); }); if(G.equip) delete G.equip[id]; delete G.party[id]; if(G.order) G.order=G.order.filter(x=>x!==id); }
// orden de formación elegido en el menú de pausa (no cambia quién entra: eso lo define cada combate)
function partyOrder(list){ if(!G.order) return list.slice(); const ix=id=>{ const i=G.order.indexOf(id); return i<0?99+list.indexOf(id):i; }; return list.slice().sort((a,b)=>ix(a)-ix(b)); }
function snapshot(){ return JSON.parse(JSON.stringify(G)); }
/* v21 · enemigos VISIBLES del mapa (rivales con nombre y grupos fijos de lugar): una vez vencidos no vuelven.
   Se marcan al ganar, DENTRO del combate (antes del autoguardado «Después de un combate» y antes de que la zona rearme sus figuras),
   siempre sobre el G vigente (el reintento tras perder reemplaza G por la foto del comienzo).
   Marcas: G.world.foes[id] (mapa) y, si es rival, G.enc.rivals[id] (encuentros). foeBeaten también acepta un flag de historia
   con el mismo id (G.world.flags / G.flags): así las partidas viejas con cualquiera de las marcas lo ven vencido. */
function foeMark(id,rival){ if(!id||!G) return; if(G.world){ (G.world.foes||(G.world.foes={}))[id]=1; }
  if(rival){ const e=G.enc||(G.enc={rivals:{},ruda:0,first:{}}); (e.rivals||(e.rivals={}))[id]=1; } }
function foeBeaten(id){ if(!id||!G) return false; const w=G.world||{}; return !!((w.foes&&w.foes[id])||(G.enc&&G.enc.rivals&&G.enc.rivals[id])||(w.flags&&w.flags[id])||(G.flags&&G.flags[id])); }
// excepción de historia: def.respawn===true (vuelve siempre) o def.respawn='<flag/need>' (vuelve solo si se cumple). Ninguno del Cap. 1 la usa.
function foeRespawns(def){ if(!def||!def.respawn) return false; if(def.respawn===true) return true; try{ return typeof can==='function'&&!!can(def.respawn); }catch(e){ return false; } }
function save(cp){ G.cp=cp; store.set('save',G); }

