    enemies:B.units.filter(v=>v.side!==side&&alive(v)),party:B.units.filter(v=>v.side===side&&alive(v)),pierce:o.pierce||null,strongest:o.strongest||null,
    setAnim:(v,a)=>{ if(a==='walk'||a==='idle'){ v.act=null; return; } setAct(v,a); },
    onHit:(info)=>{ const g=grp(info.each); const idx=seen[g]||0; seen[g]=idx+1; const k=(plans[g]||[])[idx]||0;
      if(k>0) runUpTo(g,k); else if(!AUTO) info.units.forEach(t=>{ if(alive(t)){ setAct(t,'hit'); t.kb=(t.side==='p'?5:-5); t.flash=0.7; } }); },
    onApply:(info)=>{ chain=chain.then(()=>doApply(info)); },
