/* S5: el combate no abre la pantalla hasta tener el fondo de la zona y las cabecitas de la línea de turnos
   (con atlas o Worker pueden llegar unos cuadros tarde). Tope de 6 s para no trabar nunca. No usa LR. */
async function cmbArtReady(B){ const z=B.zone, ids=[...new Set(B.units.map(sprOf))];
  const bgOk=()=>{ try{ if(artImage(artEntry('bg:'+z))) return true; }catch(e){} return !ENV._cache||!!ENV._cache[z]; };
  const hdOk=()=>ids.every(id=>[24,36].every(sz=>{ let h=null; try{ h=headOf(id,sz); }catch(e){} return !h||!h._ph; }));
  try{ ENV.prewarm([z],false,true); }catch(e){}
  // v26-fix M1: las hojas diferidas (enemigos y elenco) se piden al entrar al combate; se espera a que lleguen (mismo tope de 6 s)
  const shOk=()=>AUTO||ids.every(id=>{ const sid=sprId(id); try{ return !SPR.has(sid)||!!SPR.sheet(sid); }catch(e){ return true; } });
  const t0=performance.now(); while(!(bgOk()&&hdOk()&&shOk()) && performance.now()-t0<6000) await new Promise(r=>setTimeout(r,40));
  CMBSTAT.waits.push({zone:z,ms:Math.round(performance.now()-t0),ok:bgOk()&&hdOk()&&shOk()}); }
const CMBSTAT={waits:[]}; window.__LDC_CMB.artWaits=CMBSTAT.waits;

