function drawFigura(c,a){ moveActor(a,0); const k=a.k||1; if(k===1){ drawActor(c,a); return; } c.save(); c.translate(a.x,a.y); c.scale(k,k); c.translate(-a.x,-a.y); drawActor(c,a); c.restore(); }
