    if(ak){ AP.length=0; vis.forEach(a=>{ const q=a._rsa||(a._rsa={}); q.x=a.x-ox; q.y=a.y-oy; AP.push(q); }); try{ AMBI.ents(ents,ak,AX); }catch(e){} }
