function facing(st,name){ const F=FACE[name]||{}; const L=st.list;
  L.forEach(a=>{ if(F[a.id]!=null) a.face=F[a.id]; else if(F['*']!=null) a.face=F['*']; else { const o=L.filter(b=>b!==a); const mx=o.length?o.reduce((s,b)=>s+b.x,0)/o.length:240; a.face=mx>=a.x?1:-1; } }); }
const actorH=a=>{ if(NPCV.on(a)){ const z=NPCV.size(a.spr,NPCV.seedOf(a)); if(z) return z.h; } return SPR.size(a.spr).h; };
function moveActor(a,dt){ if(a.tw){ const p=clamp((nowMs()-a.tw.t0)/a.tw.d,0,1); a.x=a.tw.x0+(a.tw.x1-a.tw.x0)*p; a.y=a.tw.y0+(a.tw.y1-a.tw.y0)*p; a.walking=true; if(p>=1){ a.tw=null; a.walking=false; } } }
/* ---------- correr al explorar (×1,7) ----------
   Teclado: mantener la tecla «Correr» de KEYS (Shift por defecto). Táctil: botón «Correr» del pad o palanca al borde.
   Opciones › General › «Correr siempre» invierte: siempre corre y la tecla hace caminar. En AUTO (#prueba) nunca corre.
   runK(moving) da el multiplicador de velocidad; runAnim(actores,dt,k) acelera el paso de caminar de esos actores. */
const RUN={k:1.7,always:false,held:false,on:false};
try{ RUN.always=!!store.get('runAlways',false); }catch(e){}
window.__LDC_RUN=RUN; // pruebas
function setRunAlways(v){ RUN.always=!!v; try{ store.set('runAlways',RUN.always); }catch(e){} }
window.addEventListener('keydown',e=>{ if(!KEYS.capturing&&KEYS.isUp(e,'correr')) RUN.held=true; },true);
window.addEventListener('keyup',e=>{ if(KEYS.isUp(e,'correr')) RUN.held=false; },true);
window.addEventListener('blur',()=>{ RUN.held=false; });
function runWanted(){ if(AUTO) return false; const pad=(typeof PAD!=='undefined'&&PAD&&PAD.run)||false; return RUN.always!==(RUN.held||pad); }
function runK(moving){ RUN.on=!!moving&&runWanted(); return RUN.on?RUN.k:1; }
function runAnim(list,dt,k){ for(const a of list){ if(!a) continue; a.wt=(a.wt!=null&&T-a.wtT<0.2?a.wt:T)+dt*k; a.wtT=T; } }
