function drawProxy(c,p){ const a=p.olafOn; if(a.hidden) return; const x=a.x+(a.face>0?-4:4), y=a.y-(a.jump?jumpY(a):0); if(p.em){ const et=T-p.em.t0; if(et<1.7) PXS.emote(c,p.em.kind,x,y-actorH(a)-4,et); else p.em=null; } }
function setBase(x,anim){ if(!x) return; if(x.side){ x.sceneAnim=anim==='idle'?null:anim; x.sceneAt=T; return; } if(x.olafOn) return; x.base=anim==='idle'?null:anim; x.at=T; }
