  kb(KEYS.label('tabAnt')+'/'+KEYS.label('tabSig'),'pestañas'); kb('↑/↓','moverse'); kb(KEYS.label('confirmar'),'elegir'); kb(KEYS.label('cancelar'),'volver'); kb(KEYS.label('menu'),'cerrar'); kb(KEYS.label('pantalla'),'pantalla completa'); L.appendChild(ft); PZ.lastTab=null;
