function charHeader(id){ const m=G.party[id]; const h=el('div','pz-hdr'); h.appendChild(headCanvas(id,48,52));
  const t=el('div','pz-hdr-t'); const r1=el('div','pz-hdr-r'); r1.appendChild(el('b','pz-hdr-n',CHAR[id].name)); const lv=el('span','pz-hdr-lv'); lv.appendChild(el('small',null,UIT.nivelCorto+' ')); lv.appendChild(el('b',null,String(m.lvl))); r1.appendChild(lv);
  const nx=expInfo(m); const r2=el('div','pz-hdr-c',classOf(id)); const r3=el('div','pz-hdr-x'); r3.appendChild(el('span',null,nx.next==null?UIT.nivelMax:UIT.expSiguiente)); r3.appendChild(el('b',null,nx.next==null?'':String(nx.next)));
  const bar=el('div','pz-expbar'); const bi=el('i'); bi.style.width=(nx.f*100)+'%'; bar.appendChild(bi);
  t.append(r1,r2,r3,bar); h.appendChild(t); return h; }

/* ---------- Ficha de personaje (maquetación de la hoja de retratos) ---------- */
const EXPR6=['n','h','a','s','o','t'];
/* variantes de una misma persona: una sola entrada en el Libro, con la variante elegible dentro */
const VARIANTS={ilianNino:[['ilianNino','Antes del derrumbe'],['ilianNinoV','Después del derrumbe']],olaf:[['olaf','Ahora'],['olafNino','En el prólogo']]};
const VAROF={ilianNinoV:'ilianNino',olafNino:'olaf'};
let PERSONS=null; function persons(){ if(!PERSONS){ const ord=(typeof FICHAS!=='undefined'&&FICHAS.orden)||PXP.ids; PERSONS=ord.filter(id=>!VAROF[id]); } return PERSONS; }
function personNo(id){ const i=persons().indexOf(VAROF[id]||id); return i>=0?i+1:0; }
function variantsOf(p){ return VARIANTS[p]||[[p,'']]; }
function personMet(met,p){ return variantsOf(p).some(v=>met&&met[v[0]]); }
const FICON={edad:'age',raza:'race',clase:'sword',faccion:'banner'};
const PALC=new Map();
// paleta: del arte del usuario si lo hay (colores dominantes del busto); si no, PXP.palette
function paletteOf(id){ const pk=pxPortraitSrc(id)||''; if(PALC.has(id+pk)) return PALC.get(id+pk); let out=null; const im=pxPortraitImg(id)||(pk?null:artPortrait(id,'n')); if(pk&&!im) return []; // menú-retratos: paleta del retrato pixel
  if(im){ try{ const k=document.createElement('canvas'); k.width=k.height=28; const g=k.getContext('2d'); g.drawImage(im,0,0,28,28); const d=g.getImageData(0,0,28,28).data; const cnt=new Map();
      for(let i=0;i<d.length;i+=4){ if(d[i+3]<200) continue; const q=((d[i]>>4)<<8)|((d[i+1]>>4)<<4)|(d[i+2]>>4); cnt.set(q,(cnt.get(q)||0)+1); }
      const sorted=[...cnt.entries()].sort((a,b)=>b[1]-a[1]).map(e=>[((e[0]>>8)&15)*17,((e[0]>>4)&15)*17,(e[0]&15)*17]); const pick7=[];
      for(const c of sorted){ if(pick7.every(p=>Math.abs(p[0]-c[0])+Math.abs(p[1]-c[1])+Math.abs(p[2]-c[2])>90)) pick7.push(c); if(pick7.length>=7) break; }
      out=pick7.map(c=>'#'+c.map(v=>v.toString(16).padStart(2,'0')).join('')); }catch(e){ out=null; } }
  if(!out&&PXP.palette){ try{ out=PXP.palette(id); }catch(e){} }
  out=(out||[]).slice(0,7); PALC.set(id+pk,out); return out; }
const fval=v=>(!v||v==='s/d')?'—':v;
function fichaData(id){ const F=(typeof FICHAS!=='undefined'&&FICHAS[id])||{}; return {numero:personNo(id)||F.numero||0,nombre:F.nombre||nameOf(id),edad:fval(F.edad),raza:fval(F.raza),clase:fval(F.clase),faccion:fval(F.faccion),cita:F.cita||''}; }
function fichaCard(id,big){
  const d=fichaData(id); const fc=el('div','fc'+(big?' big':''));
  const bust=el('div','fc-bust'); const bc=el('canvas','fc-bustc'); bc.width=bc.height=256; paintPortrait(bc.getContext('2d'),id,'n',256); panimBind(bc,id,'bust'); bust.appendChild(bc); fc.appendChild(bust);
  const main=el('div','fc-main');
  const tt=el('div','fc-title'); tt.appendChild(el('b',null,String(d.numero).padStart(2,'0')+'.')); tt.appendChild(document.createTextNode(' '+d.nombre)); main.appendChild(tt);
  const at=el('div','fc-attrs'); [['edad','Edad'],['raza','Raza'],['clase','Clase'],['faccion','Facción']].forEach(([k,lab])=>{ const r=el('div','fc-at'); r.appendChild(el('i','ic ic-'+FICON[k])); const t=el('span'); t.appendChild(el('b',null,lab+': ')); t.appendChild(document.createTextNode(d[k])); r.appendChild(t); at.appendChild(r); }); main.appendChild(at);
  const th=el('div','fc-thumbs'+(pxPortraitSrc(id)?' one':'')); (pxPortraitSrc(id)?['n']:EXPR6).forEach(e=>{ const c=el('canvas','fc-th'); c.width=c.height=64; thumbOf(c.getContext('2d'),id,e,64); th.appendChild(c); }); main.appendChild(th); // menú-retratos: el retrato pixel es fijo: una sola cara en vez de seis expresiones
  const pl=el('div','fc-pal'); paletteOf(id).forEach(col=>{ const dot=el('i'); dot.style.background=col; pl.appendChild(dot); }); main.appendChild(pl);
  fc.appendChild(main);
  const body=el('div','fc-body'); body.appendChild(cardCanvas(id,300,420)); fc.appendChild(body);
  if(d.cita) fc.appendChild(el('div','fc-quote','«'+d.cita+'»'));
  return fc; }
function tabFichas(B){
  const id=PZ.sel, m=G.party[id], s=stats(m), P=MENUTXT.profiles[id]||{};
  const left=el('div','pz-col pz-left'); left.appendChild(charHeader(id)); B.appendChild(left); charStrip(left);
  const right=el('div','pz-col pz-right pz-fright'); right.appendChild(fichaCard(id));
  const low=el('div','pz-flow');
  const sc=el('div','pz-fstats');
  const st=el('div','pz-stats'); const help=el('div','pz-help',MENUTXT.stats.pv.help);
  SKEYS.forEach(k=>{ const row=btn('pz-st',null,()=>{ help.textContent=MENUTXT.stats[k].help; }); row.addEventListener('focus',()=>{ help.textContent=MENUTXT.stats[k].help; }); row.addEventListener('pointerenter',()=>{ help.textContent=MENUTXT.stats[k].help; });
    row.setAttribute('aria-label',MENUTXT.stats[k].label+' '+s[k]+', crecimiento '+EQUIP.grades[id][k]);
    row.appendChild(el('span','pz-st-l',MENUTXT.stats[k].label));
    const v=k==='pv'?m.pv+'/'+s.pv:(k==='pm'?m.pm+'/'+s.pm:String(s[k])); row.appendChild(el('span','pz-st-v',v));
    const bar=el('span','pz-st-b'); const bi=el('i'); bi.style.width=clamp(s[k]/SMAX[k]*100,2,100)+'%'; bar.appendChild(bi); row.appendChild(bar);
    const gr=EQUIP.grades[id][k]; row.appendChild(el('span','pz-gr g'+gr,gr)); st.appendChild(row); });
  sc.appendChild(el('div','pz-cap',UIT.crecimiento+' · '+UIT.clase+': '+classOf(id))); sc.appendChild(st); sc.appendChild(help); low.appendChild(sc);
  const pf=el('div','pz-prof'); const spr=el('div','pz-big'); spr.appendChild(sprCanvas(id,60,66,3,{anim:'victory',face:1})); pf.appendChild(spr);
  const tx=el('div','pz-prof-t'); if(P.epithet) tx.appendChild(el('div','pz-epi',P.epithet)); if(P.bio) tx.appendChild(el('p','pz-bio',P.bio)); if(P.likes){ const l=el('p','pz-likes'); l.appendChild(el('b',null,UIT.gustos+': ')); l.appendChild(document.createTextNode(P.likes)); tx.appendChild(l); }
  pf.appendChild(tx); low.appendChild(pf); right.appendChild(low); B.appendChild(right);
}
/* ---------- Libro de retratos ---------- */
function bookGrid(met,onOpen){
  const g=el('div','lb-grid'); try{ npcWarm(); }catch(e){}
  persons().forEach((p,i)=>{ const known=personMet(met,p); const id=known?variantsOf(p).find(v=>met[v[0]])[0]:p; const d=fichaData(id); const b=btn('lb-card'+(known?'':' unk'),null,()=>{ if(known) onOpen(p); else toast('Todavía no lo conociste.',1600); },{label:known?d.nombre:'Personaje desconocido'});
    if(i===0) b.dataset.focus='1';
    const c=known?cxThumb('lb-th',id,'n',96):el('canvas','lb-th'); if(!known) c.width=c.height=96; const g2=c.getContext('2d'); // cxThumb reintenta hasta que llega (antes Tessa, Odo, Bram… quedaban vacíos: PXP.thumb se arma fuera del hilo y no se repintaba)
    if(!known){ g2.clearRect(0,0,96,96); g2.fillStyle='#1c140d'; g2.fillRect(0,0,96,96); g2.fillStyle='#0a0705'; g2.beginPath(); g2.arc(48,40,19,0,Math.PI*2); g2.fill(); g2.beginPath(); g2.moveTo(10,96); g2.quadraticCurveTo(14,62,48,60); g2.quadraticCurveTo(82,62,86,96); g2.closePath(); g2.fill(); g2.fillStyle='#6a5236'; g2.font='bold 26px Georgia,serif'; g2.textAlign='center'; g2.textBaseline='middle'; g2.fillText('?',48,42); }
    b.appendChild(c); const t=el('div','lb-t'); t.appendChild(el('b',null,String(d.numero||i+1).padStart(2,'0')+'. '+(known?d.nombre:'???'))); t.appendChild(el('small',null,known?d.clase:'')); b.appendChild(t); g.appendChild(b); });
  return g; }
function bookBig(host,p,met){ met=met||{}; const vs=variantsOf(p); let id=(vs.find(v=>met[v[0]])||vs[0])[0];
  const ov=el('div','lb-big'); ov.setAttribute('role','dialog'); ov.setAttribute('aria-label','Ficha de '+fichaData(id).nombre);
  const close=btn('pz-x lb-x',UIT.volver,()=>{ ov.remove(); const f=host.querySelector('.lb-card'); if(f) f.focus({preventScroll:true}); }); ov.appendChild(close);
  const wrap=el('div','lb-wrap'); ov.appendChild(wrap);
  const show=()=>{ wrap.textContent=''; if(vs.length>1){ const bar=el('div','lb-var'); bar.setAttribute('role','group'); bar.setAttribute('aria-label','Variante');
      vs.forEach(([v,lab])=>{ const ok=!!met[v]; const b=btn('lb-vb'+(v===id?' on':''),ok?lab:'???',()=>{ id=v; show(); },{disabled:!ok}); b.setAttribute('aria-pressed',String(v===id)); bar.appendChild(b); }); wrap.appendChild(bar); }
    wrap.appendChild(fichaCard(id,true)); };
  show(); host.appendChild(ov); setTimeout(()=>close.focus({preventScroll:true}),30); }
function tabLibro(B){ const col=el('div','pz-col pz-book'); const met=G.flags.met||{}; col.appendChild(el('div','pz-cap','Libro de retratos · '+persons().filter(p=>personMet(met,p)).length+' / '+persons().length)); col.appendChild(bookGrid(met,p=>bookBig(PZ.L,p,met))); B.appendChild(col); }
// desde el título, con los datos de la partida guardada
function openBook(met){ return new Promise(res=>{ const L=mkLayer('book','Libro de retratos'); const close=()=>{ dropLayer(L); res(); }; L._close=close;
  const head=el('div','pz-head'); head.appendChild(el('div','pz-title','Libro de retratos')); head.appendChild(el('div','pz-sp')); head.appendChild(btn('pz-x','Salir',close)); L.appendChild(head);
  const body=el('div','pz-body t-libro'); const col=el('div','pz-col pz-book'); col.appendChild(el('div','pz-cap','Personajes conocidos · '+persons().filter(p=>personMet(met||{},p)).length+' / '+persons().length)); col.appendChild(bookGrid(met||{},p=>bookBig(L,p,met||{}))); body.appendChild(col); L.appendChild(body);
  const f=body.querySelector('.lb-card'); if(f&&!AUTO) f.focus({preventScroll:true}); if(AUTO) setTimeout(close,2); }); }

/* ---------- Equipo ---------- */
function statDiff(m,slot,newId){ const mm=Object.assign({},m); if(m.id==='ilian') mm.weapon=slot==='arma2'?'dagas':(slot==='arma'?'arco':m.weapon); const a=stats(mm), b=stats(mm,{[slot]:newId||null}); const out=[]; SKEYS.forEach(k=>{ if(a[k]!==b[k]) out.push([k,a[k],b[k]]); }); return {a,b,out}; }
function diffChips(d){ const w=el('span','pz-diff'); if(!d.out.length){ w.appendChild(el('span','eq',UIT.igual)); return w; } d.out.forEach(([k,a,b])=>{ const c=el('span',b>a?'up':'dn',(b>a?'▲ ':'▼ ')+MENUTXT.stats[k].label+' '+(b>a?'+':'')+(b-a)); w.appendChild(c); }); return w; }
function tagNote(it){ const d=EQUIP.items[it]; return d&&d.tags.length?itemDesc(it):''; }
function equipItem(id,slot,itemId){ const eq=G.equip[id]; const cur=eq[slot]; if(cur===itemId) return false; if(cur) gearAdd(cur); if(itemId) gearAdd(itemId,-1); eq[slot]=itemId||null; const m=G.party[id]; const s=stats(m); m.pv=Math.min(m.pv,s.pv); m.pm=Math.min(m.pm,s.pm); return true; }
function tabEquipo(B){
  const id=PZ.sel, m=G.party[id], eq=G.equip[id];
  const left=el('div','pz-col pz-left'); left.appendChild(charHeader(id)); charStrip(left,null,'mini'); B.appendChild(left);
  const mid=el('div','pz-col pz-eqmid'); const big=el('div','pz-big pz-eqspr'); big.appendChild(sprCanvas(id,60,66,3,{anim:'idle',face:1})); mid.appendChild(big);
  const slots=el('div','pz-slots');
  ['arma','arma2','armadura','accesorio'].forEach(sl=>{ if(sl==='arma2'&&id!=='ilian') return; const blocked=id==='simona'&&sl==='arma';
    const b=btn('pz-slot'+(PZ.slot===sl?' on':''),null,()=>{ PZ.slot=PZ.slot===sl?null:sl; renderPause(); const f=PZ.body.querySelector('.pz-opt'); if(f) f.focus({preventScroll:true}); },{disabled:blocked});
    if(!PZ.slot&&!slots.querySelector('[data-focus]')&&!blocked) b.dataset.focus='1';
    if(eq[sl]&&!blocked) b.appendChild(itemIcon(eq[sl],'gear',30)); else { const w=el('span','iv-ic empty'); w.style.setProperty('--px','30px'); w.appendChild(el('i','ic ic-'+({arma:id==='ilian'?'bow':'sword',arma2:'sword',armadura:'shield',accesorio:'star'}[sl]))); b.appendChild(w); }
    const t=el('span','pz-slot-t'); t.appendChild(el('small',null,slotLabel(id,sl)+(id==='ilian'&&(sl==='arma'||sl==='arma2')&&activeSlots(m).includes(sl)?' · en uso':''))); t.appendChild(el('b',null,blocked?UIT.noPuedeEquipar:(eq[sl]?itemName(eq[sl]):UIT.sinEquipo))); b.appendChild(t); slots.appendChild(b); });
  mid.appendChild(slots);
  const tot=el('div','pz-stats mini'); const s=stats(m); SKEYS.forEach(k=>{ const r=el('div','pz-st'); r.appendChild(el('span','pz-st-l',MENUTXT.stats[k].label)); r.appendChild(el('span','pz-st-v',String(k==='pv'?s.pv:k==='pm'?s.pm:s[k]))); tot.appendChild(r); }); tot.dataset.role='totals'; mid.appendChild(tot);
  B.appendChild(mid);
  const right=el('div','pz-col pz-right pz-eqlist');
  if(!PZ.slot){ right.appendChild(el('div','pz-cap','Lleva puesto')); const cl=el('div','eq-cur');
    ['arma','arma2','armadura','accesorio'].forEach(sl=>{ if(sl==='arma2'&&id!=='ilian') return; const it=eq[sl]; const r=el('div','eq-ci'+(it?'':' none')); r.appendChild(it?itemIcon(it,'gear',32):el('span','iv-ic none','—'));
      const t=el('div','iv-rt'); t.appendChild(el('small',null,slotLabel(id,sl))); t.appendChild(el('b',null,it?itemName(it):UIT.sinEquipo)); if(it) t.appendChild(el('p',null,itemDesc(it))); r.appendChild(t); cl.appendChild(r); });
    right.appendChild(cl); const spare=Object.keys(G.gear).filter(it=>G.gear[it]>0&&['arma','arma2','armadura','accesorio'].some(sl=>itemFits(it,id,sl)));
    right.appendChild(el('p','pz-hint',spare.length?('En la mochila hay '+spare.length+' pieza'+(spare.length>1?'s':'')+' que '+CHAR[id].name+' puede usar. Elegí una ranura para comparar.'):'Elegí una ranura para ver las piezas que puede usar.')); }
  else { const sl=PZ.slot; right.appendChild(el('div','pz-cap',slotLabel(id,sl)+' · '+UIT.comparar));
    const cur=eq[sl]; const opts=[];
    if(cur) opts.push({it:cur,cur:true});
    Object.keys(G.gear).filter(it=>G.gear[it]>0&&itemFits(it,id,sl)&&it!==cur).forEach(it=>opts.push({it,n:G.gear[it]}));
    if(cur) opts.push({it:null});
    const det=el('div','pz-det');
    const show=o=>{ det.innerHTML=''; if(o.it){ det.appendChild(el('b',null,itemName(o.it))); det.appendChild(el('p',null,itemDesc(o.it))); det.appendChild(el('small',null,UIT.sources[EQUIP.items[o.it].source]||'')); } else det.appendChild(el('p',null,UIT.quitar+': '+itemName(cur)));
      const d=statDiff(m,sl,o.it); tot.querySelectorAll('.pz-st').forEach((r,i)=>{ const k=SKEYS[i]; const v=r.querySelector('.pz-st-v'); const a=d.a[k], b=d.b[k]; v.textContent=a===b?String(a):a+' → '+b+(b>a?' ▲':' ▼'); v.className='pz-st-v'+(b>a?' up':(b<a?' dn':'')); }); };
    const list=el('div','pz-opts');
    opts.forEach((o,i)=>{ const b=btn('pz-opt'+(o.cur?' cur':''),null,()=>{ if(o.cur) return; equipItem(id,sl,o.it); sfx('heal'); const L=MENUTXT.equipLines[id]; const txt=L?pick(L):''; PZ.slot=null; renderPause(); const host=PZ.body.querySelector('.pz-eqspr'); if(host&&txt&&o.it) bubbleOn(host,txt); const f=PZ.body.querySelector('.pz-slot'); if(f) f.focus({preventScroll:true}); });
      if(i===0) b.dataset.focus='1';
      if(o.it) b.appendChild(itemIcon(o.it,'gear',26)); else b.appendChild(el('span','iv-ic none','✕'));
      b.appendChild(el('span','pz-opt-n',o.it?itemName(o.it):UIT.quitar));
      b.appendChild(el('span','pz-opt-c',o.cur?UIT.actual:(o.it?'×'+o.n:'')));
      b.appendChild(diffChips(statDiff(m,sl,o.it)));
      b.addEventListener('focus',()=>show(o)); b.addEventListener('pointerenter',()=>show(o)); list.appendChild(b); });
    if(opts.length===0) list.appendChild(el('p','pz-hint',UIT.sinEquipo));
    right.appendChild(list); right.appendChild(det); if(opts[0]) show(opts[0]); }
  B.appendChild(right);
}

/* ---------- íconos de objetos (ICONS de icons.js si existe; si no, los íconos de píxel de siempre) ---------- */
function ICX(){ try{ if(typeof ICONOS!=='undefined'&&ICONOS&&typeof ICONOS.el==='function') return ICONOS; }catch(e){} const w=window.LDC_ICONOS; return (w&&typeof w.el==='function')?w:null; }
function gearCat(it){ const d=EQUIP.items[it]||{}; if(d.slot==='armadura') return 'armadura'; if(d.slot==='accesorio') return 'accesorio'; const n=(itemName(it)||'').toLowerCase();
  return /arco|ballesta/.test(n)?'arco':/lanza|alabarda/.test(n)?'lanza':/daga/.test(n)?'daga':'espada'; }
function pixIc(it,kind){ if(kind==='item') return it==='pluma'?'feather':'potion'; if(kind==='key') return 'star'; const d=EQUIP.items[it]||{}; return d.slot==='armadura'?'shield':d.slot==='accesorio'?'star':(gearCat(it)==='arco'?'bow':'sword'); }
// ícono de un objeto: ICONOS (icons.js) si está; si no, el glifo de píxel de la UI. Rareza → color del marco (comun/importante/secreto).
function itemIcon(it,kind,px){ px=px||32; const w=el('span','iv-ic'); w.style.setProperty('--px',px+'px'); const IC=ICX();
  const png=!!(IC&&IC.pngReady&&IC.pngReady(it)); // PNG de PixelLab si lo hay (también objetos clave); si no, el de código
  if(IC&&(kind!=='key'||png)){ try{ const S=png?IC.pngSize(px):(px>36?48:px>26?32:24); const c=IC.el(it,S); if(c){ c.classList.add('iv-icc'); c.style.width=c.style.height=px+'px'; w.appendChild(c); const r=IC.rarity&&IC.rarity(it); if(r) w.dataset.r=r; return w; } }catch(e){} }
  const i=el('i','ic ic-'+pixIc(it,kind)); w.appendChild(i); return w; }
// ícono PNG solo si existe (tienda, botín y cofres): si no, null y el que llama deja lo de antes
function pngIcon(it,kind,px){ const IC=ICX(); if(!(IC&&IC.pngReady&&IC.pngReady(it))) return null; return itemIcon(it,kind,px); }
// cofres y recompensas: tira breve con los íconos de lo que se recibe (los ids sin PNG usan el de código; sin ICONOS, no se muestra)
function lootPop(ids){ try{ if(AUTO||!ids||!ids.length) return; const IC=ICX(); if(!IC) return; const L=ids.filter(k=>k&&k!=='oro'); if(!L.length) return;
  const old=document.querySelector('.loot-pop'); if(old) old.remove(); const box=el('div','loot-pop'); box.setAttribute('aria-hidden','true');
  L.slice(0,8).forEach(k=>{ const kind=EQUIP.items[k]?'gear':(String(k).startsWith('key_')?'key':'item'); box.appendChild(itemIcon(k,kind,32)); });
  (UI.stage||document.body).appendChild(box); requestAnimationFrame(()=>box.classList.add('on')); setTimeout(()=>{ box.classList.remove('on'); setTimeout(()=>box.remove(),400); },2600*Math.max(SPEED,0.05)); }catch(e){} }
function meter(cls,lab,a,b,extra){ const r=el('div','gp-m '+cls); r.appendChild(el('small',null,lab)); const bar=el('span','gp-bar'); const i=el('i'); i.style.width=clamp(b?a/b*100:0,0,100)+'%'; bar.appendChild(i); if(extra) bar.appendChild(extra); r.appendChild(bar); r.appendChild(el('b',null,a+'/'+b)); return r; }
function statusOf(m,s){ if(m.pv<=0) return ['ko','Fuera de combate']; if(m.pv<s.pv*0.35) return ['bad','Malherido']; if(m.pv<s.pv) return ['mid','Herido']; return ['ok','En forma']; }
function bestAff(id){ try{ if(!G.aff&&typeof cxRebuildAff==='function') cxRebuildAff(); }catch(e){} const A=G.aff||{}; let best=null;
  for(const k in A){ const [a,b]=k.split('|'); if((a!==id&&b!==id)||!a||!b) continue; const o=A[k]||{}; const sc=(o.lvl||0)*1000+(o.pts||0); if(sc>0&&(!best||sc>best.sc)) best={sc,other:a===id?b:a,lvl:o.lvl||0}; }
  if(!best) return null; let ln=''; try{ if(typeof cxLvlName==='function') ln=cxLvlName(best.lvl); }catch(e){} return {other:best.other,lvl:best.lvl,name:ln||('Nivel '+best.lvl)}; }

/* ---------- Grupo: tarjetas por personaje + orden y fila de formación ---------- */
/* v26: la vista previa usa la MISMA formación que el combate (stageLayout de p4: diagonal sin roces con las figuras 128 y Olaf en su hueco)
   y encuadra la caja de todo el grupo (antes, slotPos viejo con un recorte fijo: Nach e Ilian quedaban cortados arriba). */
const FPV={k:null,B:null};
function formationLayout(ids){ const key=(PZ.zone||'prados')+'|'+ids.map(id=>id+':'+G.party[id].row+':'+(id==='ilian'?G.party.ilian.weapon:'')+':'+sprVar(id)).join(',');
  if(FPV.k===key&&FPV.B) return FPV.B;
  const B={zone:PZ.zone||'prados',units:ids.map(id=>({side:'p',id,key:id,row:G.party[id].row,face:-1,ref:{weapon:id==='ilian'?G.party.ilian.weapon:null}}))};
  try{ stageLayout(B); }catch(e){ return null; }
  let x0=1e9,x1=-1e9,y0=1e9,y1=-1e9; B.units.forEach(u=>{ const b=bodyBoxOr(u); x0=Math.min(x0,u.hx+b.l); x1=Math.max(x1,u.hx+b.r); y0=Math.min(y0,u.hy+b.t); y1=Math.max(y1,u.hy+Math.max(b.b,2)); });
  if(B.olafAt){ x0=Math.min(x0,B.olafAt.x-10); x1=Math.max(x1,B.olafAt.x+10); y1=Math.max(y1,B.olafAt.y+2); }
  B.box={x0,x1,y0,y1}; if(B.units.every(u=>bodyBox(u))){ FPV.k=key; FPV.B=B; } return B; }
function formationDraw(g,v){ const ids=PZ.mode==='fijo'&&PZ.fixed?PZ.fixed.filter(id=>G.party[id]):partyIds().slice(0,5); /* posadas: solo los que pelean */ const W2=v.w, H2=v.h, sc=v.scale;
  const B=ids.length?formationLayout(ids):null; g.save(); g.scale(sc,sc);
  const bx=B&&B.box, ox=bx?Math.round(clamp((bx.x0+bx.x1)/2-W2/2,0,W-W2)):196, oy=bx?Math.round(clamp(bx.y1+6-H2,0,H-H2)):92;
  g.save(); g.translate(-ox,-oy); drawBG(g,PZ.zone||'prados',0); g.restore();
  if(B){ B.units.slice().sort((a,b)=>a.hy-b.hy).forEach(u=>{ const o={anim:'idle',face:-1,t:T+u.hx*0.03}; if(u.id==='ilian'){ o.weapon=G.party.ilian.weapon; } SPR.draw(g,u.id,Math.round(u.hx-ox),Math.round(u.hy-oy),o); });
    const ol=B.olafAt||{x:396,y:238}; SPR.draw(g,'olaf',ol.x-ox,ol.y-oy,{anim:'sit',face:-1}); }
  g.restore(); }
function tabGrupo(B){
  const fixed=PZ.mode==='fijo'&&PZ.fixed?PZ.fixed.filter(id=>G.party[id]):null;
  const ids=fixed||partyIds(); const N=5, big=!fixed&&ids.length>N, swap=GRUPO.canSwap(), prot=GRUPO.prot(); const main=el('div','pz-col gp-main');
  const cap=el('div','pz-cap gp-cap'); cap.appendChild(el('span',null,'Grupo')); cap.appendChild(el('span','gp-n',ids.length+' integrantes'));
  if(PZ.mode!=='libre'){ const ML={posada:'Posada',campamento:'Campamento',formacion:'Formación',fijo:'Formación',castillo:'Castillo'}; cap.appendChild(el('span','gp-mode',ML[PZ.mode]||PZ.mode)); } main.appendChild(cap);
  if(fixed) main.appendChild(el('p','pz-hint gp-lockhint',GRUPO.txt('bloqueado','Quién pelea lo decide la historia; las filas, vos.')));
  else if(PZ.mode==='formacion') main.appendChild(el('p','pz-hint',GRUPO.txt('abrir','Elegí quién pelea y en qué fila.')));
  if(big&&!swap) main.appendChild(el('p','pz-hint gp-lockhint',GRUPO.txt('candado','El grupo se cambia en posadas, campamentos y puntos de formación.')));
  const grid=el('div','gp-cards');
  const doSwap=(a,b)=>{ const o=partyIds(); const i1=o.indexOf(a), i2=o.indexOf(b); if(i1<0||i2<0) return;
    const cross=(i1<N)!==(i2<N); if(cross&&(GRUPO.guest(a)||GRUPO.guest(b))){ toast(GRUPO.txt('invitada','Va como invitada: no se cambia.'),2200); return; }
    if(cross&&(a===prot&&i1<N||b===prot&&i2<N)){ toast(nameOf(prot)+': '+GRUPO.txt('protagonista','va siempre en el grupo.'),2000); return; }
    [o[i1],o[i2]]=[o[i2],o[i1]]; G.order=o; sfx('heal'); };
  ids.forEach((id,i)=>{ const m=G.party[id], s=stats(m), nx=expInfo(m), [stc,stt]=statusOf(m,s);
    if(big&&i===N){ const sep=el('div','gp-sep',GRUPO.txt('caravana','En la caravana')); grid.appendChild(sep); }
    const bench=big&&i>=N;
    const c=el('article','gp-card'+(i===0?' lead':'')+(m.row==='front'?' f':' b')+(bench?' bench':'')+(PZ.swapSel===id?' swapsel':'')); c.setAttribute('aria-label',CHAR[id].name+', nivel '+m.lvl+', '+stt+(bench?', en la caravana':''));
    const pic=btn('gp-pic',null,()=>{ PZ.sel=id; PZ.tab='fichas'; renderPause(true); },{label:'Ver la ficha de '+CHAR[id].name}); { const hc=headCanvas(id,128,60); panimBind(hc,id,'head'); pic.appendChild(hc); } pic.appendChild(el('span','gp-ord',String(i+1))); if(i===0) pic.appendChild(el('span','gp-lead','Líder')); c.appendChild(pic);
    const hd=el('div','gp-hd'); const nm=el('div','gp-nm'); nm.appendChild(el('b',null,CHAR[id].name)); const lv=el('span','gp-lv'); lv.appendChild(el('small',null,UIT.nivelCorto+' ')); lv.appendChild(el('b',null,String(m.lvl))); nm.appendChild(lv); hd.appendChild(nm);
    const sub=el('div','gp-sub'); sub.appendChild(el('span','gp-cls',classOf(id))); sub.appendChild(el('span','gp-st '+stc,stt)); hd.appendChild(sub); c.appendChild(hd);
    // ▲▼: reordenar. Sin posada no se cruza el 5.º lugar (candado); en la posada, el protagonista no baja a la caravana
    const lockDn=big&&i===N-1&&(!swap||id===prot||GRUPO.guest(id)), lockUp=big&&i===N&&(!swap||GRUPO.guest(id)||GRUPO.guest(ids[N-1])||ids[N-1]===prot);
    const mv=(d)=>{ if((d>0&&lockDn)||(d<0&&lockUp)){ toast(GRUPO.txt('candado','El grupo se cambia en posadas, campamentos y puntos de formación.'),2200); return; } const o=partyIds(); const j=i+d; if(j<0||j>=o.length) return; [o[i],o[j]]=[o[j],o[i]]; G.order=o; renderPause(); const f=PZ.body.querySelectorAll(d<0?'.pz-up':'.pz-dn')[j]; const g2=f&&!f.disabled?f:PZ.body.querySelectorAll(d<0?'.pz-dn':'.pz-up')[j]; if(g2) g2.focus({preventScroll:true}); };
    const ord=el('div','gp-ordb'); const bu=btn('pz-up'+(lockUp?' locked':''),'▲',()=>mv(-1),{disabled:!!fixed||i===0||lockUp,label:'Subir a '+CHAR[id].name}); const bd=btn('pz-dn'+(lockDn?' locked':''),'▼',()=>mv(1),{disabled:!!fixed||i===ids.length-1||lockDn,label:'Bajar a '+CHAR[id].name});
    if(lockUp||lockDn){ (lockUp?bu:bd).title=GRUPO.txt('candado','El grupo se cambia en posadas, campamentos y puntos de formación.'); } ord.appendChild(bu); ord.appendChild(bd); c.appendChild(ord);
    const bars=el('div','gp-bars'); bars.appendChild(meter('pv','PV',m.pv,s.pv)); bars.appendChild(meter('pm','PM',m.pm,s.pm));
    const ex=el('div','gp-m ex'); ex.appendChild(el('small',null,'Exp')); const eb=el('span','gp-bar'); const ei=el('i'); ei.style.width=(nx.f*100)+'%'; eb.appendChild(ei); ex.appendChild(eb); ex.appendChild(el('b',null,nx.next==null?UIT.nivelMax:('faltan '+nx.next))); bars.appendChild(ex); c.appendChild(bars);
    const ft=el('div','gp-ft'); const af=bestAff(id); const al=el('span','gp-aff'); al.appendChild(el('i','gp-heart'));
    if(af){ al.appendChild(el('span',null,(nameOf(af.other)||af.other)+' · ')); al.appendChild(el('b',null,af.name)); al.title='Afinidad más alta'; } else al.appendChild(el('span','gp-dim','Sin afinidad todavía')); hd.appendChild(al);
    // «Cambiar» (posada, campamento, punto de formación, castillo): se toca uno y después el otro
    if(swap&&big){ const on=PZ.swapSel===id; const sw=btn('pz-swap'+(on?' on':''),on?'Cancelar':GRUPO.txt('cambiar','Cambiar'),()=>{ const a=PZ.swapSel; if(!a||a===id){ PZ.swapSel=on?null:id; } else { doSwap(a,id); PZ.swapSel=null; } renderPause(); const f=[...PZ.body.querySelectorAll('.gp-card')].find(x=>x.querySelector('.pz-swap.on'))||PZ.body.querySelectorAll('.gp-card')[partyIds().indexOf(id)]; const fb=f&&f.querySelector('.pz-swap'); if(fb) fb.focus({preventScroll:true}); },{label:(on?'Cancelar el cambio de ':'Cambiar a ')+CHAR[id].name,disabled:(id===prot&&!PZ.swapSel)});
      if(id===prot) sw.title=GRUPO.txt('protagonista','Va siempre en el grupo'); ft.appendChild(sw); }
    const rb=btn('pz-rowb '+(m.row==='front'?'f':'b'),m.row==='front'?UIT.primeraLinea:UIT.segundaLinea,()=>{ m.row=m.row==='front'?'back':'front'; renderPause(); const f=PZ.body.querySelectorAll('.pz-rowb')[i]; if(f) f.focus({preventScroll:true}); },{label:UIT.cambiarLinea+': '+CHAR[id].name});
    rb.title=UIT.cambiarLinea; if(i===0) rb.dataset.focus='1'; ft.appendChild(rb); c.appendChild(ft);
    grid.appendChild(c); });
  main.appendChild(grid); B.appendChild(main);
  const side=el('div','pz-col gp-side'); side.appendChild(el('div','pz-cap','Así forman en combate'));
  const pv=el('div','pz-form'); pv.appendChild(sprCanvas('ilian',232,168,2,{draw:formationDraw})); side.appendChild(pv);
  side.appendChild(el('p','pz-hint','La 1.ª línea recibe más golpes; arcos, lanzas y magia rinden igual desde la 2.ª. '+(big?'Pelean los 5 primeros; el resto espera en la caravana.':'Quién entra lo decide cada combate.')+' El primero de la lista encabeza la marcha.'));
  const sm=el('div','gp-sum'); const kv=(k,v)=>{ const r=el('div'); r.appendChild(el('small',null,k)); r.appendChild(el('b',null,v)); sm.appendChild(r); };
  let place='—'; try{ place=SAVES.placeNow(); }catch(e){} kv('Dónde',place); kv('Tiempo de juego',fmtPlay(SAVES.playNow())); kv(UIT.oro,String(G.oro)); if(G.sealed) kv('Estrellas selladas',G.sealed.length+' / 120');
  side.appendChild(sm); B.appendChild(side);
}

/* ---------- Objetos: inventario con filtros, orden, detalle y «Usar» sobre quién ---------- */
const INVCATS=[['todo','Todo'],['cons','Consumibles'],['wpn','Armas'],['arm','Armaduras'],['acc','Accesorios'],['key','Clave']];
const INVORD={cons:0,wpn:1,arm:2,acc:3,key:4};
const INVSORT=[['tipo','Tipo'],['nombre','Nombre'],['cantidad','Cantidad']];
PZ.inv={cat:'todo',sort:'tipo',sel:null};
function invEntries(){ const out=[];
  Object.keys(ITEMS).forEach(k=>{ const n=G.items[k]||0; if(n>0) out.push({id:k,kind:'item',cat:'cons',n,tot:n,name:MENUTXT.items[k].name,desc:MENUTXT.items[k].desc}); });
  const worn={}; partyIds().forEach(pid=>{ const eq=G.equip[pid]||{}; Object.keys(eq).forEach(sl=>{ const it=eq[sl]; if(it) (worn[it]||(worn[it]=[])).push(pid); }); });
  new Set(Object.keys(G.gear).filter(k=>G.gear[k]>0).concat(Object.keys(worn))).forEach(it=>{ const d=EQUIP.items[it]; if(!d) return; const cat=d.slot==='armadura'?'arm':d.slot==='accesorio'?'acc':'wpn'; const n=G.gear[it]||0, w=worn[it]||[];
    out.push({id:it,kind:'gear',cat,n,tot:n+w.length,worn:w,name:itemName(it),desc:itemDesc(it),slot:d.slot}); });
  if(G.keyItems&&typeof ARC!=='undefined') Object.keys(G.keyItems).forEach(k=>{ const D=ARC.keyItem(k); if(D) out.push({id:'key_'+k,kind:'key',cat:'key',n:1,tot:1,name:D.n,desc:D.d}); }); // Arco I · S11: recuerdos (sin uso ni venta)
  if(G.sealed&&G.sealed.length) out.push({id:'estrellas',kind:'key',cat:'key',n:G.sealed.length,tot:G.sealed.length,name:'Estrellas selladas',desc:'Las estrellas que ya quedaron selladas ('+G.sealed.length+' de 120): '+G.sealed.map(x=>nameOf(x)||x).join(', ')+'.'});
  return out; }
function invSorted(L){ const S=PZ.inv.sort, nm=(a,b)=>a.name.localeCompare(b.name,'es');
  return L.slice().sort(S==='nombre'?nm:S==='cantidad'?((a,b)=>b.tot-a.tot||nm(a,b)):((a,b)=>INVORD[a.cat]-INVORD[b.cat]||(invUsable(b)-invUsable(a))||nm(a,b))); }
const INV_FIELD={pocion:1,pocion_mayor:1,tonico:1}; // se usan fuera de combate (B11)
function invUsable(e){ return e.kind==='item'&&(!!INV_FIELD[e.id]||(e.id==='ruda'&&typeof ENC!=='undefined')); }
