  const so=el('div','iv-sort'); so.appendChild(el('small',null,'Orden')); INVSORT.forEach(([k,lb])=>{ const b=btn('iv-s'+(I.sort===k?' on':''),lb,()=>{ I.sort=k; renderPause(); const f=PZ.body.querySelector('.iv-s.on'); if(f) f.focus({preventScroll:true}); }); b.setAttribute('aria-pressed',String(I.sort===k)); so.appendChild(b); });
  top.append(fl,so); B.appendChild(top);
