/* ---------- estado ---------- */
const CXS={sub:'cronica',enemy:null,pair:null,fresh:{}};
const CXELEM_COL={fuego:'#e0663a',viento:'#5cbf8a',rayo:'#e6c84a',luz:'#f1e4a6',agua:'#5a9ae0',tierra:'#b08a5a',hielo:'#9ad8f0',sombra:'#8a6ab8',veneno:'#9ad16b'};
const CXBEST=['lobo','alfa','bandido','arquero','lobo_bosque','jabali','soldado','ballestero','asesino','oswin'];
const CXFIGHT={lobo:'prados',bandido:'sauces',arquero:'sauces',jabali:'pantano',alfa:'pantano',soldado:'puente',ballestero:'puente',asesino:'emboscada',oswin:'jefe'};
// pulido C03: los 7 enemigos del Arco I (el tramo después del cual ya se pelearon sí o sí)
Object.assign(CXFIGHT,{jinete:'c2_rezagados',cabo_jinetes:'c2_jefe',sargento:'c3_jefe',cabo_taberna:'c4_jefe',sabueso:'c5_caceria',montero:'c5_jefe',valdris:'c5_valdris'});
// técnicas y su efecto, desde los textos de cada capítulo (LINES.capN.codex; historia.js solo copia el lore)
(function cxArcSkills(){ [2,3,4,5].forEach(n=>{ const C=((typeof LINES!=='undefined'&&LINES['cap'+n])||{}).codex||{};
  Object.keys(C.skills||{}).forEach(k=>{ CXT.skills[k]=C.skills[k].slice(); }); Object.assign(CXT.skillDesc,C.skillDesc||{}); });
  // los golpes base que también se registran con su nombre
  if(CXT.skills.jinete&&!CXT.skills.jinete.includes('Lanza')) CXT.skills.jinete.unshift('Lanza');
  if(CXT.skills.sabueso&&!CXT.skills.sabueso.includes('Mordida')) CXT.skills.sabueso.unshift('Mordida');
  if(!CXT.skillDesc['Lanza']) CXT.skillDesc['Lanza']='Lanzazo a uno.'; })();
// el registro de combate anota el nombre del efecto visual cuando una técnica nueva reusa uno del Cap. 1: se muestra con su nombre propio
CXT.skillAlias={sargento:{'Mandoble Ceniza':'Carga de lanzas'},cabo_jinetes:{'Formación':'¡A la carga!'},cabo_taberna:{'Formación':'¡Las mesas!'},
  sabueso:{'Aullido':'Rastro'},montero:{'Aullido':'Cuerno de caza'},valdris:{'Mandoble Ceniza':'Tajo del Ocaso'}};
const CXSTEPS=['prologo','hollin','contrato','prados','sauces','pantano','campamento','puente','emboscada','huida','jefe','bosque','cierre'];
function cxOrd(){ return (typeof ORDER!=='undefined'&&ORDER)||['prologo','titulo'].concat(CXSTEPS.slice(1)); }
function cxIdx(s){ return cxOrd().indexOf(s); }
function cxCur(){ const i=cxIdx(G&&G.cp); return i<0?0:i; }
const cxDone=s=>cxIdx(s)>=0&&cxIdx(s)<cxCur();
const cxReached=s=>cxIdx(s)>=0&&cxIdx(s)<=cxCur();
function cxFreshCheck(){ if(CXS.L!==PZ.L){ CXS.L=PZ.L; CXS.fresh={}; } }
function cxState(){ if(!G) return {enemies:{},journal:{seen:{}}}; const c=G.codex||(G.codex={}); if(!c.enemies) c.enemies={}; const j=c.journal||(c.journal={}); if(!j.seen) j.seen={}; if(!j.places) j.places={}; return c; }
/* marca «nuevo»: true la primera vez que se muestra en esta partida (se registra al pintar) */
function cxIsNew(k){ const j=cxState().journal; if(CXS.fresh[k]) return true; if(j.seen[k]) return false; CXS.fresh[k]=1; j.seen[k]=1; return true; }
function cxPeekNew(k){ const j=cxState().journal; return !j.seen[k]; }
function cxTag(host,k){ if(cxIsNew(k)) host.appendChild(el('span','cx-new','Nuevo')); }
const cxName=k=>(ENEMY[k]&&ENEMY[k].name)||k;
function cxItemName(id){ if(MENUTXT.equip&&MENUTXT.equip[id]) return MENUTXT.equip[id].name; if(MENUTXT.items&&MENUTXT.items[id]) return MENUTXT.items[id].name; return String(id); }
// miniatura de retrato: los ilustrados se arman fuera del hilo del juego; se repinta apenas están (unos segundos como máximo)
function cxThumb(cls,id,expr,size){ const c=el('canvas',cls); c.width=c.height=size; const g=c.getContext('2d'); const t0=performance.now();
  const ok=()=>{ try{ return g.getImageData(size>>1,size>>1,1,1).data[3]>0; }catch(e){ return true; } };
  const paint=()=>{ try{ g.clearRect(0,0,size,size); thumbOf(g,id,expr,size); }catch(e){} if(!ok()&&performance.now()-t0<15000&&(c.isConnected||performance.now()-t0<500)) setTimeout(paint,150); };
  paint(); return c; }
const cxNorm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]/g,'');

/* ---------- bestiario: datos ---------- */
// pulido C03: los aleatorios del Arco I usan variantes de nivel ('lobo_bosque_n6', 'jinete_n7'); se suman a la ficha de su tipo
function cxRec(k){ const E=cxState().enemies; const vs=Object.keys(E).filter(x=>x===k||x.replace(/_n\d+$/,'')===k&&x!==k); if(!vs.length) return null; if(vs.length===1&&vs[0]===k) return E[k];
  const r={seen:0,kills:0,hp:false,weak:[],res:[],skills:[],drops:[],memo:false}; const add=(a,b)=>(b||[]).forEach(v=>{ if(!a.includes(v)) a.push(v); });
  vs.forEach(x=>{ const e=E[x]; r.seen+=e.seen|0; r.kills+=e.kills|0; r.hp=r.hp||!!e.hp; r.memo=r.memo||!!e.memo; add(r.weak,e.weak); add(r.res,e.res); add(r.skills,e.skills); add(r.drops,e.drops); }); return r; }
function cxEnemy(k){ const rec=cxRec(k); const inferred=!rec&&!!CXFIGHT[k]&&cxDone(CXFIGHT[k]);
  const r=rec||{}; const seen=(r.seen|0)>0||(r.kills|0)>0||inferred; return {k,rec:r,seen,inferred,memo:inferred||!!r.memo,kills:rec?(r.kills|0):null}; }
function cxPotDrops(k){ const out=((EQUIP.drops||{})[k]||[]).slice(); if(ENEMY[k]&&ENEMY[k].drop) out.push('pocion'); return out; }
function cxSprDraw(k,o){ return (g,v)=>{ const sc=v.scale; const x=Math.round(v.w*sc/2), y=Math.round((v.h-4)*sc);
    let an='idle', t=T+(o.ph||0);
    if(o.cycle){ let dA=0; try{ dA=SPR.dur(sprId(k),'attack')||0; }catch(e){} const P=3.2+(dA?dA+0.5:0); const tt=(T-v.t0)%P; if(dA&&tt>3.2){ an='attack'; t=Math.min(tt-3.2,dA); } }
    try{ SPR.draw(g,sprId(k),x,y,{anim:an,t,face:1,scale:sc,shadow:!o.sil}); }catch(e){}
    if(o.sil){ g.save(); g.globalCompositeOperation='source-atop'; g.fillStyle='#120c08'; g.fillRect(0,0,v.c.width,v.c.height); g.restore(); } }; }
function cxSprite(k,scale,o){ let sz={w:48,h:48}; try{ sz=SPR.size(sprId(k))||sz; }catch(e){} const w=Math.max(56,Math.ceil(sz.w*1.25)+12), h=Math.max(44,Math.ceil(sz.h)+10);
  return sprCanvas(k,w,h,scale,{draw:cxSprDraw(k,o||{})}); }
const CXBG=new Map();
// fondo de la lámina: el de la zona (si todavía no está armado, se pide con prioridad y se reintenta unos segundos)
function cxBgReady(k){ try{ const d=k.getContext('2d').getImageData(0,200,480,1).data; let s=0; for(let i=0;i<d.length;i+=16) s+=d[i]+d[i+1]+d[i+2]; return s/(d.length/16)>60; }catch(e){ return true; } }
function cxBackdrop(zone){ if(CXBG.has(zone)) return CXBG.get(zone); const k=document.createElement('canvas'); k.width=480; k.height=300; try{ drawBG(k.getContext('2d'),zone,0); }catch(e){} if(cxBgReady(k)) CXBG.set(zone,k); return k; }
function cxPaintPlate(bg,zone,tries){ if(!bg.isConnected&&tries<20){ setTimeout(()=>cxPaintPlate(bg,zone,tries+1),60); return; } if(!bg.isConnected) return; const k=cxBackdrop(zone); const g=bg.getContext('2d'); g.clearRect(0,0,480,300); g.drawImage(k,0,0);
  if(!CXBG.has(zone)){ if(tries===0){ try{ if(ENV.prewarm) ENV.prewarm([zone],false,true); }catch(e){} } if(tries<25) setTimeout(()=>cxPaintPlate(bg,zone,tries+1),300); } }
const CXZONE={lobo:'prados',alfa:'pantano',bandido:'sauces',arquero:'sauces',lobo_bosque:'sauces',jabali:'pantano',soldado:'puente',ballestero:'puente',asesino:'puente',oswin:'puente'};
Object.assign(CXZONE,{jinete:'sauces',cabo_jinetes:'sauces',sargento:'prados',cabo_taberna:'taberna',sabueso:'campamento',montero:'pantano',valdris:'pantano'}); // pulido C03: fondo de la lámina = el del combate

/* ---------- pestaña BESTIARIO ---------- */
function tabBestiario(B){ cxFreshCheck(); cxRebuild();
  const E=CXBEST.map(cxEnemy); const nSeen=E.filter(e=>e.seen).length; const kills=E.reduce((a,e)=>a+(e.kills||0),0);
  if(!CXS.enemy||!E.find(e=>e.k===CXS.enemy&&e.seen)) CXS.enemy=(E.find(e=>e.seen)||{}).k||null;
  const left=el('div','pz-col cx-bl');
  const cap=el('div','pz-cap cx-cap'); cap.appendChild(el('span',null,CXT.tabs.bestiario)); const cnt=el('span','cx-cnt'); cnt.appendChild(el('span',null,'Vistos ')); cnt.appendChild(el('b',null,nSeen+'/'+CXBEST.length)); cnt.appendChild(el('span',null,' · Derrotados ')); cnt.appendChild(el('b',null,String(kills))); cap.appendChild(cnt); left.appendChild(cap);
  const grid=el('div','cx-bgrid'); const det=el('div','cx-bdet');
  E.forEach((e,i)=>{ const b=btn('cx-bc'+(e.seen?'':' unk')+(e.k===CXS.enemy?' on':''),null,()=>{ if(!e.seen){ toast('Todavía no lo viste.',1500); return; } pick(e.k); },{label:e.seen?cxName(e.k):'Enemigo sin ver'});
    if(e.k===CXS.enemy||(!CXS.enemy&&i===0)) b.dataset.focus='1';
    const fr=el('div','cx-bc-spr'); fr.appendChild(cxSprite(e.k,1,{sil:!e.seen,ph:i*0.37})); if(!e.seen) fr.appendChild(el('span','cx-q','?')); b.appendChild(fr);
    const t=el('div','cx-bc-t'); t.appendChild(el('small',null,'N.º '+String(i+1).padStart(2,'0'))); t.appendChild(el('b',null,e.seen?cxName(e.k):'???'));
    if(e.seen) t.appendChild(el('span','cx-bc-k',e.kills==null?'Derrotados: —':'Derrotados: '+e.kills)); b.appendChild(t);
    if(e.seen&&cxPeekNew('b:'+e.k)) b.appendChild(el('span','cx-new','Nuevo'));
    b.addEventListener('focus',()=>{ if(e.seen&&CXS.enemy!==e.k) pick(e.k,true); });
    grid.appendChild(b); });
  left.appendChild(grid); left.appendChild(el('p','pz-hint',CXT.bestHint)); B.appendChild(left);
  const right=el('div','pz-col cx-br'); right.appendChild(det); B.appendChild(right);
  function pick(k,fromFocus){ CXS.enemy=k; grid.querySelectorAll('.cx-bc').forEach((b,j)=>b.classList.toggle('on',CXBEST[j]===k)); const nb=grid.querySelectorAll('.cx-bc')[CXBEST.indexOf(k)]; const nw=nb&&nb.querySelector('.cx-new'); if(nw) nw.remove(); cxState().journal.seen['b:'+k]=1; bestDetail(det,cxEnemy(k)); if(!fromFocus&&nb) nb.focus({preventScroll:true}); if(!fromFocus&&!WIDE) det.scrollIntoView({block:'start',behavior:REDUCED?'auto':'smooth'}); }
  if(CXS.enemy){ cxState().journal.seen['b:'+CXS.enemy]=1; bestDetail(det,cxEnemy(CXS.enemy)); const nb=grid.querySelectorAll('.cx-bc')[CXBEST.indexOf(CXS.enemy)]; const nw=nb&&nb.querySelector('.cx-new'); if(nw) nw.remove(); }
  else { const em=el('div','cx-empty'); em.appendChild(el('b',null,'Páginas en blanco')); em.appendChild(el('p',null,'Todavía no cruzaste ningún enemigo. Cuando pelees, lo que veas queda anotado acá.')); det.appendChild(em); }
}
