  const allK=!!(D.boss&&CXFIGHT[k]&&cxDone(CXFIGHT[k])); const isK=n=>allK||known.some(x=>cxNorm(x)===cxNorm(n)); /* pulido C03: jefe ya vencido = técnicas de fase conocidas */ all.forEach(n=>{ const li=el('li',isK(n)?'':'unk'); if(isK(n)){ li.appendChild(el('b',null,n)); if(CXT.skillDesc[n]) li.appendChild(el('span',null,CXT.skillDesc[n])); } else li.appendChild(el('b',null,'???')); ul.appendChild(li); });
  known.filter(x=>!all.some(n=>cxNorm(n)===cxNorm(x))).forEach(x=>{ const li=el('li'); li.appendChild(el('b',null,x)); ul.appendChild(li); });
  if(!ul.children.length) ul.appendChild(el('li','unk','—')); sk.appendChild(ul); grid.appendChild(sk);
