/* ---------- diario: datos derivados ---------- */
function cxPlaces(){ const j=cxState().journal; const HF=(G.flags&&G.flags.hol)||{}; const out=[];
  CXT.places.forEach(p=>{ const vis=cxReached(p.step)||!!j.places[p.id]; if(vis) j.places[p.id]=1; const rooms=[];
    if(p.id==='hollin'){ const R=(LINES.hollin&&LINES.hollin.rooms)||{}; Object.keys(CXT.rooms).forEach(rid=>{ if(HF['en_'+rid]) rooms.push({n:(R[rid]&&R[rid].name)||rid,d:CXT.rooms[rid]}); }); }
    out.push(Object.assign({vis,rooms},p)); }); return out; }
function cxPeople(){ const met=(G.flags&&G.flags.met)||{}; return persons().filter(p=>personMet(met,p)).map(p=>{ const vs=variantsOf(p); const id=(vs.find(v=>met[v[0]])||vs[0])[0]; let note=CXT.people[p]||''; if(note&&typeof note==='object') note=cxDone(note.after)?note.b:note.a; return {p,id,note,d:fichaData(id)}; }); }
// escenas de afinidad v2: la lista es LINES.escenas (id, title, pair, hint); «abierta» = disponible ahora (escenaAvail, p5)
function cxChatsAll(){ return (LINES.escenas||[]); }
function cxChatOpen(ch){ try{ return escenaAvail(ch.id); }catch(e){ return false; } }
const cxEscLost=ch=>{ try{ return escenaLost(ch.id); }catch(e){ return false; } };
const cxPlace=ch=>String(ch.hint||'').split(' · ')[0];
function cxTodos(){ const HF=(G.flags&&G.flags.hol)||{}; const T2=CXT.todo; const out=[]; const ci=cxCur();
  // contrato
  { const st=cxDone('contrato')?(cxDone('emboscada')?'off':'on'):'pre'; out.push({k:'contrato',n:T2.contrato.n,d:T2.contrato[st],state:st==='on'?'on':(st==='off'?'fail':'pre')}); }
  // Sir Astilla (aparece cuando el nene lo pide o al encontrar el juguete)
  if(HF.pedido||HF.juguete||HF.juguete_dev){ let s,d; if(HF.juguete_dev){ s='done'; d=T2.astilla.hecho; } else if(HF.juguete){ s='on'; d=HF.pedido?T2.astilla.hallado:T2.astilla.hallado0; } else { s='on'; d=T2.astilla.pedido; }
    if(s!=='done'&&cxDone('hollin')){ s='late'; d+=' '+T2.astilla.tarde; } out.push({k:'astilla',n:T2.astilla.n,d,state:s}); }
  // misiones MVP: H-02, C-01 y C-04 (el estado se deriva de las banderas: sirve igual para partidas viejas)
  try{ sqTodos(out,T2); }catch(e){ console.error(e); }
  // cofres secretos x/2
  { const a=!!HF.cofre_taberna, b=!!HF.cofre_fardos; const n=(a?1:0)+(b?1:0); if(cxReached('hollin')) out.push({k:'secretos',n:T2.secretos.n,count:n+'/2',list:[a?T2.secretos.tabla:T2.secretos.falta,b?T2.secretos.fardos:T2.secretos.falta],state:n>=2?'done':(cxDone('hollin')?'late':'on')}); }
  // cofre del molino
  if(cxReached('hollin')){ const o=!!(G.flags&&G.flags.cofre); out.push({k:'molino',n:T2.molino.n,d:o?T2.molino.si:T2.molino.no,state:o?'done':(cxDone('hollin')?'late':'on')}); }
  // escenas de afinidad v2: vistas (título · lugar), las que esperan ahora (con su lugar, sin título) y cuántas se perdieron
  { const seen=(G.flags&&G.flags.chats)||{}; const all=cxChatsAll(); const vis=all.filter(c=>seen[c.id]); const av=all.filter(c=>!seen[c.id]&&cxChatOpen(c)); const lost=all.filter(c=>!seen[c.id]&&cxEscLost(c)).length;
    if(cxReached('hollin')||vis.length){ const C2=T2.charlas; const L2=vis.map(c=>'«'+c.title+'» · '+cxPlace(c)).concat(av.filter(c=>c.mark).map(c=>C2.espera.replace('%L',c.hint))); /* las de paso y la del fogón son automáticas: no se anuncian */ if(lost) L2.push(lost===1?C2.perdida:C2.perdidas.replace('%',lost));
      out.push({k:'charlas',n:C2.n,count:vis.length+'/'+all.length,d:C2.d,list:L2.length?L2:null,state:av.length?'on':(vis.length+lost>=all.length?(lost?'late':'done'):'pre')}); } }
  // GUION v2: encargo de la Granja y el Altar hundido
  { const fl=(G.world&&G.world.flags)||{}; if(fl.granja_lobos) out.push({k:'granja',n:T2.granja.n,d:T2.granja.si,state:'done'}); else if(cxReached('prados')&&G.world&&G.world.places&&G.world.places.granja) out.push({k:'granja',n:T2.granja.n,d:T2.granja.on,state:cxDone('campamento')?'late':'on'});
    if(fl.diario_altar) out.push({k:'altar',n:T2.altar.n,d:T2.altar.d,state:'pre'}); }
  // estrellas
  if((G.sealed||[]).length) out.push({k:'estrellas',n:T2.estrellas.n,count:((G.sealed||[]).length+2)+'/120',d:T2.estrellas.d+' Ya selladas: '+['Ilian','Nach'].concat((G.sealed||[]).map(nameOf)).join(', ')+'.',state:'on'});
  return out; }
function cxNewDiary(){ try{ if(!G) return 0; let n=0; const j=cxState().journal;
  CXSTEPS.forEach(s=>{ if(CXT.chron[s]&&cxDone(s)&&!j.seen['c:'+s]) n++; }); if(ncOn()) Object.keys((G.flags&&G.flags.nc)||{}).forEach(id=>{ if(!j.seen['nc:'+id]) n++; }); return n; }catch(e){ return 0; } }

/* ---------- pestaña DIARIO ---------- */
