  Object.keys(CXT.dsub).filter(s=>s!=='nocierra'||ncOn()).forEach(s=>{ const b=btn('cx-sub'+(CXS.sub===s?' on':''),CXT.dsub[s],()=>{ CXS.sub=s; renderPause(); const f=PZ.body.querySelector('.cx-sub.on'); if(f) f.focus({preventScroll:true}); }); b.setAttribute('role','tab'); b.setAttribute('aria-selected',String(CXS.sub===s)); if(CXS.sub===s) b.dataset.focus='1'; subs.appendChild(b); });
  nav.appendChild(subs);
  const lid=el('div','cx-lid'); { const cn=(G&&G.chap>1&&typeof ARC!=='undefined')?ARC.capInfo(G.chap):null; lid.appendChild(el('b',null,cn?'Capítulo '+cn.n:'Capítulo 1')); lid.appendChild(el('span',null,cn?cn.titulo:'El Contrato')); } lid.appendChild(el('small',null,(typeof STEPNAME!=='undefined'&&STEPNAME[G.cp])?('Ahora: '+STEPNAME[G.cp]):'')); nav.appendChild(lid);
