    const clip=X0>0.5||Y0>0.5||X1<W-0.5||Y1<H-0.5; if(clip){ if(X1-X0<40||Y1-Y0<40) return; c.save(); c.beginPath(); c.rect(X0,Y0,X1-X0,Y1-Y0); c.clip(); }
