const SP=n=>AUTO?0:n;

/* ---------- pincel de píxeles (zonas de prueba y mapa global) ---------- */
const HX={}; const rgbOf=h=>{ let v=HX[h]; if(v) return v; const n=parseInt(h.slice(1),16); return HX[h]=[n>>16,(n>>8)&255,n&255]; };
