const BAY=[0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5]; const bay=(x,y)=>(BAY[(y&3)*4+(x&3)]+0.5)/16;
const qa=(p,v,x,y)=>p[clamp(Math.floor(v*(p.length-1)+bay(x,y)),0,p.length-1)];
const mixc=(a,b,t)=>[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t];
