    set(px,py,c,a){ px|=0; py|=0; if(px<0||py<0||px>=PW||py>=PH||!c) return; const i=(py*PW+px)*4; if(a==null||a>=1){ d[i]=c[0]; d[i+1]=c[1]; d[i+2]=c[2]; d[i+3]=255; return; } d[i]+=(c[0]-d[i])*a; d[i+1]+=(c[1]-d[i+1])*a; d[i+2]+=(c[2]-d[i+2])*a; if(d[i+3]<a*255) d[i+3]=a*255; },
