    ell(cx,cy,rx,ry,f){ for(let yy=Math.floor(cy-ry);yy<=cy+ry;yy++) for(let xx=Math.floor(cx-rx);xx<=cx+rx;xx++){ const u=(xx+0.5-cx)/rx, v=(yy+0.5-cy)/ry; if(u*u+v*v<=1){ const c=typeof f==='function'?f(xx,yy,u,v):f; if(c) P.set(xx,yy,c); } } },
    line(x0,y0,x1,y1,c){ x0|=0;y0|=0;x1|=0;y1|=0; const dx=Math.abs(x1-x0), dy=-Math.abs(y1-y0), sx=x0<x1?1:-1, sy=y0<y1?1:-1; let e=dx+dy; for(let n=0;n<4000;n++){ P.set(x0,y0,c); if(x0===x1&&y0===y1) break; const e2=2*e; if(e2>=dy){ e+=dy; x0+=sx; } if(e2<=dx){ e+=dx; y0+=sy; } } },
    outline(k2){ k2=k2==null?0.5:k2; const src=new Uint8ClampedArray(d); const A=(xx,yy)=>xx>=0&&yy>=0&&xx<PW&&yy<PH?src[(yy*PW+xx)*4+3]:0;
      for(let yy=0;yy<PH;yy++) for(let xx=0;xx<PW;xx++){ const i=(yy*PW+xx)*4; if(src[i+3]>40) continue; let b=-1; if(A(xx+1,yy)>200) b=(yy*PW+xx+1)*4; else if(A(xx-1,yy)>200) b=(yy*PW+xx-1)*4; else if(A(xx,yy+1)>200) b=((yy+1)*PW+xx)*4; else if(A(xx,yy-1)>200) b=((yy-1)*PW+xx)*4;
        if(b>=0){ d[i]=src[b]*(1-k2)*0.8; d[i+1]=src[b+1]*(1-k2)*0.78; d[i+2]=Math.min(255,src[b+2]*(1-k2)+10); d[i+3]=255; } } },
