const C={grass:pal(['#35602a','#447332','#53853a','#649744','#78a94e']), grassD:pal(['#1f3a1c','#284a22','#335a2a','#3f6a32','#4e7a3a']),
  heath:pal(['#4a2e5a','#64407a','#7e5494','#9a6cae','#b88ac6']), dirt:pal(['#7a5c3a','#8a6a44','#a3824f','#b8955f','#c9a874','#d8bc8a']),
  mud:pal(['#2e2a1a','#3e3822','#4e472c','#615838','#766c46']), water:pal(['#1e4a66','#245a7a','#2d6a8c','#3a7fa4','#4f96bc','#6fb0d4']),
  swampW:pal(['#16302c','#1e3c36','#284a40','#33584a','#406654']), rock:pal(['#2e2b28','#3e3a36','#4e4a44','#6a655c','#888276','#a8a294','#c4beb0']),
  leaf:pal(['#1e3a1e','#2a5226','#3a6a2e','#4e843a','#68a048','#8cbc5a']), willow:pal(['#24421e','#30562a','#426e34','#5a8840','#78a250','#9cbc64']),
  pine:pal(['#142a20','#1e3c2a','#2a5034','#3a663e','#507a48']), wood:pal(['#3a2414','#5a3a20','#7a5230','#9a6c40','#b88a56']),
  thatch:pal(['#6a4a22','#8a6a32','#a88a44','#c8a858','#dcc070']), cloth:pal(['#5a4c3e','#7a6a56','#9a8a70','#bcac8e','#dcd0b4']),
  plaster:pal(['#8a7a62','#b8a684','#d0c09e','#e4d6b8']), needle:pal(['#14180f','#1c2216','#252d1c','#303a24','#3c482c']), deadleaf:pal(['#2a2414','#3a301a','#4c3e22','#5e4c2a']),
  wool:pal(['#9a968a','#c4c0b2','#e2ded0','#f6f2e6'])};
function segD(px,py,a,b){ const vx=b[0]-a[0], vy=b[1]-a[1]; const t=clamp(((px-a[0])*vx+(py-a[1])*vy)/(vx*vx+vy*vy||1),0,1); return Math.hypot(px-a[0]-vx*t,py-a[1]-vy*t); }
function polyD(x,y,P){ let b=1e9; for(let i=0;i<P.length-1;i++){ const d=segD(x,y,P[i],P[i+1]); if(d<b) b=d; } return b; }
function catmull(P,steps){ const out=[]; for(let i=0;i<P.length-1;i++){ const p0=P[Math.max(0,i-1)],p1=P[i],p2=P[i+1],p3=P[Math.min(P.length-1,i+2)]; for(let k=0;k<steps;k++){ const t=k/steps,t2=t*t,t3=t2*t; const f=(a,b,c2,d)=>0.5*(2*b+(-a+c2)*t+(2*a-5*b+4*c2-d)*t2+(-a+3*b-3*c2+d)*t3); out.push([f(p0[0],p1[0],p2[0],p3[0]),f(p0[1],p1[1],p2[1],p3[1])]); } } out.push(P[P.length-1]); return out; }
const inR=(x,y,r)=>x>=r[0]&&y>=r[1]&&x<r[0]+r[2]&&y<r[1]+r[3];

/* ---------- objetos de las zonas de prueba (sprites por código, cacheados) ---------- */
const SPRC={};
function sprite(key,w,h,fn,ol){ if(SPRC[key]) return SPRC[key]; const P=pix(w,h); fn(P); if(ol!==false) P.outline(0.55); return SPRC[key]=P.done(); }
