  oak:(r,v,night)=>{ r=Math.round(r); const k='oak'+r+'_'+v+(night?'n':''); const w=r*2+6, h=r*2+14; return {img:sprite(k,w,h,P=>{ const cx=w/2, cy=r+2; P.rect(Math.round(cx-2),cy+r*0.4|0,4,h-(cy+r*0.4|0)-1,C.wood[1]); P.rect(Math.round(cx-2),cy+r*0.4|0,1,h-(cy+r*0.4|0)-1,C.wood[3]); canopy(P,cx,cy,r,night?C.pine:C.leaf,v*3+1); }),ox:w/2,oy:h-1,foot:[Math.max(3,r*0.25),3]}; },
