  tent:(r,v)=>({img:sprite('tn'+v,48,34,P=>{ P.fn(0,0,48,34,(x,y)=>{ const cx=24, top=4; const half=(y-top)*0.78; if(y<top||Math.abs(x+0.5-cx)>half) return null; const side=x<cx?0.7:0.42; return qa(C.cloth,clamp(side-(y-top)/30*0.2+((x%6)===0?-0.12:0),0,1),x,y); }); P.fn(19,18,10,16,(x,y)=>Math.abs(x+0.5-24)<(y-18)*0.32+1?rgbOf('#1a120c'):null); P.rect(23,0,2,6,C.wood[1]); }),ox:24,oy:33,foot:[19,5]}),
  cart:(r,v)=>({img:sprite('ca'+v,58,40,P=>{ P.fn(4,16,50,14,(x,y)=>qa(C.wood,clamp(0.66-(y-16)/14*0.4+((x%7)===0?-0.2:0),0,1),x,y)); P.fn(6,2,46,16,(x,y)=>{ const k=(x-6)/46, top=2+Math.abs(k-0.5)*10; if(y<top) return null; return qa(C.cloth,clamp(0.78-(y-top)/16*0.35-k*0.25,0,1),x,y); });
      [[14,32],[44,32]].forEach(([cx,cy])=>{ P.ell(cx,cy,7,7,(x,y,u,vv)=>(u*u+vv*vv>0.5?qa(C.wood,0.3-u*0.2,x,y):(u*u+vv*vv<0.08?C.wood[3]:null))); P.line(cx-6,cy,cx+6,cy,C.wood[1]); P.line(cx,cy-6,cx,cy+6,C.wood[1]); }); P.rect(54,24,4,2,C.wood[2]); }),ox:29,oy:39,foot:[26,6]}),
