    if(x<20||y<14||y>GH-14||x>GW-12) return '#';
    const dr=polyD(x,y,RIV); if(dr<9){ if(rd<10&&Math.hypot(x-1116,y-420)<26) return '='; return '~'; }
    if(rd<7) return '='; if(td<4) return ':';
