    trees.sort((a,b)=>a[1]-b[1]).forEach(([x,y,r])=>{ ellipse(g,x+1,y+r*0.6,r,r*0.45,'rgba(10,20,10,.35)'); ellipse(g,x,y,r,r*0.86,'#1e3e1e'); ellipse(g,x-0.6,y-0.8,r*0.82,r*0.7,'#2e5a2a'); ellipse(g,x-r*0.3,y-r*0.35,r*0.4,r*0.32,'#4e843a'); });
