    g.globalAlpha=0.55; g.fillStyle='#6a7076'; g.fillRect(580,836,40,20); g.fillRect(574,826,10,30); g.fillRect(616,826,10,30); g.fillRect(594,822,12,14); g.globalAlpha=1;
