  if(id==='global'){ const g=ZS&&ZS.global; if(g&&g.draw&&g.nodes){ g.nodes.forEach(n=>{ if(!n.type) n.type=n.kind; }); g.exits=g.exits||[]; g.npcs=[]; g.props=[]; g.triggers=g.triggers||[]; g.rivals=g.rivals||[]; g.fixed=[]; g.ambient=g.ambient||'mapa'; g._z=true; if(!g.speed||typeof g.speed!=='function') g.speedF=g.speedAt; return ZC.global=g; } return ZC.global=mkGlobal(g); }
