function bgOk(z){ if(AUTO) return true; try{ if(fade.a>0.5) return true; }catch(e){} if(scene!==S) return !(scene&&scene.battle); if(S.busy||S.overlay||(S.idleT||0)>1.2) return true;
  if(S.Z&&S.P&&!S.global){ for(const ex of S.Z.exits){ const to=ex.to===MAPA?'global':ex.to; if(zone(to)===z&&Math.hypot(S.P.x-(ex.x+ex.w/2),S.P.y-(ex.y+ex.h/2))<140) return true; } } return false; }
function bgStep(){ const z=BGQ[0]; if(!z){ BGON=false; return; } if(!bgOk(z)){ setTimeout(bgStep,100); return; } try{ if(!z._gen) z._gen=(z.steps&&!(z.ready&&z.ready()))?z.steps():'nav'; const t0=performance.now(); while(performance.now()-t0<6){ if(z._gen!=='nav'){ const r=z._gen.next(); if(r.done){ z._gen='nav'; } } else { if(z._nav){ BGQ.shift(); z._gen=null; break; } if(!z._navG) z._navG=navJob(z); if(z._navG.next().done){ z._navG=null; BGQ.shift(); z._gen=null; break; } } } }catch(e){ console.error(e); BGQ.shift(); } setTimeout(bgStep,AUTO?0:(scene&&scene.battle?40:16)); }
