function buildNow(z){ if(!z) return; if(z.ready&&z.ready()) return; const i=BGQ.indexOf(z); if(i>=0&&z._gen&&z._gen!=='nav'){ try{ while(!z._gen.next().done){} }catch(e){} z._gen='nav'; } if(z.build) try{ z.build(); }catch(e){ console.error(e); } if(z.prep) z.prep(); }
function prewarmNow(ids,nb,pos){ ids=(ids||[]).slice(); if(nb&&pos){ const g=zone('global'); (g.nodes||[]).forEach(n=>{ if(n.zone&&!n.closed&&!n.viaZone&&!n.sub&&Math.hypot(n.x-pos.x,n.y-pos.y)<450&&!ids.includes(n.zone)) ids.push(n.zone); }); } if(nb) ids.slice().forEach(id=>{ const z=zone(id); if(z&&z.exits) z.exits.forEach(e=>{ const t=e.to===MAPA?'global':e.to; if(t&&!e.v11&&!ids.includes(t)&&zone(t)) ids.push(t); }); }); if(!AUTO&&!(nb&&pos)){ try{ const L=SAVES.latest&&SAVES.latest(), sd=L&&L.rec&&STORY[L.rec.cp], zc=sd&&sd.zone?zid(sd.zone):null; if(zc&&!ids.includes(zc)&&zone(zc)) ids.push(zc); }catch(e){} } // M1: también la zona del tramo guardado (antes se armaba de un bloque al entrar, ~0,6–1 s)
  ids.forEach(id=>{ const z=zone(id); if(!z) return; if(z.steps&&!(z.ready&&z.ready())&&!AUTO&&!(nb&&pos)&&z.kind!=='pueblo'){ /* M1 (fix 2): diorama y zonas se arman en segundo plano, en pasos cortos (antes: bloques de ~600–1000 ms en la carga o al entrar) */ const i=BGQ.indexOf(z); if(i>0) BGQ.splice(i,1); if(i!==0) BGQ.unshift(z); if(!BGON){ BGON=true; setTimeout(bgStep,16); } return; } buildNow(z); try{ navGrid(z); miniOf(z); if(z.kind==='global') globalImg(); }catch(e){} }); }
