  const w=ensure(); if(!S.global){ w.x=Math.round(P.x); w.y=Math.round(P.y); w.face=P.face; } else { w.gx=Math.round(P.x); w.gy=Math.round(P.y); fogReveal(P.x,P.y); updPlaces(); if(P.walking&&!AUTO&&nowS()-(S.gsave||0)>12){ S.gsave=nowS(); try{ SAVES.auto('zona'); }catch(e){} } }
  updCam(false);
  for(const ex of Z.exits){ if(inExit(ex,P.x,P.y)){ tryExit(ex); return; } }
  const gt=goalTrigger(); if(gt&&!gt.prop&&inR(P.x,P.y,trigRect(gt))){ reachGoal(gt); return; }
  for(const t of Z.triggers){ if(t===gt||STORYTRIG.has(t.id)) continue; if(inR(P.x,P.y,trigRect(t))&&can(t.need)&&!(t.once!==false&&w.seen['trg:'+Z.id+':'+t.id])){ fireTrigger(t); return; } }
