function nearInter(x,y,r){ const Z=S.Z; if(!Z) return false; for(const p of (Z.props||[])){ if((p.kind==='cofre'||p.kind==='esfera'||p.kind==='descanso'||p.kind==='examinable'||p.kind==='cartel'||p.kind==='mojon')&&!p.nosprite&&(Math.hypot(p.x-x,(p.y-y)*1.4)<r||(Math.abs(p.x-x)<r+2&&y-p.y>-8&&y-p.y<46))) return true; /* tampoco delante (más abajo): la figura de 128 lo taparía */ if((p.kind==='esfera'||p.kind==='descanso')&&Math.hypot(p.x-x,(p.y-y)*1.4)<r+6) return true; } for(const a of (S.npcA||[])){ if(Math.hypot(a.x-x,(a.y-y)*1.4)<r) return true; } return false; }
