function bumpWall(x,y){ const Z=S.Z, wl=(Z.walls||[]).find(r=>inR(x,y,[r.x-2,r.y-2,r.w+4,r.h+4])); if(!wl||!wl.deny) return; const n=nowS(), k='w'+wl.deny; if(S.bump[k]&&n-S.bump[k]<4) return; S.bump[k]=n; const L=linesOf(wl.deny); if(!L) return; const P=S.P; bubble(L[0][1],()=>scene===S?{x:P.x-S.cam.x,y:P.y-actorH(P)-6-S.cam.y}:null,2600,'amb'); }
