  if(Z.kind==='global'){ const n=Z.nodes.find(n=>n.zone===goalZ&&!n.sub&&!n.viaZone)||Z.nodes.find(n=>n.zone===goalZ); return n?{x:n.x,y:n.y,node:n}:null; } // v28: al nodo de la meta (todos los lugares tienen nodo)
