/* ---------- consumibles nuevos (plan 3.2 · B11) y tiendas con precios propios (B10) ----------
   Textos: LINES.items.<id>.{n,d} y LINES.arcoShop.<tienda>.{titulo,saludo} (Hermes, C07); sin texto, quedan vacíos. */
const ARC_CONS={ tonico:{target:'ally',pm:30}, pocion_mayor:{target:'ally',pv:400}, bomba_eter:{target:'foes',dmg:180,elem:'rayo'} };
const ARC_GOODS={ agnes_c2:[['pocion',15],['antidoto',10],['ruda',25]],
  gaspar:[['pocion',20],['antidoto',15],['tonico',30],['pocion_mayor',40],['bomba_eter',35]] };
const arcItemTxt=(k,f)=>((typeof LINES!=='undefined'&&LINES.items&&LINES.items[k]&&LINES.items[k][f])||'');
// lo que recupera un consumible sobre un integrante (combate y menú): {pv, pm}
function consGain(k,pvNow,pvMax,pmNow,pmMax){ const C=k==='pocion'?{pv:150}:ARC_CONS[k]; if(!C) return {pv:0,pm:0}; return {pv:C.pv?Math.max(0,Math.min(C.pv,pvMax-pvNow)):0,pm:C.pm?Math.max(0,Math.min(C.pm,(pmMax||0)-(pmNow||0))):0}; }
const ARC_DROPS={ cabo_jinetes:['panuelo_cabo'], cabo_taberna:['guantelete_rosa'], montero:['cuerno_montero'] };

/* ---------- enemigos y jefes (plan 2.x; escala de scaleUnit: PV×(1+0,12·d), ATQ/MAG +3d, DEF/RES +2d, VEL +d) ---------- */
const ARC_ENEMY={
  jinete:      {name:'Jinete de la Rosa',lvl:7,pv:470,atk:40,def:24,res:14,vel:22,pre:92,eva:8,cri:10,weak:['viento'],exp:80,oro:26,spr:'jinete'},
  cabo_jinetes:{name:'Cabo de jinetes',lvl:8,pv:2400,atk:46,def:30,res:18,vel:20,pre:92,eva:6,cri:10,weak:['rayo'],exp:150,oro:180,spr:'rc_oficial_ceniza',boss:true},
  sargento:    {name:'Sargento de la Rosa',lvl:10,pv:3400,atk:50,def:36,res:20,vel:20,pre:92,eva:6,cri:10,weak:['rayo'],exp:240,oro:0,spr:'rc_oficial',boss:true},
  cabo_taberna:{name:'Cabo de la Rosa',lvl:11,pv:3700,atk:54,def:38,res:22,vel:22,pre:92,eva:6,cri:10,weak:['rayo'],exp:290,oro:200,spr:'rc_oficial_brasa',boss:true},
  sabueso:     {name:'Sabueso de la Rosa',lvl:10,pv:520,atk:50,def:26,res:16,vel:32,pre:94,eva:16,cri:12,weak:['fuego'],exp:156,oro:10,beast:'sabueso'},
  montero:     {name:'Montero de la Rosa',lvl:13,pv:3600,atk:58,def:42,res:24,vel:26,pre:94,eva:8,cri:12,weak:['viento'],exp:380,oro:250,spr:'rc_caballero',boss:true},
  valdris:     {name:'Caballero negro',lvl:15,pv:6000,atk:70,def:60,res:40,vel:30,pre:99,eva:10,cri:15,weak:[],exp:0,oro:0,spr:'valdris',boss:true}
};
const eRefA=L=>1.5*L*L+6;
const ARC_BOSSK={cabo_jinetes:1.2,sargento:1.22,cabo_taberna:1.2,montero:1.2}; // B20: escala de dibujo de los jefes con sprite de tropa
// economía (ajuste rápido de la verificación): el botín en coronas del Arco I se paga al 72 % y el equipo de tienda nivel 2 y 3 sube un 15 %
const ARC_ECON=0.72, ARC_PRICE=1.15;
// EXP de reserva (S14) para los que no pelean, también los ausentes: 50 % → 75 % (B09: banca ≤ 1 nivel)
const ARC_RESERVA=0.75;
const arcCoreAvg=()=>{ const P=Object.assign({},G.away||{},G.party), L=['ilian','nach','maela','simona','severo'].filter(k=>P[k]).map(k=>P[k].lvl); return L.length?L.reduce((a,b)=>a+b,0)/L.length:1; };
// sube o baja una unidad ya armada a otro nivel (regla de scaleUnit; si baja, la EXP pasa a eRef(nivel), S3)
function arcScale(u,lvl){ const d=lvl-u.lvl; if(!d) return u; u.pv=u.pvMax=Math.max(1,Math.round(u.pvMax*(1+0.12*d))); u.atk+=3*d; u.mag+=3*d; u.def+=2*d; u.res+=2*d; u.vel+=d; u.lvl=lvl;
  u.exp=d>0?Math.max(u.exp,Math.round(eRefA(lvl))):Math.round(eRefA(lvl)); u.oro=d>0?Math.round(u.oro*(1+0.25*d)):u.oro; return u; }
// variantes de nivel fijo para las tablas de aleatorios (el motor de encuentros lee claves sueltas)
function arcLvlKey(key,lvl){ const b=ENEMY[key]; if(!b||b.lvl===lvl) return key; const k=key+'_n'+lvl; if(ENEMY[k]) return k; const d=lvl-b.lvl;
  ENEMY[k]=Object.assign({},b,{lvl,pv:Math.round(b.pv*(1+0.12*d)),atk:b.atk+3*d,def:b.def+2*d,res:b.res+2*d,vel:b.vel+d,exp:d>0?Math.max(b.exp,Math.round(eRefA(lvl))):Math.round(eRefA(lvl)),oro:Math.round((d>0?b.oro*(1+0.25*d):b.oro)*ARC_ECON),codexAs:key});
  SPRMAP[k]=SPRMAP[key]||key; if(LINES.barks&&LINES.barks[key]&&!LINES.barks[k]) LINES.barks[k]=LINES.barks[key]; if(ARC_AI[key]&&!ARC_AI[k]) ARC_AI[k]=ARC_AI[key]; return k; }

/* ---------- IA de los enemigos nuevos (la llama enemyTurn de p3_logic.js) ---------- */
const arcFoes=B=>B.units.filter(v=>v.side==='e'&&alive(v)), arcAllies=B=>B.units.filter(v=>v.side==='p'&&alive(v));
const ARC_AI={
  jinete: async(B,e,cfg,X)=>{ if(!X.sealed&&LR()<0.3){ const r=await X.atk('Carga',{poder:130}); if(r&&!r.r.miss&&alive(r.t)){ r.t.ct-=200; addFloat(B,{x:r.t.x,y:r.t.y+12},'Retrasado','#bbb'); } return; } await X.atk('Lanza',{poder:100}); },
  cabo_jinetes: async(B,e,cfg,X)=>{ bossBark(B,e);
    if(!X.sealed&&!e.carga&&e.pv<=e.pvMax*0.7){ e.carga=true; const L=arcTxt(2,'boss','cabo_jinetes','aLaCarga'); B.log='Cabo de jinetes: ¡A la carga!'; await X.fxOnly('en_soldado_formacion',[],()=>{ arcFoes(B).filter(v=>v.key!=='cabo_jinetes').forEach(v=>{ v.ct=1000; addFloat(B,v,'¡Carga!','#ff8a7a'); }); }); if(L&&!AUTO) await say(L[0],L[1],L[2]); hideDialog(); return; }
    if(!X.sealed&&LR()<0.45){ await X.atk('Tajo de montura',{poder:140}); return; } await X.atk('Tajo',{poder:100}); },
  sargento: async(B,e,cfg,X)=>{ bossBark(B,e); if(!X.sealed&&LR()<0.5){ await X.atk('Tajo de patio de armas',{poder:140}); return; } await X.atk('Tajo',{poder:100}); },
  cabo_taberna: async(B,e,cfg,X)=>{ bossBark(B,e); if(!X.sealed&&LR()<0.4){ const r=await X.atk('Golpe de jarra',{poder:120}); if(r&&!r.r.miss&&alive(r.t)){ r.t.st.ceguera=1; addFloat(B,{x:r.t.x,y:r.t.y+12},'Ceguera','#bbb'); } return; } await X.atk('Tajo',{poder:100}); },
  sabueso: async(B,e,cfg,X)=>{ const furia=B.aMuerte?2:1; for(let i=0;i<furia&&alive(e);i++){ const t=i?pickEnemyTarget(B,e):X.t; if(!t) return; const r0=LR();
      if(!X.sealed&&r0<0.25&&!t.st.marca){ B.log='Sabueso: Rastro.'; await X.fxOnly('en_alfa_aullido',[t],()=>{ t.st.marca=2; addFloat(B,{x:t.x,y:t.y+12},'Marca','#d96bb0'); }); continue; }
      if(!X.sealed&&r0<0.6){ const r=await X.atk('Dentellada',{poder:110},t); if(r&&!r.r.miss&&alive(r.t)&&LR()<0.6){ r.t.st.sangrado=3; addFloat(B,{x:r.t.x,y:r.t.y+12},'Sangrado','#ff8a7a'); } continue; }
      await X.atk('Mordida',{poder:100},t); } },
  montero: async(B,e,cfg,X)=>{ bossBark(B,e);
    if(!X.sealed&&!e.cuerno){ e.cuerno=true; B.log='Montero de la Rosa: Cuerno de caza.'; await X.fxOnly('en_alfa_aullido',[],()=>{ sfx('bark'); arcFoes(B).forEach(v=>{ v.st.valor=3; addFloat(B,v,'Valor','#e0ab45'); }); }); return; }
    if(!X.sealed&&LR()<0.4){ const ps=arcAllies(B), back=ps.filter(v=>v.row==='back'); const tg=back.length?lpick(back):X.t; await X.atk('Venablo',{poder:140,ranged:true},tg); return; } await X.atk('Tajo',{poder:100}); },
  valdris: async(B,e,cfg,X)=>{ const n=arcAllies(B).find(v=>v.id==='nach');
    if(e.turns===2){ B.log='El caballero negro da un paso al frente.'; await X.fxOnly('defensa',[],()=>{ addFloat(B,e,'Paso al frente','#ff8a6a'); }); return; }
    await X.atk('Tajo del Ocaso',{poder:150},n||X.t); }
};
// las coreografías: ataques y técnicas nuevas reusan las existentes (fx.js no se toca)
const ARC_FXA={descarga:'virote',canto_valor:'aullido',tajo_pesado:'mordida',flecha_veloz:'atravesante',cura:'pocion',hurtar:'corte',bomba_eter:'imp_simona_2',rafaga_punos:'corte',rafaga_eter:'virote',
  imp_dov_0:'imp_severo_1',imp_dov_2:'imp_bertram_2',imp_ysa_0:'imp_simona_1',imp_ysa_2:'imp_nach_1',imp_bram_0:'imp_simona_1',imp_bram_2:'imp_maela_0',imp_tessa_0:'imp_bertram_0',imp_tessa_2:'imp_ilian_1',
  imp_odo_0:'imp_simona_1',imp_odo_2:'imp_simona_1',imp_zarpa_0:'defensa',imp_zarpa_2:'imp_lina_2',imp_gaspar_0:'en_asesino_humo',imp_gaspar_2:'imp_severo_2',imp_agnes_0:'imp_nach_0',imp_agnes_2:'imp_lina_2',imp_darra_0:'imp_nach_1',imp_darra_2:'imp_ilian_2'};
const ARC_FXB={dov:'atk_ballesta',ysa:'atk_dagas',bram:'atk_maza',tessa:'atk_arco',odo:'atk_baston',zarpa:'atk_dagas',gaspar:'atk_baston',agnes:'atk_garra',darra:'atk_espada',
  jinete:'atk_espada',cabo_jinetes:'atk_espada',sargento:'atk_espada',cabo_taberna:'atk_maza',sabueso:'atk_mordida',montero:'atk_espada',valdris:'atk_espada'};
const ARC_FXE={'Venablo':'atk_arco','Golpe de jarra':'atk_maza','Tajo del Ocaso':'oswin_mandoble_ceniza','Dentellada':'en_alfa_desgarro','Mordida':'atk_mordida'};
try{ const g0=FX.get, b0=FX.basic, e0=FX.enemy;
  FX.get=k=>{ const q=g0(k); return q||(ARC_FXA[k]?g0(ARC_FXA[k]):q); };
  FX.basic=(id,w)=>ARC_FXB[id]||b0(id,w);
  FX.enemy=(k,n)=>ARC_FXE[n]||(ARC_FXB[k]&&!/Formación|Aullido/.test(n)?ARC_FXB[k]:e0(k,n)); }catch(e){ console.error(e); }

/* ---------- técnicas especiales nuevas (las llama execPlayer de p3_logic.js) ---------- */
const ARC_SPEC={
  cura: async(B,u,a,x)=>{ const t=a.target; await runFX(B,'cura',{user:u,targets:[t],onApply:()=>{ const h=Math.min(Math.round(t.pvMax*(x.pct||0.35)),t.pvMax-t.pv); t.pv+=h; addFloat(B,t,'+'+h,'#8fe08f'); sfx('heal'); }}); return 'normal'; },
  veloz: async(B,u,a,x)=>{ await runFX(B,'flecha_veloz',{user:u,targets:[a.target],jobs:[J('main',()=>applyDamage(B,u,a.target,{poder:x.poder,elem:x.elem,ranged:true,tech:true}))]}); return 'light'; },
  hurtar: async(B,u,a,x)=>{ let r=null; await runFX(B,'hurtar',{user:u,targets:[a.target],jobs:[J('main',async()=>{ r=await applyDamage(B,u,a.target,{poder:x.poder,tech:true}); })]});
    if(r&&!r.r.miss&&LR()<0.3){ G.items.pocion=(G.items.pocion||0)+1; addFloat(B,{x:u.x,y:u.y-10},'¡Poción!','#ffd46a'); } return 'normal'; },
  area: async(B,u,a,x)=>{ const ts=arcFoes(B); await runFX(B,'bomba_eter',{user:u,targets:ts,jobs:[J('main',async()=>{ for(const t of ts) if(alive(t)) await applyDamage(B,u,t,{poder:x.poder,kind:x.kind,elem:x.elem,ranged:true,area:true,tech:true}); })]}); return 'normal'; },
  prisa: async(B,u,a,x,k)=>{ await runFX(B,'imp_'+u.id+'_0',{user:u,onApply:()=>{ arcAllies(B).forEach(v=>{ if(v!==u){ v.ct=Math.max(v.ct,700); addFloat(B,v,'Prisa','#9fd6f4'); } }); }}); return 'normal'; },
  balada: async(B,u,a,x)=>{ await runFX(B,'imp_'+u.id+'_2',{user:u,cine:true,cutin:[[u.id],x.name,'Definitiva'],onApply:()=>{ arcAllies(B).forEach(v=>{ v.st.proteccion=3; v.st.valor=3; delete v.st.miedo; addFloat(B,v,'Protección','#9fd6f4'); }); }}); return 'normal'; },
  forja: async(B,u,a,x)=>{ await runFX(B,'imp_'+u.id+'_0',{user:u,onApply:()=>{ arcAllies(B).forEach(v=>{ v.st.furia=2; addFloat(B,v,'Furia','#ff8a7a'); }); }}); return 'normal'; },
  limpia: async(B,u,a,x)=>{ await runFX(B,'imp_'+u.id+'_0',{user:u,onApply:()=>{ arcAllies(B).forEach(v=>{ ['veneno','sangrado','ceguera','sello','marca','miedo','condena','lento'].forEach(k=>delete v.st[k]); addFloat(B,v,'Limpio','#8fe08f'); }); sfx('heal'); }}); return 'normal'; },
  brindis: async(B,u,a,x)=>{ await runFX(B,'imp_'+u.id+'_2',{user:u,cine:true,cutin:[[u.id],x.name,'Definitiva'],onApply:()=>{ arcAllies(B).forEach(v=>{ ['veneno','sangrado','ceguera','sello','marca','miedo','condena','lento'].forEach(k=>delete v.st[k]); const h=Math.min(Math.round(v.pvMax*0.5),v.pvMax-v.pv); v.pv+=h; addFloat(B,v,'+'+h,'#8fe08f'); }); sfx('heal'); }}); return 'normal'; },
  pies: async(B,u,a,x)=>{ await runFX(B,'imp_'+u.id+'_0',{user:u,onApply:()=>{ u.st.humo=3; addFloat(B,u,'Pies Ligeros','#9fd6f4'); }}); return 'normal'; },
  sieteVidas: async(B,u,a,x)=>{ const ts=arcFoes(B); await runFX(B,'imp_'+u.id+'_2',{user:u,targets:ts,cine:true,cutin:[[u.id],x.name,'Definitiva'],jobs:[J('main',async()=>{ for(let i=0;i<7;i++){ const L=arcFoes(B); if(!L.length) break; await applyDamage(B,u,lpick(L),{poder:60,elem:'sombra',imp:true,tech:true,area:true}); } })]}); return 'normal'; },
  humoE: async(B,u,a,x)=>{ const ts=arcFoes(B); await runFX(B,'imp_'+u.id+'_0',{user:u,targets:ts,onApply:()=>{ ts.forEach(v=>{ v.st.ceguera=2; addFloat(B,v,'Ceguera','#bbb'); }); }}); return 'normal'; },
  cuentaDiez: async(B,u,a,x)=>{ let t=a.target; await runFX(B,'imp_'+u.id+'_2',{user:u,targets:[t],cine:true,cutin:[[u.id],x.name,'Definitiva'],jobs:[J('main',async()=>{ for(let i=0;i<10;i++){ if(!t||!alive(t)) t=arcFoes(B)[0]; if(!t) break; await applyDamage(B,u,t,{poder:40,imp:true,tech:true}); } })]}); return 'normal'; },
  columna: async(B,u,a,x)=>{ const t=a.target; await runFX(B,'imp_'+u.id+'_2',{user:u,targets:[t],cine:true,cutin:[[u.id],x.name,'Definitiva'],jobs:[J('main',async()=>{ if(alive(t)) await applyDamage(B,u,t,{poder:320,elem:'rayo',imp:true,tech:true}); }),J('post',async()=>{ u.st.lento=2; addFloat(B,u,'Lenta','#bbb'); })]}); return 'normal'; }
};

/* ---------- registro: personajes, equipo, enemigos, nombres y sprites ---------- */
(function arcRegister(){ try{
  const GRADE=(id,k,v)=>{ // letra por cercanía a los personajes del Cap. 1 (misma escala que EQUIP.grades)
    let best='C',bd=1e9; ['ilian','nach','maela','simona','severo','bertram','lina'].forEach(o=>{ const n=EQUIP.naked[o], g=CHAR[o].gr, w=(n[k]||0)+7*(g[k]||0); const d=Math.abs(w-v); if(d<bd&&EQUIP.grades[o]){ bd=d; best=EQUIP.grades[o][k]; } }); return best; };
  Object.keys(ARC_REC).forEach(id=>{ const R=ARC_REC[id], st=ARC_START[id];
    CHAR[id]={name:R.name,row:R.row,base:R.base,gr:R.gr,ranged:!!R.ranged,reach:!!R.reach,elem:R.elem||null,tech:R.tech.slice(),link:R.link.slice()};
    if(!R.elem) delete CHAR[id].elem;
    const nk=Object.assign({},R.base); [st[0],st[1]].forEach(([iid,nm,kind,stats,desc],i)=>{ for(const k in stats) nk[k]-=stats[k];
      EQUIP.items[iid]={slot:i?'armadura':'arma',kind,who:[id],stats,tags:[],price:0,source:'inicial',name:'s/d',desc:'s/d'}; MENUTXT.equip[iid]={name:nm,desc:Object.keys(stats).map(k=>k.toUpperCase()+' +'+stats[k]).join(', ')+'. '+desc}; });
    EQUIP.naked[id]=nk; EQUIP.start[id]={arma:st[0][0],arma2:null,armadura:st[1][0],accesorio:null};
    const gr={}; ['pv','pm','atk','mag','def','res','vel'].forEach(k=>{ gr[k]=GRADE(id,k,(nk[k]||0)+7*(R.gr[k]||0)); }); ['pre','eva','cri'].forEach(k=>{ gr[k]=GRADE(id,k,nk[k]||0); }); EQUIP.grades[id]=gr;
    IMP[id]=ARC_IMP[id]; });
  Object.assign(TECH,ARC_TECH);
  Object.keys(ARC_ITEMS).forEach(k=>{ const d=ARC_ITEMS[k]; EQUIP.items[k]={slot:d.slot,kind:d.kind,who:d.who.slice(),stats:d.stats,tags:d.tags||[],price:Math.round(d.price*ARC_PRICE/5)*5,source:d.source||'tienda',name:'s/d',desc:'s/d'}; MENUTXT.equip[k]={name:d.name,desc:d.desc}; });
  // los accesorios del Cap. 1 también los pueden usar los reclutas
  ['talisman_impetu','amuleto_antiveneno','colmillo_alfa'].forEach(k=>{ const it=EQUIP.items[k]; if(it) Object.keys(ARC_REC).forEach(id=>{ if(!it.who.includes(id)) it.who.push(id); }); });
  Object.assign(EQUIP.shop,ARC_SHOP,{agnes_c2:[]}); Object.assign(EQUIP.drops,ARC_DROPS);
  Object.keys(ARC_CONS).forEach(k=>{ const D={target:ARC_CONS[k].target}; Object.defineProperty(D,'name',{get:()=>arcItemTxt(k,'n'),enumerable:true}); Object.defineProperty(D,'desc',{get:()=>arcItemTxt(k,'d'),enumerable:true}); ITEMS[k]=D;
    const M={}; Object.defineProperty(M,'name',{get:()=>arcItemTxt(k,'n'),enumerable:true}); Object.defineProperty(M,'desc',{get:()=>arcItemTxt(k,'d'),enumerable:true}); MENUTXT.items[k]=M; });
  Object.assign(ENEMY,ARC_ENEMY);
  // sprites, nombres, voces y colores de nombre (sin arte nuevo: tropas de TROPA_C, vecinos y la variante de lobo)
  // arte de Brian (LDC_PL128): el jinete (y rc_lancero) usan la hoja PixelLab «jinete» (v26); Gaspar, los dos cabos, el sargento y el montero tienen hoja propia (SPR cae en la tropa de PXFB si no llegó)
  Object.assign(SPRMAP,{gaspar:'gaspar',comerciante:'gaspar',jinete:'jinete',rc_lancero:'jinete',cabo_jinetes:'cabo_jinetes',sargento:'sargento',cabo_taberna:'cabo_taberna',montero:'montero',
    merc_mudo:'guardia',pregonero:'aldeano',refugiada:'aldeana',anguilero:'anciano',viuda:'aldeana',merc_ruy_c:'guardia'});
  Object.assign(NPCNAME,{dov:'Dov',ysa:'Ysa',zarpa:'Zarpa',darra:'Darra',gaspar:'Gaspar',jinete:'Jinete',cabo_jinetes:'Cabo de jinetes',sargento:'Sargento',cabo_taberna:'Cabo de la Rosa',montero:'Montero',
    sabueso:'Sabueso',merc_mudo:'El Mudo',pregonero:'Pregonero',refugiada:'Refugiada',anguilero:'Anguilero',viuda:'Viuda'});
  Object.assign(VOICE,{dov:44,ysa:76,zarpa:72,darra:58,gaspar:56,jinete:48,cabo_jinetes:46,sargento:42,cabo_taberna:44,montero:40,merc_mudo:50,pregonero:52,refugiada:64,anguilero:46,viuda:66});
  Object.assign(NAMECOL,{dov:'#c0603a',ysa:'#5aa29a',zarpa:'#c9b48a',darra:'#7fa8d0',gaspar:'#c9973c',sargento:'#a3313b',cabo_jinetes:'#a3313b',cabo_taberna:'#a3313b',montero:'#a3313b',jinete:'#a3313b'});
}catch(e){ console.error('[arco1] registro',e); } })();

/* ---------- balance por tramo (pulido, carril B · B05 a B09) ----------
   ARC_TUNE[<tramo>] se aplica encima de lo que pide capN_mundo.js (que no se toca): enemigos y niveles, y por clave de enemigo
   PV (hp ×), ATQ (atk ×), DEF (def +), EXP (exp ×) y coronas (oro ×); fases (phaseAt: {'clave@umbral': umbral nuevo}).
   '#prueba&notune=1' lo apaga (para medir contra v25). */
const ARC_TUNE={
  // Cap. 2 · el cabo de jinetes tumbaba a uno (KO 1 en 2 de 3 semillas; objetivo 0): menos golpe y menos críticos
  c2_jefe:{mod:{cabo_jinetes:{atk:0.91,cri:-6},jinete:{atk:0.91,cri:-6}}},
  // Cap. 3 · el grupo llegaba al sargento en 8,8 (objetivo 9–9,7): más EXP en C3-1 y C3-2 (y la reserva también para Ilian de batida, p3_logic.js)
  c3_patrulla:{mod:{'*':{exp:1.35}}}, c3_callejon:{mod:{'*':{exp:1.35}}}, c3_jefe:{mod:{sargento:{atk:0.98}}},
  // Cap. 4 · salía en 10,8 (objetivo 11) y el cabo no apretaba (PV mínimo 51–63 %; objetivo 15–45 %)
  c4_edicto:{mod:{'*':{exp:1.5}}}, c4_patio:{mod:{'*':{exp:1.5}}},
  c4_jefe:{mod:{cabo_taberna:{atk:1.4,hp:1.05,exp:1.3},soldado:{atk:1.3,exp:1.3}}},
  // Cap. 5 · el Montero tiene que pesar más que los sabuesos y el combate variaba de 52 % a 2 % de PV mínimo según la semilla
  c5_jefe:{mod:{montero:{atk:1.12,hp:0.92},sabueso:{atk:0.85}}},
  // el caballero negro: en una semilla tumbaba a Nach (PV mínimo 0 %; objetivo 10–30 %). v27 (O6): también menos críticos (la tirada se hace igual)
  c5_valdris:{mod:{valdris:{atk:0.93,cri:-15}}}
};
// regalos de historia (B09: pociones que no se acumulan solas). Por tramo: lo que se entrega en vez de lo que pide capN_mundo.js
const ARC_GIFT={ c3_ruy:{pocion:1}, c4_carrera:{pocion:1}, c4_agnes:{pocion:0} };
function arcTune(cfg){ const T=(AUTO&&/notune=1/.test(location.hash))?null:ARC_TUNE[G&&G.cp]; if(!T) return {cfg};
  const c=Object.assign({},cfg); if(T.enemies) c.enemies=T.enemies.slice();
  if(T.phaseAt&&cfg.phases) c.phases=cfg.phases.map(p=>{ const k=p.key+'@'+p.at; return k in T.phaseAt?Object.assign(p,{at:T.phaseAt[k]}):p; });
  if(T.endAt&&cfg.endAt) c.endAt=Object.assign({},cfg.endAt,T.endAt);
  return {cfg:c,mod:T.mod||null}; }
function arcTuneUnits(B,T0){ const M=T0.mod; if(!M) return; B.units.filter(u=>u.side==='e').forEach(u=>{ const m=M[u.key]||M['*']; if(!m) return;
  if(m.hp){ u.pvMax=u.pv=Math.round(u.pvMax*m.hp); } if(m.atk){ u.atk=Math.round(u.atk*m.atk); u.mag=Math.round(u.mag*m.atk); } if(m.def) u.def+=m.def; if(m.vel) u.vel+=m.vel; if(m.cri) u.cri=Math.max(0,u.cri+m.cri);
  if(m.exp) u.exp=Math.round(u.exp*m.exp); if(m.oro!=null) u.oro=Math.round(u.oro*m.oro); }); }

/* ---------- combate del Arco I ----------
   cfg = {zone, party:[ids] (o null = el grupo de 5 elegido), must:[ids], enemies:[clave | [clave,nivel]], music,
          phases:[{at:0.6, key, scene, run(B,u)}], endAt:{key,pv} | {key,turns} | {ally,pv}, noLose, quiet, boss, minPv:{key:frac}, guest:[ids], intro} */
function arcParty(list,must){ let L=(list||(typeof WORLD!=='undefined'&&WORLD.partyIds?WORLD.partyIds():Object.keys(G.party))).filter(id=>G.party[id]);
  if(!list) L=L.slice(0,5); (must||[]).forEach(id=>{ if(G.party[id]&&!L.includes(id)){ if(L.length>=5) L.pop(); L.unshift(id); } }); return L; }
async function arcFight(cfg){
  const T0=arcTune(cfg); cfg=T0.cfg;
  const keys=[], lv=[]; (cfg.enemies||[]).forEach(e=>{ if(Array.isArray(e)){ keys.push(e[0]); lv.push(e[1]); } else { keys.push(e); lv.push(null); } });
  if(cfg.boss&&!AUTO&&!cfg.party&&Object.keys(G.party).length>5&&cfg.pick!==false&&!arcPickOff()) await arcPickParty(cfg); // posadas: no sale si un punto de formación ya cubrió el tramo (G.flags.pf) ni con el caballero negro
  // v27: el aviso «Antes del jefe» va ANTES de armar el grupo (en v26 iba después y el cambio no llegaba a este combate)
  const party=arcParty(cfg.party,cfg.must);
  const c=Object.assign({},cfg,{enemies:keys,party,arc:true,music:cfg.music||'batalla',zone:(ENV.zones.includes(cfg.zone)?cfg.zone:'prados')});
  c.intro=async B=>{ B.units.filter(u=>u.side==='e').forEach((u,i)=>{ if(lv[i]) arcScale(u,lv[i]); u.oro=Math.round(u.oro*ARC_ECON); }); if(cfg.boss){ B.boss=true; B.unisonDone=true; } /* el bloqueo del auto es solo del tutorial de Oswin */ B.arcCfg=cfg; arcTuneUnits(B,T0); if(cfg.intro) await cfg.intro(B); arcStatOpen(B,cfg); renderHUD(B,null); };
  c.onAfter=async B=>{ arcStatTick(B);
    { const a=B.active; if(a&&a.st&&a.st.lento>0){ a.st.lento--; if(a.st.lento<=0) delete a.st.lento; } } // «Lenta» dura sus turnos
    // fases por datos (S4): al cruzar el umbral de PV del jefe, una vez
    for(const ph of (cfg.phases||[])){ if(ph.done) continue; const u=B.units.find(v=>v.side==='e'&&v.key===ph.key&&alive(v)); if(!u||u.pv>u.pvMax*ph.at) continue; ph.done=true;
      if(ph.scene&&LINES.scenes[ph.scene]) await playScene(ph.scene,battleCtx(B,ph.hooks||{})); const lg0=B.log; if(ph.run) await ph.run(B,u); if(B.log&&B.log!==lg0&&!AUTO) try{ FX.title(B.log.replace(/[.:]\s*$/,'')); }catch(e){} /* B20: cartel de fase con el nombre que ya tiene la fase */ hideDialog(); renderHUD(B,null); }
    // piso de PV (Valdris no baja del 70 %)
    for(const k in (cfg.minPv||{})){ const u=B.units.find(v=>v.side==='e'&&v.key===k); if(u&&u.pv<u.pvMax*cfg.minPv[k]){ u.pv=Math.round(u.pvMax*cfg.minPv[k]); } }
    // fin por guion y aguante (S5)
    let end=false; const E=cfg.endAt;
    if(E){ if(E.key&&E.pv!=null){ const u=B.units.find(v=>v.side==='e'&&v.key===E.key); if(u&&(!alive(u)||u.pv<=u.pvMax*E.pv)) end=true; }
      if(E.key&&E.turns!=null){ const u=B.units.find(v=>v.side==='e'&&v.key===E.key); if(u&&u.turns>=E.turns) end=true; }
      if(E.ally&&E.pv!=null){ const a=B.units.find(v=>v.side==='p'&&v.id===E.ally); if(a&&a.pv<=a.pvMax*E.pv) end=true; }
      if(E.alt&&E.alt(B)) end=true; }
    if(cfg.noLose&&!B.units.some(v=>v.side==='p'&&alive(v))){ end=true; B.units.filter(v=>v.side==='p').forEach(v=>{ v.pv=1; }); }
    if(end){ B.scripted=true; B.units.filter(v=>v.side==='e').forEach(v=>{ v.pv=0; }); }
  };
  await battle(c); arcStatClose(CUR.B,'win');
  return CUR.B;
}
/* ---------- registro de combate para balance (tools/verify/balance.js lee ARC.dbg.fights) ----------
   por combate: tramo, jefe, acciones por unidad, PV mínimo del grupo (total y del más golpeado, en % del máximo), KO, objetos usados y resultado */
function arcStatOpen(B,cfg){ if(typeof ARC==='undefined') return; const F=ARC.dbg.fights||(ARC.dbg.fights=[]);
  const prev=F[F.length-1]; if(prev&&prev.open){ prev.res='lose'; prev.open=false; arcStatFill(prev,prev._B); delete prev._B; }
  const R={cp:G.cp,boss:!!cfg.boss,keys:B.units.filter(u=>u.side==='e').map(u=>u.key+':'+u.lvl),party:B.units.filter(u=>u.side==='p').map(u=>u.id+':'+u.lvl),pocion:G.items.pocion||0,minTot:1,minInd:1,ko:[],open:true,_B:B}; F.push(R); B.arcStat=R; }
function arcStatTick(B){ const R=B.arcStat; if(!R) return; const ps=B.units.filter(u=>u.side==='p'); let a=0,m=0; ps.forEach(u=>{ a+=Math.max(0,u.pv); m+=u.pvMax; R.minInd=Math.min(R.minInd,Math.max(0,u.pv)/u.pvMax); if(u.pv<=0&&!R.ko.includes(u.id)) R.ko.push(u.id); }); if(m) R.minTot=Math.min(R.minTot,a/m); }
function arcStatFill(R,B){ if(!B) return; arcStatTick(B); R.turns={}; B.units.forEach(u=>{ R.turns[u.side==='e'?u.id:u.id]=(u.turns||0); }); R.eTurns=B.units.filter(u=>u.side==='e').reduce((s,u)=>s+(u.turns||0),0); R.items=B.itemsUsed||0;
  R.minTot=Math.round(R.minTot*100); R.minInd=Math.round(R.minInd*100); R.scripted=!!B.scripted; }
function arcStatClose(B,res){ const R=B&&B.arcStat; if(!R||!R.open) return; R.open=false; R.res=res; arcStatFill(R,B); delete R._B; }
// S6 (simple): antes de un jefe, el jugador puede revisar el grupo y su orden (Menú › Grupo; pelean los 5 primeros)
function arcPickOff(){ try{ return POSADAS.pickOff(G.cp); }catch(e){ return false; } }
async function arcPickParty(cfg){ while(true){ const P=arcParty(null,cfg.must); hideDialog();
  const v=await choose([{label:'Pelear con este grupo',sub:P.map(id=>CHAR[id].name).join(', '),value:'go',cls:'primary',auto:true,icon:'go'},{label:'Cambiar el grupo',sub:'Menú › Grupo: pelean los 5 primeros',value:'grp',icon:'banner'}],'Antes del jefe');
  if(v!=='grp') return; openPause('grupo',{mode:'formacion'}); await new Promise(r=>{ const iv=setInterval(()=>{ if(!PZ.open){ clearInterval(iv); r(); } },120); }); } }

/* ==================== MÓDULO arco1/historia.js ==================== */
/* ============================================================
   ARCO I · HISTORIA (Tanda 0 · Hefesto) — pegamento común de los Caps. 2 a 5
   · carga los textos de Hermes (LINES.capN, LINES.sq) en las estructuras del juego (escenas, elenco, zonas, frases, Diario, fichas…)
   · ARC.cap(n, {order, steps, names}) registra los tramos de cada capítulo; ARC.install(ORDER,STEPS,STEPNAME) los suma después del Cap. 1 (p6_steps.js)
   · ayudas de puesta: escenas en escenario pintado o en la zona, combates en el lugar, cartel de capítulo, reclutas (S2), ausencia y líder (S7),
     objetos clave (S11), banderas y ganchos de Hermes (README de guion-arco1 §2)
   ============================================================ */
const ARC=(()=>{
const CAPS=[];           // [{n, order:[ids], steps:{}, names:{}}]
const dbg={log:[]};      // registro para pruebas (#prueba): pasos, reclutas, decisiones
const T=(n)=>(typeof LINES!=='undefined'&&LINES['cap'+n])||{};

/* ---------- textos de Hermes → estructuras del juego ---------- */
// actores que entran con 'show' (empiezan ocultos) y hablantes que no tienen que estar en cuadro
const OFFSTAGE={c2_senda_carbonera:['sargento']};
function firstUse(cmds,id){ for(const c of cmds){ if(!Array.isArray(c)) continue; if(c[0]==='if'){ const r=firstUse(c[2]||[],id)||firstUse(c[3]||[],id); if(r) return r; continue; } if(c[0]==='?'){ for(const q of c[1]){ const r=firstUse(q.do||[],id); if(r) return r; } continue; }
    if(c[1]===id&&['show','hide','say','think','whisper','walk','emote','anim','gest','approach','step','back','turn','faceTo','jump','cam','ono'].includes(c[0])) return c[0]; } return null; }
function merge(n){ const L=T(n); if(!L.scenes) return;
  Object.assign(LINES.scenes,L.scenes);
  const cast={}; Object.keys(L.cast||{}).forEach(k=>{ const off=OFFSTAGE[k]||[]; cast[k]=L.cast[k].filter(id=>!off.includes(id)); const sc=L.scenes[k]||[];
    const ent=cast[k].filter(id=>firstUse(sc,id)==='show'); if(ent.length) ENTER[k]=(ENTER[k]||[]).concat(ent); });
  LINES.cast['cap'+n]=cast;
  Object.assign(LINES.zones,L.zones||{});
  (L.escenaMeta||[]).forEach(E=>{ if(!(LINES.escenas||(LINES.escenas=[])).some(x=>x.id===E.id)) LINES.escenas.push(Object.assign({stage:STAGE_AF[E.id]||'noche'},E)); });
  Object.assign(LINES.escenaLabels||(LINES.escenaLabels={}),L.escenaLabels||{});
  if(L.aff&&L.aff.scene) Object.assign(LINES.aff.scene,L.aff.scene);
  Object.keys(L.barks||{}).forEach(id=>{ LINES.barks[id]=Object.assign({},LINES.barks[id]||{},L.barks[id]); });
  (L.duo||[]).forEach(d=>LINES.duo.push(d));
  Object.keys(L.noCierra||{}).forEach(id=>{ LINES.noCierra[id]=L.noCierra[id]; if(!LINES.noCierraOrden.includes(id)) LINES.noCierraOrden.push(id); });
  Object.keys(L.fichas||{}).forEach(id=>{ FICHAS[id]=Object.assign({},FICHAS[id]||{},L.fichas[id]); if(!FICHAS.orden.includes(id)) FICHAS.orden.push(id);
    const F=L.fichas[id]; if(!MENUTXT.profiles[id]) MENUTXT.profiles[id]={title:F.clase||'s/d',epithet:F.raza||'',bio:F.nota||'',likes:'',quote:F.cita||''}; });
  const D=L.diario||{}; try{ Object.assign(CXT.chron,D.chron||{}); Object.keys(D.chron||{}).forEach(k=>{ if(!CXSTEPS.includes(k)) CXSTEPS.push(k); }); Object.assign(CXT.now,D.now||{}); (D.places||[]).forEach(p=>{ if(!CXT.places.some(q=>q.id===p.id)) CXT.places.push(p); }); Object.keys(D.people||{}).forEach(k=>{ if(!CXT.people[k]) CXT.people[k]=D.people[k]; }); }catch(e){ console.error(e); }
  try{ const C=L.codex||{}; Object.assign(CXT.enemies,C.enemies||{}); Object.keys(C.enemies||{}).forEach(k=>{ if(!CXBEST.includes(k)) CXBEST.push(k); }); }catch(e){}
  Object.keys(L.keyItems||{}).forEach(k=>{ KEYS[k]=L.keyItems[k]; });
  Object.keys(L.items||{}).forEach(k=>{ const it=EQUIP.items[k], M=MENUTXT.equip[k]; if(it&&M){ M.name=L.items[k].n; M.desc=Object.keys(it.stats).map(q=>q.toUpperCase()+' +'+it.stats[q]).join(', ')+(Object.keys(it.stats).length?'. ':'')+L.items[k].d; } });
}
const STAGE_AF={af_otravez:'noche',af_mella:'taberna',af_cicatrices:'taberna',af_lista:'pantano'};
const KEYS={};
function mergeAll(){ [2,3,4,5].forEach(n=>{ try{ merge(n); }catch(e){ console.error('[arco1] textos cap '+n,e); } });
  try{ const S=LINES.sq||{}; if(S.bota&&S.bota.keyItems) Object.assign(KEYS,S.bota.keyItems); }catch(e){} }
mergeAll();
try{ Object.assign(ROOMSTAGE,{herreria:1,capilla:1,casa:1}); }catch(e){}

/* ---------- banderas (G.flags + mundo, así las leen 'if' {flag}, can() y los textos) ---------- */
function set(k,v){ if(!G) return; G.flags[k]=v==null?1:v; try{ WORLD.flag(k,v==null?true:v); }catch(e){} }
function has(k){ return !!(G&&((G.flags&&G.flags[k]&&typeof G.flags[k]!=='object')||(G.flags.hol&&G.flags.hol[k])||(()=>{ try{ return WORLD.flag(k); }catch(e){ return false; } })())); }
function txt(n,...p){ let o=T(n); for(const k of p){ if(o==null) return null; o=o[k]; } return o; }
function log(x){ dbg.log.push(x); }

/* ---------- reclutas (S2) ---------- */
function join(id,minLvl,quiet){ if(!G||G.party[id]) return; const avg=arcCoreAvg(); /* B09: nivel de ingreso contra el núcleo (antes, contra todo el grupo, que ya incluía reclutas atrasados) */
  const lvl=Math.max(minLvl||2,Math.round(avg)-1); G.party[id]=mkMember(id,lvl); if(G.order&&!G.order.includes(id)) G.order.push(id); markMet(id); set('rec_'+id);
  if(!G.sealed.includes(id)) seal(id); if(!AUTO) warmPartyArt([id]); if(!quiet) toast('Se suma '+CHAR[id].name+' · Nv '+lvl,2400); log('join:'+id+':'+lvl); }
// S7: ausencia temporal sin memberLeaves (conserva equipo y nivel)
function away(id){ if(!G.party[id]) return; (G.away||(G.away={}))[id]=G.party[id]; delete G.party[id]; log('away:'+id); }
function back(id){ if(!G.away||!G.away[id]) return; G.party[id]=G.away[id]; delete G.away[id]; log('back:'+id); }
function leader(id){ const ids=WORLD.partyIds(); G.order=[id].concat(ids.filter(x=>x!==id)); }
// S11: objetos clave (Objetos › Clave)
function key(k,on){ const K=G.keyItems||(G.keyItems={}); if(on===false){ delete K[k]; return; } if(K[k]) return; K[k]=1; const D=KEYS[k]; if(D&&!AUTO){ toast('Recuerdo: '+D.n,2200); lootPop(['key_'+k]); } }
function keyItem(k){ return KEYS[k]||null; }
function give(items,msg){ const names=[]; { const T=(typeof ARC_GIFT!=='undefined'&&!(AUTO&&/notune=1/.test(location.hash)))?ARC_GIFT[G&&G.cp]:null; if(T&&Object.keys(T).some(k=>k in items)){ items=Object.assign({},items,T); Object.keys(items).forEach(k=>{ if(!items[k]) delete items[k]; }); const k2=(typeof LINES!=='undefined'&&LINES.giftTune&&LINES.giftTune[G.cp])||null; msg=k2; } } /* B09 */ Object.keys(items).forEach(k=>{ const n=items[k]; if(k==='oro'){ G.oro+=n; names.push(n+' coronas'); return; } if(EQUIP.items[k]){ gearAdd(k,n); names.push(MENUTXT.equip[k].name); return; } G.items[k]=(G.items[k]||0)+n; names.push((n>1?n+' × ':'')+((MENUTXT.items[k]||{}).name||k)); });
  if(!AUTO){ toast(msg||('Recibís: '+names.join(', ')),2400); lootPop(Object.keys(items)); } }

/* ---------- puesta en escena ---------- */
// ganchos de Hermes que se resuelven igual en todos los capítulos (los de cada paso se suman encima)
function hooks(extra){ const H={
  explorar:async()=>{}, finPorGuion:async()=>{}, battle:async()=>{},
  musicaSilencio:async()=>{ stopMusic(); }, musicaHermanos:async()=>{ playMusic('hermanos'); }, musicaCorte:async()=>{ stopMusic(); },
  severoLibre:async()=>{ if(G.flags.severo!=='libre'){ G.flags.severo='libre'; } set('severo_libre'); },
  capFin:async()=>{} };
  ['joinDov','joinYsa','joinBram','joinOdo','joinTessa','joinGaspar','joinZarpa','joinAgnes','joinDarra'].forEach(h=>{ if(!H[h]) H[h]=async()=>{ join(h.slice(4).toLowerCase(),CAPMIN[G.chap]||7); }; });
  try{ if(typeof RECL!=='undefined') Object.assign(H,RECL.hooks); }catch(e){} // v27: zarpaSeVa / zarpaFirme (reclutas.js)
  return Object.assign(H,extra||{}); }
const CAPMIN={2:7,3:9,4:10,5:11};
async function stage(bg,name,hk,opt){ opt=opt||{}; if(opt.music) playMusic(opt.music); const st=await stageIn(bg,name,opt.ms||600,opt); await playScene(name,stageCtx(st,hooks(hk))); hideDialog(); if(!opt.keep) await fadeTo(1,opt.out||400); return st; }
async function world(name,at,hk,opt){ opt=opt||{}; const st=await WORLD.sceneIn(name,{at,ms:opt.ms||400,music:opt.music}); await playScene(name,stageCtx(st,hooks(hk))); hideDialog(); if(opt.keep) return st; await WORLD.back(st); return st; }
// escena pintada desde el pueblo (charla con un vecino en su interior) y vuelta a explorar Hollin donde estaba
async function townScene(api,bg,name,hk,opt){ hideDialog(); await fadeTo(1,300); await stage(bg,name,hk,Object.assign({keep:true},opt||{})); await fadeTo(1,300);
  setScene(api.S); CUR.sayStage=api.S; CUR.sayGet=id=>api.actors[id]||null; hideDialog(); await fadeTo(0,300); }
// combate en el lugar: el escenario de la escena vuelve armado después
async function fightIn(st,cfg){ await fadeTo(1,300); const B=await arcFight(cfg); await fadeTo(1,150); setScene(st); CUR.sayStage=st; CUR.sayGet=st.get; hideDialog(); st.cam.tbars=0; await fadeTo(0,350); return B; }
// entra a una zona (si no está ya) en una marca o punto
async function enter(zid,at){ const w=WORLD.ensure(); const Z=WORLD.zone(zid); if(!Z) return; if(WORLD.scene.Z&&WORLD.scene.Z.id===zid&&w.zone===zid) return; const m=typeof at==='string'?(Z.marks||{})[at]:at; await fadeTo(1,300); await WORLD.enter(zid,m?{x:m.x,y:m.y,face:1}:null); }
// cartel de capítulo: cierra el anterior y abre el nuevo (S1); autoguardado de capítulo
// B26: mientras corre el cartel se precalientan, en segundo plano, las zonas y los fondos de combate del capítulo que empieza
const CAPWARM={2:{z:['aldea','carboneros','sirga'],b:['sauces','noche','taberna']},3:{z:[],b:['prados','noche']},4:{z:['albardon'],b:['pantano','noche','taberna']},5:{z:['granja_vieja','juncal'],b:['campamento','pantano']}};
function capWarm(n){ if(AUTO) return; const C=CAPWARM[n]; if(!C) return; try{ if(WORLD.prewarm) WORLD.prewarm(C.z); }catch(e){} try{ C.b.forEach(z=>ENV.prewarm([z],false,true)); }catch(e){} try{ warmPartyArt(); }catch(e){} }
async function card(n){ const L=T(n).cartel||{n,titulo:'',fecha:''}; G.chap=n; brand(); hideDialog(); stopMusic(); playMusic('title'); capWarm(n);
  const prev=n===2?'Capítulo 1 · El Contrato':('Capítulo '+(n-1)+' · '+((T(n-1).cartel||{}).titulo||''));
  let ph=0; setScene({draw(c,dt){ drawBG(c,ph?'titulo':'noche',dt); if(!ph){ c.fillStyle='rgba(0,0,0,.4)'; c.fillRect(0,80,W,110); c.textAlign='center'; c.fillStyle='#f4e8c8'; c.font='24px "Marcellus SC", Georgia, serif'; c.fillText(prev,W/2,120); c.fillStyle='#e0b860'; c.font='700 '+FSZ(13)+'px "Alegreya Sans SC", system-ui, sans-serif'; c.fillText('FIN DEL CAPÍTULO',W/2,146); }
    else { titleText(c,'Capítulo '+n+' · '+L.titulo,(L.fecha||'').toUpperCase()); epigrafe(c,n,186); } }});
  await fadeTo(0,700); await sleep(AUTO?0:1400); await fadeTo(1,500); ph=1; await fadeTo(0,700);
  await choose([{label:'Comenzar el capítulo',value:1,cls:'primary',auto:true,icon:'go'}]); await fadeTo(1,600);
  try{ SAVES.auto('capitulo'); }catch(e){} log('cap:'+n); }
// C11 (Hermes): epígrafe de la novela debajo del cartel (LINES.epigrafe[n] = {t, de}); sin texto no dibuja nada
function epigrafe(c,k,y0){ const E=typeof LINES!=='undefined'&&LINES.epigrafe&&LINES.epigrafe[k]; if(!E||!E.t) return; c.save(); c.textAlign='center';
  const fz=FSZ(13), maxW=Math.min(W-40,440); c.font='italic '+fz+'px Alegreya, Georgia, serif'; const words=String(E.t).split(' '), rows=[]; let r='';
  words.forEach(w=>{ const t=r?r+' '+w:w; if(c.measureText(t).width>maxW&&r){ rows.push(r); r=w; } else r=t; }); if(r) rows.push(r);
  const lh=Math.round(fz*1.3), h=rows.length*lh+(E.de?lh+4:0)+12; c.fillStyle='rgba(6,8,16,.5)'; c.fillRect(W/2-maxW/2-12,y0-fz,maxW+24,h);
  c.fillStyle='#e6dcc4'; rows.forEach((t,i)=>c.fillText(t,W/2,y0+i*lh));
  if(E.de){ c.font=FSZ(11)+'px "Alegreya Sans SC", system-ui, sans-serif'; c.fillStyle='#e0b860'; c.fillText('— '+E.de,W/2,y0+rows.length*lh+4); } c.restore(); }
// fin de capítulo: aviso y autoguardado
async function capEnd(n){ if(!AUTO) toast(txt(n,'toasts','capFin')||('Fin del Capítulo '+n),2400); set('cap'+n+'_fin'); try{ SAVES.auto('capitulo'); }catch(e){} }

/* ---------- encabezado y Diario: capítulo actual ---------- */
function capInfo(n){ const c=T(n).cartel; return c?{n,titulo:c.titulo,fecha:c.fecha}:null; }
function partOf(step){ const C=CAPS.find(c=>c.order.includes(step)); if(!C) return null; const i=capInfo(C.n); return i?'Capítulo '+i.n+' · '+i.titulo:null; }
function capOf(step){ const C=CAPS.find(c=>c.order.includes(step)); return C?C.n:1; }
function brand(){ try{ const n=Math.max((G&&G.chap)||1,G&&G.cp?capOf(G.cp):1), el=document.querySelector('.brand span'); if(G&&n>(G.chap||1)) G.chap=n; if(!el) return; const i=n>1?capInfo(n):null; el.textContent=i?'Capítulo '+i.n+' · '+i.titulo:'Capítulo 1 · El Contrato'; }catch(e){} }
/* ---------- ganchos antes y después de un tramo (pulido, carril B) ---------- */
// B02 (decisión de Brian: (a)): si nunca se le compró, Gaspar se suma igual por historia al cerrar el Cap. 4 → 14 al Fin del Arco (13 si se entrega a Darra)
// prueba de la rama sin compras: '#prueba&sincompra=1' deja la bolsa en 0 en los tramos donde Gaspar ofrece (y la devuelve después)
const SINC=()=>AUTO&&/sincompra=1/.test(location.hash), guard=()=>{ if(SINC()){ G._oroG=(G._oroG||0)+G.oro; G.oro=0; } }, unguard=()=>{ if(SINC()&&G._oroG!=null){ G.oro+=G._oroG; delete G._oroG; } };
// perfiles de balance (solo '#prueba'): '&farm=N' pelea N aleatorios por capítulo después del cartel (tablas de las zonas del capítulo);
// '&compras=1' compra lo de un jugador típico: 2 Pociones a Agnes (Cap. 2) y 2 Pociones mayores + 1 Bomba de éter a Gaspar (Caps. 4 y 5)
const HS=k=>AUTO?((location.hash.match(new RegExp('[&#]'+k+'=(\\d+)'))||[])[1]|0):0;
const FARM={2:[['carboneros',null],['sirga',null]],3:[['sirga',null]],4:[['albardon',null]],5:[['albardon',10]]};
async function farm(n){ const N=HS('farm'); if(!N||typeof ENC==='undefined') return; const T=[]; (FARM[n]||[]).forEach(([z,l])=>{ const Z=ZONES[z]; ((Z&&Z.enc&&Z.enc.table)||[]).forEach(g=>T.push({z,enemies:(g.enemies||[]).map(k=>l?arcLvlKey(k,l):k)})); });
  if(!T.length) return; for(let i=0;i<N;i++){ const g=T[(i*7+n)%T.length]; await ENC.start({enemies:g.enemies},g.z); log('farm:'+n+':'+g.enemies.join('+')); } }
function buy(list){ if(!HS('compras')) return; list.forEach(([k,n,p])=>{ for(let i=0;i<n;i++){ if(G.oro<p) return; G.oro-=p; G.items[k]=(G.items[k]||0)+1; log('compra:'+k); } }); }
// registro por tramo para balance.js: nivel del líder, promedio del núcleo y de los reclutas, coronas y objetos
const CORE=['ilian','nach','maela','simona','severo'];
function snap(id){ try{ const P=Object.assign({},G.away||{},G.party), lv=k=>P[k]&&P[k].lvl, core=CORE.filter(k=>P[k]).map(lv), rec=Object.keys(P).filter(k=>!CORE.includes(k)).map(lv), avg=a=>a.length?Math.round(a.reduce((x,y)=>x+y,0)/a.length*100)/100:null;
  (dbg.steps||(dbg.steps=[])).push({cp:id,lead:lv((G.order||[]).find(k=>G.party[k])),core:avg(core),rec:avg(rec),recMin:rec.length?Math.min(...rec):null,oro:G.oro,items:Object.assign({},G.items),n:Object.keys(G.party).length}); }catch(e){} }
const PRE={c4_gaspar:guard,c4_robo:guard,c4_vuelta:guard}, POST={
  c2_titulo:()=>farm(2), c3_titulo:()=>farm(3), c4_titulo:()=>farm(4), c5_titulo:()=>farm(5),
  c2_hollin:()=>buy([['pocion',2,15]]), c4_gaspar:async()=>{ unguard(); buy([['pocion_mayor',2,40],['bomba_eter',1,35]]); }, c5_granja:()=>buy([['pocion_mayor',2,40],['bomba_eter',1,35]]),
  c4_robo:unguard, c4_vuelta:unguard,
  c4_fin:async()=>{ if(G&&!G.party.gaspar&&!(G.away&&G.away.gaspar)){ join('gaspar',CAPMIN[4]); log('gaspar:historia'); } } };
// v27: otros módulos suman ganchos antes / después de un tramo (reclutas opcionales, escenas de Unísono): ARC.step(id,'pre'|'post',fn)
function stepHook(id,when,fn){ const M=when==='pre'?PRE:POST, f0=M[id]; M[id]=f0?async()=>{ await f0(); await fn(); }:fn; }
/* ---------- B23: temas nuevos donde corresponden (sin tocar los capN_mundo.js): se reemplaza el tema pedido en ese tramo ----------
   No corre en '#prueba' (el audio no entra en el registro, pero así el piloto queda idéntico). */
const MUSIC_SUB={ c2_hollin:{calma:'laud_ysa'}, c4_vuelta:{intriga:'marcha_rosa'}, c4_plan:{intriga:'marcha_rosa'}, c5_valdris:{silencio:'caballero'}, c5_caceria:{intriga:'caballero'} };
try{ const pm0=playMusic; playMusic=function(n){ const S=!AUTO&&G&&MUSIC_SUB[G.cp]; return pm0((S&&S[n])||n); }; }catch(e){ console.error(e); }
/* ---------- registro de capítulos ---------- */
function cap(n,def){ CAPS.push(Object.assign({n},def)); CAPS.sort((a,b)=>a.n-b.n); }
function install(ORDER,STEPS,STEPNAME){ CAPS.forEach(C=>{ C.order.forEach(id=>{ if(!ORDER.includes(id)) ORDER.push(id); if(C.steps[id]){ const f=C.steps[id]; STEPS[id]=async function(){ G.chap=Math.max(G.chap||1,C.n); brand(); snap(id); if(PRE[id]) await PRE[id](); await f(); if(POST[id]) await POST[id](); set(id); if(id==='c5_epilogo') snap('fin'); }; } }); Object.assign(STEPNAME,C.names||{}); }); } // al terminar un tramo queda su bandera (la leen los «when» de las escenas)

return {step:stepHook,epigrafe,cap,install,set,has,txt,join,away,back,leader,key,keyItem,give,hooks,stage,world,fightIn,enter,card,capEnd,log,dbg,KEYS,CAPMIN,townScene,capInfo,partOf,brand,shopName:k=>{ if(k==='agnes_c2'){ const L=(typeof LINES!=='undefined'&&LINES.arcoShop&&LINES.arcoShop.agnes)||{}; return L.titulo||NPCNAME.agnes||CHAR.agnes.name; } return ({bram_ventana:'Ventana de la herrería',herreria_c3:'Herrería de Bram',gaspar:'La carreta de Gaspar'})[k]||null; },
  // B10: la tienda de Agnes (Cap. 2, Hollin de noche). A llama ARC.shop('agnes_c2') desde la opción «Comprar» de la charla; el saludo es de Hermes
  shop:async k=>{ const id=k==='agnes_c2'?'agnes':k, L=(typeof LINES!=='undefined'&&LINES.arcoShop&&LINES.arcoShop[id])||{}; if(L.saludo&&!AUTO){ await say(id,L.saludo,'h'); hideDialog(); } await openShop(k); }};
})();
const arcTxt=(n,...p)=>ARC.txt(n,...p);

/* ==================== MÓDULO arco1/sq.js ==================== */
/* ============================================================
   ARCO I · Las dos misiones secundarias que entran (plan 5; textos: js/arco1/secundarias.js · LINES.sq)
   H-03 «La columna de Nach» (sq_fiado): Hollin del Cap. 1 (encadenada a agnes_pizarra) y del Cap. 2 (pizarra) → cobra en c4_agnes.
   C-05 «La bota de Tomé» (sq_bota): Linde (Tomé + «Algo en el barro») → Campamento (entrega) → cobra en bosque_b, c3_capilla y af_lista.
   Sistemas: S12 (elección con costo en coronas), S11 (objetos clave), charlas de caravana por bandera, Diario › Pendientes.
   ============================================================ */
(function(){
const SQ=()=>LINES.sq||{};
const hf=()=>G.flags.hol||(G.flags.hol={});
const on=k=>ARC.has(k)||!!hf()[k];
const put=k=>{ hf()[k]=true; ARC.set(k); };

/* ---------- S12: elección de una charla de Hollin, con costo ---------- */
ARC.choice=async function(c,HF){ const C=c.choice; if(!C) return; hideDialog();
  const opts=C.opts.map((o,i)=>({label:o.label,sub:o.cost&&o.cost.oro?(o.cost.oro+' coronas · tenés '+G.oro):'',value:i,cls:i===0?'primary':'',auto:i===(AUTO?C.opts.length-1:0),icon:o.cost?'coin':'chat'}));
  try{ if(typeof tutAviso==='function') await tutAviso('costo','say'); }catch(e){} // C06: aviso de primera elección con costo
  const i=await choose(opts,C.title||''); const o=C.opts[i]; if(!o) return;
  if(o.cost&&o.cost.oro&&G.oro<o.cost.oro){ for(const l of (c.sinPlata||[])) await say(l[0],l[1],l[2]||'n'); return; }
  if(o.cost&&o.cost.oro){ G.oro-=o.cost.oro; sfx('heal'); }
  for(const l of (o.lines||[])) await say(l[0],l[1],l[2]||'n');
  if(o.set){ HF[o.set]=true; ARC.set(o.set); }
  if(o.aff) try{ affList(o.aff); }catch(e){}
  const T=(SQ().fiado||{}).toasts||{}; if(!AUTO&&o.set==='sq_fiado_pago') toast(T.hecho||'Encargo cumplido',2200); ARC.log('choice:'+(o.set||i)); };

/* ---------- H-03 · Cap. 1: la charla con Agnes encadenada a «agnes_pizarra» ---------- */
try{ const F=SQ().fiado; if(F&&F.cond_c1&&LINES.npc&&LINES.npc.agnes){ const c=Object.assign({},F.cond_c1,{need:F.cond_c1.need.map(k=>k==='agnes_pizarra'?'c_agnes_pizarra':k)});
  if(!LINES.npc.agnes.cond.some(q=>q.once===c.once)) LINES.npc.agnes.cond.push(c); } }catch(e){ console.error(e); }
// Cap. 2 · la pizarra (examinable de la taberna con el texto de la noche) y la segunda oportunidad
ARC.fiadoC2=async function(){ const F=SQ().fiado; if(!F||!F.cond_c2) return; if(on('sq_fiado_pago')||on('sq_fiado_c2')) return; put('sq_fiado_c2'); put('sq_fiado');
  for(const l of F.cond_c2.lines) await say(l[0],l[1],l[2]||'n'); await ARC.choice(F.cond_c2,hf()); };

/* ---------- C-05 · La bota de Tomé ---------- */
const B=()=>SQ().bota||{};
const tomeLinde=()=>{ const b=B(); if(on('sq_bota_tiene')&&!on('sq_bota_dev')) return b.tome_linde_tiene; if(on('sq_bota')) return b.tome_linde_again; return b.tome_linde; };
const tomeCamp=()=>{ const b=B(); if(on('sq_bota_dev')) return b.tome_campamento_dev; if(on('sq_bota_tiene')) return b.tome_campamento_entrega; if(on('sq_bota')) return b.tome_campamento_pide; return null; };
try{ const ZS=ZONES; const ci=ZS.caravanIn;
  ZS.caravanIn=function(z){ const L=ci.call(this,z); if(z==='linde') L.forEach(n=>{ if(n.id==='merc_pell_linde'){ n.talk=()=>tomeLinde(); n.run=async()=>{ if(!on('sq_bota')){ put('sq_bota'); if(!AUTO) toast(((B().toasts)||{}).nuevo||'Encargo nuevo · Diario',2000); } }; n.bang=['!sq_bota','sq_bota_tiene&!sq_bota_dev']; } }); return L; };
  const cn=(ZS.campamento&&ZS.campamento.npcs||[]).find(n=>n.id==='merc_pell_campamento');
  if(cn){ const t0=cn.talk; cn.talk=()=>tomeCamp()||(ZONES.text(t0)); cn.bang=['sq_bota_tiene&!sq_bota_dev'];
    cn.run=async()=>{ if(on('sq_bota_tiene')&&!on('sq_bota_dev')){ put('sq_bota_dev'); ARC.key('bota_tome',false); ARC.key('dos_cobre_tome'); try{ affList([['ilian','maela',1]]); }catch(e){} if(!AUTO) toast(((B().toasts)||{}).hecho||'Encargo cumplido',2000); } }; }
  // «Algo en el barro»: junto al charco del sur del camino de la Linde
  const ex=B().ex_barro, lz=ZS.linde; if(ex&&lz&&!lz.props.some(p=>p.id===ex.id)) lz.props.push({id:ex.id,x:252,y:214,kind:'examinable',label:ex.label,
    lines:()=>on('sq_bota_tiene')||on('sq_bota_dev')?ex.again:(on('sq_bota')?ex.lines:ex.beforeLines),
    run:async()=>{ if(on('sq_bota')&&!on('sq_bota_tiene')&&!on('sq_bota_dev')){ put('sq_bota_tiene'); ARC.key('bota_tome'); if(!AUTO) toast(((B().toasts)||{}).tiene||'Hay algo para entregar',2000); } }});
}catch(e){ console.error('[arco1] C-05',e); }
// Tomé cae en el puente: si tenía la bota sin entregar, queda «huérfana» (la pone el motor al empezar el Cap. 2)
ARC.botaHuerfana=function(){ if(on('sq_bota_tiene')&&!on('sq_bota_dev')) put('sq_bota_huerfana'); };

/* ---------- Diario › Pendientes: las dos secundarias ---------- */
try{ const sq0=sqTodos; sqTodos=function(out,T2){ sq0(out,T2); try{
    const F=(SQ().fiado||{}).diario, b=B().diario;
    if(F&&(on('sq_fiado')||on('sq_fiado_pago')||on('sq_fiado_espera'))){ let s='on',d=F.on; if(on('sq_fiado_pago')){ s='done'; d=F.hecho; } else if(on('sq_fiado_perdida')){ s='fail'; d=F.perdida; } else if(on('sq_fiado_espera')){ d=F.espera; } out.push({k:'fiado',n:F.n,d,state:s}); }
    if(b&&(on('sq_bota')||on('sq_bota_tiene'))){ let s='on',d=b.on; if(on('sq_bota_dev')){ s='done'; d=b.hecho; } else if(on('sq_bota_huerfana')){ s='fail'; d=b.huerfana; } else if(on('sq_bota_tiene')) d=b.tiene; else if(ORDER.indexOf(G.cp)>ORDER.indexOf('puente')){ s='fail'; d=b.perdida; } out.push({k:'bota',n:b.n,d,state:s}); }
  }catch(e){ console.error(e); } }; }catch(e){ console.error(e); }
})();

/* ==================== MÓDULO arco1/pulido_textos.js ==================== */
/* ============================================================
   ARCO I · PULIDO · carril C (Hermes, 21/10/2026) — lo que tiene que correr DESPUÉS de motor.js e historia.js
   Va en modules.json después de arco1/sq.js y antes de arco1/cap2_mundo.js (así las variantes de nivel de los aleatorios,
   que se arman en capN_mundo.js, ya copian el nombre corregido). Solo textos y nombres: no gasta Math.random ni toca combate.
   · C08: una sola forma visible por jefe (barra de turnos, Bestiario, diálogo, registro de combate)
   · C05: notas del Diario › Personajes que historia.js no pisaba (solo agregaba las que no existían en el Cap. 1)
   Los textos nuevos de A y B (3.3 del backlog) están en lines.js, que carga antes que todo.
   ============================================================ */
(function(){
/* ---------- C08 · nombres de jefe: el mismo en la barra, el Bestiario, el cuadro de diálogo y el registro ---------- */
const JEFE={cabo_jinetes:'Cabo de jinetes',sargento:'Sargento de la Rosa',cabo_taberna:'Cabo de la Rosa',montero:'Montero de la Rosa',valdris:'Caballero negro'};
try{ Object.keys(JEFE).forEach(k=>{ if(ENEMY[k]) ENEMY[k].name=JEFE[k]; NPCNAME[k]=JEFE[k]; });
  Object.keys(ENEMY).forEach(k=>{ const b=k.replace(/_n\d+$/,''); if(b!==k&&JEFE[b]) ENEMY[k].name=JEFE[b]; }); }catch(e){ console.error('[pulido C08]',e); }

/* ---------- C05 · Diario › Personajes: la nota que cambia con el arco (forma {a, after, b}) reemplaza a la del Cap. 1 ---------- */
try{ [2,3,4,5].forEach(n=>{ const P=(((LINES['cap'+n]||{}).diario)||{}).people||{}; Object.keys(P).forEach(k=>{ CXT.people[k]=P[k]; }); }); }catch(e){ console.error('[pulido C05]',e); }

/* ---------- A13 (docs/pulido-claves-pendientes-A.md) · el Olfato de Simona y el Paso del Zorro ----------
   LINES.olfato.zorro: lista de líneas al abrir la grieta de los Sauces con Simona en el grupo (cap2_mundo.js, olfLines).
   Solo Simona y narración: el que lidera puede ser Ilian o Nach según el capítulo. */
LINES.olfato = Object.assign(LINES.olfato||{}, {
  zorro: [['simona','*hunde el hocico en la huella y tira para la grieta*','t'],
          [null,'Simona se mete entre las rocas sin dudar. La grieta no era angosta: era angosta para el que no sabe dónde pisar.','n'],
          [null,'Del otro lado, una senda de zorros, baja y torcida, que se pierde hacia la Linde.','n']]
});
/* LINES.zonasArco.ex.zorro_paso: examinable en medio del Paso del Zorro (exLine/exLabel, forma {label, lines, again}) */
if(LINES.zonasArco&&LINES.zonasArco.ex) LINES.zonasArco.ex.zorro_paso = { label:'Mirar la senda',
  lines:[[null,'Una senda de zorros entre dos paredes de roca. Pelos rojizos en las espinas, huesos de liebre y ni una sola bota.','n'],
         [null,'Por acá no pasa la Rosa. Los caballos no caben, y los jinetes no saben agacharse.','n']],
  again:[[null,'Huellas chicas, todas para el mismo lado. Los zorros saben adónde van.','n']] };

/* ---------- B09 (docs/pulido-claves-pendientes-B.md) · avisos de los regalos con el reparto de ARC_GIFT (motor.js) ----------
   historia.js give(): si el tramo está en ARC_GIFT, el aviso es LINES.giftTune[G.cp] (sin clave, «Recibís: …»).
   c3_ruy {pocion:1} · c4_carrera {pocion:1} · c4_agnes {pocion:0} → solo las 35 coronas de la caja. */
LINES.giftTune = Object.assign(LINES.giftTune||{}, {
  c3_ruy:     'La viuda deja una Poción en la carreta',
  c4_carrera: 'Caldo de raíces: +1 Poción',
  c4_agnes:   'Recuerdo: la caja de Agnes (+35 coronas)'
});
})();

/* ==================== MÓDULO arco1/posadas_textos.js ==================== */
/* ============================================================
   ARCO I · POSADAS, CAMPAMENTOS, GUARDADO Y PUNTOS DE FORMACIÓN · carril C (Hermes, 21/10/2026)
   Diseño: docs/diseno-posadas-formacion.md (con las «Decisiones de Brian (21/10/2026)»: D1 guardado en posadas, campamentos
   y lumbres de paso; desde la pausa solo se carga · D2 campamentos con descanso completo y cambio de grupo, 1 por capítulo ·
   D3 la posadera del aserradero es Odila · D4 la granja de los Oberen es parada de descanso del Cap. 1).
   Va en modules.json DESPUÉS de arco1/pulido_textos.js (lo agrega Zeus). Solo textos: no gasta Math.random ni toca G.

   Formatos (los mismos de lines.js):
   · «línea»  = [quien|null, texto, expr, nombre?]  (null = narración; el 4.º campo es el nombre visible si no hay retrato propio)
   · «líneas» = lista de líneas (se recorren con say / api.playLines)
   · Interpolación: %n = número (como LINES.sqAviso.hollinN). Se usa en los precios: 'Dormir · %n coronas', '−%n coronas'.
   Largos: diálogo ≤ 100 · narración ≤ 150 · opciones ≤ 34 · etiquetas ≤ 28 (tools/verify/largos.js).

   Mapa de claves
   · LINES.posada.menu / .cartel / .toast ............ comunes a todos los lugares de descanso (2.1, 2.4)
   · LINES.posada.<lugar> ............................ hollin (Agnes), aserradero (Odila), granja_oberen (Oberen):
       {nombre, npc, saludo, menu:{descansar, grupo, guardar, salir}, descanso, despedida, sinPlata?, again?}
       hollin además trae la variante por capítulo: hollin.c1 … c4 (pisa a los campos comunes; c4 = cerrada)
   · LINES.posada.campamento ......................... {nombre, llegada, menu, descanso, yaDescansado} comunes
       + campamento.lugares.{albardon (C1, Cap. 4), granja_vieja (C2, Cap. 5)} con sus propias líneas de Dov
   · LINES.posada.esfera ............................. la Lumbre de paso (D1): {nombre, label, primera, toque, guardado, cancelar, again}
   · LINES.posada.formacion .......................... {menu, abrir, invitada, bloqueado, protagonista, listo, puntos.<f2|f3|f4|f5a|f5b>}
   · LINES.posada.grupo .............................. rótulos de Menú › Grupo (6.1: LINES.grupo.*)
   · LINES.posada.pausa .............................. {soloCargar} pista del Guardar deshabilitado en la pausa (6.1: partidas.solo_lugares)
   · LINES.posada.mojon .............................. opciones del mojón del cuervo (6.1: LINES.mojon.*)
   · LINES.posada.odo ................................ Fray Odo en el Cap. 3 sin curación (6.1: odo.c3_sin_cura)
   · LINES.pf ........................................ alias de LINES.posada.formacion.puntos + menu + fijo (como lo nombra el diseño, 6.1)
   · LINES.tut.{posada, formacion} ................... avisos de primera vez (los muestra tutAviso; no pisa los que ya existen)
   · LINES.zonasArco.ex.{cama_aserradero, fogon_c4, fogon_c5, lumbre} examinables de los lugares de descanso (opcionales)
   ============================================================ */
