/* ==================== MÓDULO arco1/puesta.js ==================== */
/* ============================================================
   ARCO I · PUESTA DE ESCENAS (pulido, carril B · B12 y B13)
   Va en js/modules.json después de arco1/historia.js y antes de arco1/cap2_mundo.js.
   · ARC_POS[<escena>] = {id:[x,y]} en coordenadas de escenario (480×300; pies en y≈232–250), igual que POS de p5_world.js.
     Se copia a POS al cargar, así lo leen stageIn (escenario pintado) y WORLD.sceneIn (escena en la zona, que después
     corre a cada actor a suelo libre).
   · Las escenas del Arco I con 7 o más actores y sin posición propia se arman solas en DOS filas (adelante/atrás, intercaladas
     en el orden del elenco de Hermes): nadie queda fuera del cuadro y hay ≥ 8 px entre los pies (antes, una sola fila de
     56 px de paso: con 15 actores, la fila empezaba en x = −142).
   · ARC.posFor('c4_carrera', actores, tramo): posiciones de la carrera (B13) para el gancho de cap4_mundo.js (carril A).
   No escribe texto visible.
   ============================================================ */
const ARC_POS={
  // epílogo (15): Nach y Maela a la izquierda, la compañía en dos filas, Ilian con Olaf y Simona adelante a la derecha
  c5_epilogo:{nach:[64,234],maela:[104,250],gaspar:[140,232],bram:[176,250],severo:[210,232],dov:[244,252],agnes:[276,232],darra:[310,250],
    odo:[342,232],ysa:[372,250],zarpa:[402,232],tessa:[432,248],ilian:[284,256],olaf:[304,258],simona:[226,258]},
  // fogón (10): en ronda alrededor del fuego (centro x≈240)
  c5_fogon:{nach:[150,240],maela:[186,230],tessa:[224,226],dov:[262,228],severo:[300,232],ilian:[338,242],olaf:[358,250],ysa:[196,254],darra:[244,256],zarpa:[292,254]},
  // Doña Rueda (8): Dov junto a la carreta a la izquierda; la compañía a la derecha sin pasarse del borde
  c2_dov:{dov:[96,240],maela:[176,232],ilian:[214,246],nach:[254,240],severo:[294,232],simona:[238,256],merc_quina:[352,234],merc_ruy:[396,240]},
  // entierro de Ruy (7): Ruy tendido al centro, el resto en semicírculo
  c3_ruy:{merc_ruy:[240,250],merc_quina:[196,236],bram:[156,242],maela:[284,236],severo:[324,242],nach:[364,236],olaf:[390,250]},
  // después del cabo de la taberna: el cabo caído a la izquierda, Agnes de pie, Zarpa e Ilian llegando
  c4_jefe_post:{cabo_taberna:[150,246],agnes:[222,240],zarpa:[296,236],ilian:[350,244]},
  // decisión de Darra (7): Darra sola a la izquierda, la compañía enfrente
  c5_decision:{darra:[110,240],maela:[226,232],severo:[262,246],gaspar:[300,232],nach:[336,244],ilian:[374,238],olaf:[396,248]},
  c5_decision_b:null, // la rama «la entregamos» de la prueba usa las mismas (se copia abajo)
  // escenas de afinidad nuevas: el dúo al centro (70 px) y los demás a los costados
  af_otravez:{dov:[196,242],ilian:[266,244],nach:[336,240],simona:[372,252]},
  af_mella:{bram:[204,242],nach:[276,242],olaf:[306,250]},
  af_cicatrices:{agnes:[200,242],maela:[270,242],ilian:[350,240]},
  af_lista:{merc_quina:[96,236],merc_mudo:[140,240],nach:[226,244],ilian:[296,242],olaf:[322,250]}
};
ARC_POS.c5_decision_b=ARC_POS.c5_decision;
// dos filas para los elencos grandes (≥ 7) sin posición propia
function arcRows(ids){ const n=ids.length, front=[], back=[]; ids.forEach((id,i)=>{ ((i%2===0)?front:back).push(id); });
  const P={}, L=46, R=W-46; const put=(row,y,shift)=>{ const m=row.length; if(!m) return; const sp=m>1?(R-L)/(m-1+(shift?0.5:0)):0; row.forEach((id,i)=>{ const pet=id==='simona'||id==='olaf'; P[id]=[Math.round(m>1?L+i*sp+(shift?sp/2:0):W/2),y+(pet?6:0)]; }); };
  put(back,232,true); put(front,250,false); return P; }
(function arcPuesta(){ try{
  Object.keys(ARC_POS).forEach(k=>{ if(ARC_POS[k]) POS[k]=ARC_POS[k]; });
  for(const ck in LINES.cast){ if(!/^cap[2-5]$/.test(ck)) continue; const C=LINES.cast[ck]; for(const name in C){ if(POS[name]) continue; const ids=C[name]||[]; if(ids.length>=7) POS[name]=arcRows(ids); } }
  // escenas de afinidad (LINES.escenas: elenco propio)
  (LINES.escenas||[]).forEach(E=>{ if(E&&E.id&&!POS[E.id]&&E.cast&&E.cast.length>=7) POS[E.id]=arcRows(E.cast); });
}catch(e){ console.error('[arco1] puesta',e); } })();

/* ---------- B13 · la carrera del Cap. 4: posiciones por tramo sobre suelo firme ----------
   Gancho de A (cap4_mundo.js): const P=ARC.posFor('c4_carrera',actores,tramo) → {id:{x,y}} en coordenadas de la zona.
   Elige, para cada actor, el punto transitable más cercano a su lugar en la formación (fuera de 'solid' y de T_DEEP),
   con la formación centrada en la marca del tramo (carrera, carrera_2, carrera_3; o la de la isla). */
const ARC_RACE={ order:['zarpa','ilian','nach','simona','olaf','ysa','tessa','odo','maela','gaspar','refugiada'],
  // formación relativa al centro del tramo: los corredores adelante (Zarpa y las monturas), el resto mirando desde la orilla
  slot:{zarpa:[40,0],ilian:[0,-6],nach:[-26,4],simona:[16,14],olaf:[-6,14],ysa:[-60,-14],tessa:[-84,-6],odo:[-108,-14],maela:[-60,10],gaspar:[-96,12],refugiada:[-130,0]} };
function arcRaceOk(Z,x,y){ try{ if(x<0||y<0||x>=Z.w||y>=Z.h||Z.solid(x,y)) return false; const N=window.WORLDT&&WORLDT.nav(Z.id); return !N||!!N.comp[((y/N.C)|0)*N.gw+((x/N.C)|0)]; }catch(e){ return true; } } // como okPos de p10: dentro de la zona, fuera de 'solid' (T_DEEP es sólido) y en la parte transitable
function arcPosFor(name,actors,tramo){ if(name!=='c4_carrera') return null; const out={}; let Z=null; try{ Z=WORLD.zone('albardon'); }catch(e){}
  const M=(Z&&Z.marks)||{}, c0=M.carrera||M.isla||{x:1180,y:160}, t=Math.max(1,Math.min(3,tramo|0||1)), c=M['carrera'+t]||{x:c0.x+(t-2)*170,y:c0.y}; // 3 tramos a lo largo del albardón: 1010, 1180 y 1350 (el sauce muerto, la meta)
  const ids=(actors||[]).map(a=>typeof a==='string'?a:a.id); const used=[];
  ids.forEach(id=>{ const s=ARC_RACE.slot[id]||[-150+used.length*12,0]; let x=c.x+s[0], y=c.y+s[1];
    if(Z&&!arcRaceOk(Z,x,y)){ let best=null; for(let r=4;r<=96&&!best;r+=4) for(let a=0;a<16&&!best;a++){ const xx=Math.round(x+Math.cos(a*Math.PI/8)*r), yy=Math.round(y+Math.sin(a*Math.PI/8)*r*0.6); if(arcRaceOk(Z,xx,yy)&&!used.some(u=>Math.abs(u.x-xx)<14&&Math.abs(u.y-yy)<8)) best={x:xx,y:yy}; } if(best){ x=best.x; y=best.y; } }
    used.push({x,y}); out[id]={x,y}; });
  return out; }
try{ ARC.posFor=arcPosFor; ARC.POS=ARC_POS; }catch(e){}

/* ---------- B14 · Ilian «sentado» donde el texto lo sienta ----------
   ojo (el poste del cerco), preguntas (una raíz) y af_lista (la última guardia) ponen la pose 'sit'. Desde v27 (pedido de Brian)
   los humanos con hoja PNG no se dibujan sentados (p5_world.js, sitStands): quedan de pie y ya no se pinta el poste/raíz/tocón
   que tapaba las piernas cortadas. ARC_SIT_INIT se mantiene para que la lógica (gestos) no cambie. */
const ARC_SIT_INIT={af_lista:['ilian']};
// af_lista no trae la orden de sentarse en el guion: se sienta al empezar (sin texto nuevo)
try{ const ps0=playScene; playScene=async function(name,ctx){ try{ (ARC_SIT_INIT[name]||[]).forEach(id=>{ const a=ctx&&ctx.get&&ctx.get(id); if(a&&!a.side){ a.base='sit'; a.at=T; } }); }catch(e){} return ps0.apply(this,arguments); }; }catch(e){ console.error('[arco1] sentar',e); }

/* ---------- B25 · cámara fina y gestos en las 4 escenas de afinidad nuevas ----------
   Se agregan órdenes de puesta (sin texto) a las escenas de Hermes: acercamiento al primero que habla, vuelta al plano general
   después de la última línea y dos gestos (asentir y encogerse de hombros) en la segunda línea de cada uno del dúo. */
(function arcAfCam(){ try{ const AF={af_otravez:['ilian','dov'],af_mella:['nach','bram'],af_cicatrices:['maela','agnes'],af_lista:['ilian','nach']};
  Object.keys(AF).forEach(id=>{ const S=LINES.scenes[id]; if(!Array.isArray(S)||S._b25) return; const pair=AF[id];
    const says=[]; S.forEach((c,i)=>{ if(Array.isArray(c)&&c[0]==='say') says.push(i); }); if(!says.length) return;
    const ins=[]; const nth=(who,n)=>{ let k=0; for(const i of says) if(S[i][1]===who&&++k===n) return i; return -1; };
    ins.push([says[0],['cam',S[says[0]][1],1.16]]);
    const g1=nth(pair[0],2), g2=nth(pair[1],2); if(g1>=0) ins.push([g1,['gest',pair[0],'nod']]); if(g2>=0) ins.push([g2,['gest',pair[1],'shrug']]);
    ins.push([says[says.length-1]+1,['cam','reset']]);
    ins.sort((a,b)=>b[0]-a[0]).forEach(([i,c])=>S.splice(i,0,c)); S._b25=true; });
}catch(e){ console.error('[arco1] B25',e); } })();

