const decision={
  darraProteger:async()=>{ ARC.set('darra_protegida'); ARC.join('darra',11); try{ affList((L5().affDecision||{}).darraProteger); }catch(e){} ARC.log('darra:proteger'); },
  joinDarra:async()=>{ ARC.join('darra',11); },
  darraEntregar:async()=>{ ARC.set('darra_entregada'); G.oro+=150; G.flags.rep_corvaine=(G.flags.rep_corvaine|0)+5; try{ affList((L5().affDecision||{}).darraEntregar); }catch(e){} if(!AUTO) toast((L5().toasts||{}).darraEntregada||'+150 coronas',2600); ARC.log('darra:entregar'); } };
// prueba automática: '#prueba&darra=2' recorre la rama «la entregamos»
function decisionScene(){ const S=LINES.scenes.c5_decision; if(!(AUTO&&(/darra=2/.test(location.hash)||RECL.perfil()!=='todos'))) return 'c5_decision'; // v27: sin opcionales / segundas, la entregan (su 2.ª es del Arco III)
  if(!LINES.scenes.c5_decision_b) LINES.scenes.c5_decision_b=S.map(c=>Array.isArray(c)&&c[0]==='?'?['?',c[1].slice().reverse(),c[2]]:c); ENTER.c5_decision_b=ENTER.c5_decision; POS.c5_decision_b=POS.c5_decision;
  for(const k in LINES.cast) if(LINES.cast[k].c5_decision) LINES.cast[k].c5_decision_b=LINES.cast[k].c5_decision; return 'c5_decision_b'; }

/* ---------- jefe: el Montero; después, el caballero negro ---------- */
async function traila(B){ if(B.units.filter(v=>v.side==='e'&&alive(v)).length>=4) return; const e=enemyUnit('sabueso',30); arcScale(e,10); e.isNew=true; B.units.push(e); layout(B); e.x=e.hx-140; e.y=e.hy; e.isNew=false; await tweenTo(e,e.hx,e.hy,500); }
const valdrisEnd=B=>{ const n=B.units.find(v=>v.side==='p'&&v.id==='nach'); return !!(n&&n.pv<=n.pvMax*0.25); };

const at=m=>WORLD.mark(m);
