// [D1–D6] filtra las líneas etiquetadas según LDC_DEC (lines.js). '§1A', '§3'/'§!3', '§4fardo|camino|hora|cartel', '§5'/'§!5'
function decOk(tag){ const D=(typeof LDC_DEC!=='undefined'&&LDC_DEC)||{}; const neg=tag[1]==='!'; const k=tag.slice(neg?2:1); let v=true;
  if(k==='1A') v=D.d1==='A'; else if(k==='3') v=D.d3!==false; else if(k==='5') v=D.d5!==false; else if(k[0]==='4') v=!D.d4||D.d4[k.slice(1)]!==false;
  return neg?!v:v; }
// T8 (misiones): '§f:bandera' / '§!f:bandera' no se filtran al cargar: el comando se envuelve en ['if',{flag},…] y se decide al jugar la escena
const isFTag=x=>typeof x==='string'&&/^§!?f:/.test(x);
function decCmds(L){ return L.filter(c=>!Array.isArray(c)||!c.some(x=>typeof x==='string'&&x[0]==='§'&&!isFTag(x)&&!decOk(x))).map(c=>{ if(!Array.isArray(c)) return c; const ft=c.filter(isFTag); let o=c.filter(x=>!(typeof x==='string'&&x[0]==='§'));
    ft.forEach(t=>{ const neg=t[1]==='!'; const fl=t.slice(neg?4:3); o=neg?['if',{flag:fl},[],[o]]:['if',{flag:fl},[o]]; }); return o; }); }
function decApply(){ try{ const S0=LINES.scenes; Object.keys(S0).forEach(k=>{ S0[k]=decCmds(S0[k]); });
    // escenas v2: Lina de Molle la resuelven las etiquetas §5/§!5 de «af_rodilla» (LINES.scenes); LINES.chats queda vacía
    (LINES.chats||[]).concat(LINES.affChats||[]).forEach(ch=>{ ch.lines=decCmds(ch.lines); }); }catch(e){ console.error(e); } }
decApply();
