function storyTriggers(){ try{ const Z0=(typeof ZONES!=='undefined')?ZONES:null; if(!Z0) return;
    const add=(z,t)=>{ const zz=Z0[z]; if(!zz||!zz.triggers||zz.triggers.some(q=>q.id===t.id)) return; zz.triggers.push(t); };
    add('sauces',{id:'sau_perra',x:300,y:150,w:40,h:330,scene:'sauces_perra',need:'!c2',once:true});           // 4.4 la perra de la loma
    add('linde',{id:'lin_llegada',x:56,y:90,w:24,h:150,scene:'linde_llegada',need:'!c3',once:true});          // 4.6 el castillo en la niebla
    add('aldea',{id:'ald_llegada',x:40,y:160,w:24,h:96,scene:'aldea_llegada',need:'bosque_b',once:true});     // 10.1 la aldea
    const e6=Z0.puente&&(Z0.puente.triggers||[]).find(t=>t.id==='e6_cierre'); if(e6) e6.scene='puente_humo';   // 6.1 «Eso no es leña»
    // escenas de afinidad v2 · disparadores de paso (sin «!»; si se sale de la zona por otro lado, se juegan al salir: p10 tryExit)
    const pass=(z,id,x,y,w,h,esc)=>add(z,{id,x,y,w,h,escena:esc,pass:true,need:()=>escenaAvail(esc),once:true});
    pass('linde','lin_pasarela',740,60,90,150,'codigo');       // tramo noreste antes del claro (fuera del cono del rival riv_juncal, 904,40)
    pass('campamento','cam_alba',880,20,60,130,'ojo');         // el poste del cerco, antes de cam_ne (y del aviso «¿Listos?»)
    pass('puente','pue_lira',860,100,80,110,'lira');           // extremo este del Puente Viejo, antes de pue_e
    // «La primera guardia» (figura con «!»): si se sale del Bosque Hondo sin verla, se juega al salir (p10 tryExit, ESCEXIT)
    // examinables nuevos (con «!» mientras la escena esté pendiente; después, su texto)
    const prop=(z,p)=>{ const zz=Z0[z]; if(!zz||!zz.props||zz.props.some(q=>q.id===p.id)) return; zz.props.push(p); };
    prop('sauces',{id:'sau_ex_piedra',kind:'examinable',x:318,y:214,label:'Mirar la piedra de la loma',escena:'perra',text:'sau_ex_piedra',need:'c2'});
    prop('aldea',{id:'ald_pozo',kind:'examinable',x:252,y:404,label:'Mirar el pozo',escena:'rivales',text:'ald_pozo'});
    // la llegada a la aldea deja bandera (cierra «La primera guardia» y abre «El pozo»)
    const al=Z0.aldea&&(Z0.aldea.triggers||[]).find(t=>t.id==='ald_llegada'); if(al&&!al.sets) al.sets='ald_llegada';
  }catch(e){ console.error(e); } }
storyTriggers();
