// rec: registro de ranura con el que se retoma (para no repetir combates ya ganados en ese tramo)
async function runFrom(cp,rec){
  let i=Math.max(0,ORDER.indexOf(cp)); const i0=i; migrarEscenas(); // partidas viejas: charlas v1 → escenas v2 (una vez)
  for(;i<ORDER.length;i++){ SAVES.beginStep(ORDER[i],i===i0?rec:null); G.cp=ORDER[i]; SAVES.auto('tramo'); prepNext(ORDER[i]); await STEPS[ORDER[i]]();
    if(ORDER[i]==='cierre'&&!CUR.cap1) CUR.cap1={n:(CUR.blog||[]).length,g:snapshot()}; } // regresión: foto del cierre del Cap. 1 (#prueba)
  await endScreen();
}
// cargar una ranura (desde el título o al arrancar después de «Cargar» en la pausa)
async function loadSlot(id,rec){ rec=rec||SAVES.read(id); if(!rec) return false; G=JSON.parse(JSON.stringify(rec.g)); G.cp=rec.cp; ensureEquip(G); G.start=Date.now(); SAVES.loaded(rec); try{ if(typeof ARC!=='undefined') ARC.brand(); }catch(e){} /* B19: el encabezado ya dice el capítulo del guardado */ if(!AUTO) warmPartyArt(); /* B16 */
  AU.init(); AU.resume(); await fadeTo(1,400); runFrom(rec.cp,rec); return true; }

/* ============================================================
   ARRANQUE (con precalentado de arte)
   ============================================================ */
// precarga con prioridad de lo que trae el tramo que empieza (fondo, enemigos y cabecitas de la línea de turnos), mientras corre el mapa o la escena previa
const NEXTB={hollin:['taberna',[]],contrato:['taberna',[]],prados:['prados',['lobo']],sauces:['sauces',['bandido','arquero']],pantano:['pantano',['jabali','alfa']],campamento:['campamento',[]],puente:['puente',['soldado','ballestero']],emboscada:['puente',['asesino','soldado']],huida:['puente',[]],jefe:['puente',['oswin','soldado']],bosque:['noche',[]],cierre:['prados',[]]};
function prepNext(step){ const n=NEXTB[step]; if(!n) return; try{ ENV.prewarm([n[0]],false,true); const ids=n[1].concat(G&&G.party?Object.keys(G.party):[]); if(PXS.prio) PXS.prio(ids); if(FX.warmPrio) FX.warmPrio(n[1]); ids.forEach(id=>{ headOf(id,24); headOf(id,36); }); }catch(e){} }
const WARM_ALL=['z:taberna','ilian','nach','agnes','maela','bram','tessa','odo','comerciante','guardia','peregrino','encap','aldeano','aldeana','anciano','nino','gallina','gato_pueblo','paloma','cocinera','parroquiano','aprendiz','z:prados','bertram','lina','lobo','z:sauces','bandido','arquero','z:pantano','jabali','alfa','z:campamento','severo','z:puente','oswin','soldado','ballestero','asesino','valdris','simona','z:noche'];
async function start(data){
  fit(); requestAnimationFrame(frame);
  newGame(); SAVES.fresh();
  try{ const mg=SAVES.migrate(); if(mg) console.info('Guardado anterior migrado a:',SLOTNAME(mg)); }catch(e){ console.error(e); }
  let boot=null; try{ boot=store.get('boot',null); if(boot!=null) store.del('boot'); }catch(e){}
  const bootRec=boot?SAVES.read(boot):null;
  const LAT=bootRec?{id:boot,rec:bootRec}:SAVES.latest(); const saved=LAT?LAT.rec.g:null; if(saved&&LAT) saved.cp=LAT.rec.cp;
  let load=0, loading=true;
  setScene({draw(c,dt){ if(WARMED.has('z:titulo')) drawBG(c,'titulo',dt); titleText(c,'Las Doce Coronas','ARCO I · CAPÍTULOS 1 A 5');
    c.textAlign='center'; c.font=FSZ(16)+'px Alegreya, Georgia, serif'; c.lineWidth=3; c.strokeStyle='rgba(0,0,0,.7)'; const tip=loading?'Preparando el arte…':'Con sonido se disfruta más: hay partes que se juegan con el oído.'; c.strokeText(tip,W/2,190); c.fillStyle="#e6dcc4"; c.fillText(tip,W/2,190);
    if(loading){ c.fillStyle='rgba(0,0,0,.5)'; c.fillRect(W/2-80,200,160,5); c.fillStyle="#e0b860"; c.fillRect(W/2-80,200,Math.round(160*load),5); } }});
  // pantalla de carga: lo que no se puede armar en el Worker (pueblo) y los fondos que se ven primero, de una vez; el resto, en el Worker
  const first=['z:titulo','z:ruinasLuz','ilianNino','olaf','z:ruinas','hagen','town','world']; if(saved&&saved.cp&&NEXTB[saved.cp]) first.push('z:'+NEXTB[saved.cp][0]);
  for(let k=0;k<first.length;k++){ const x=first[k]; if(x==='town'){ if(!WARMED.has('town')){ ENV.town.build(); WARMED.add('town'); } } else if(x==='world'){ try{ const wz=saved&&saved.world&&saved.world.zone; WORLD.prewarmNow(['global'].concat(wz&&wz!=='global'?[wz]:[]),true,wz==='global'?{x:saved.world.gx,y:saved.world.gy}:null); /* «Continuar»: la zona guardada y sus vecinas, armadas en la pantalla de carga */ }catch(e){ console.error(e); } } else if(x.startsWith('z:')){ ENV.prewarm([x.slice(2)],true); warmArt(x.slice(2),[]); } else warmArt(null,[x]); load=(k+1)/first.length; await new Promise(r=>setTimeout(r,AUTO?0:16)); if(k===0) fadeTo(0,700); }
  if(saved&&saved.cp&&NEXTB[saved.cp]&&ENV.prewarmMap&&!['hollin','contrato'].includes(saved.cp)) ENV.prewarmMap(true); // «Continuar» abre con el mapa: ya armado
  if(!AUTO&&FX.warm){ try{ FXW.done=FX.warm(900); }catch(e){} } // primer tramo de los efectos, todavía en la pantalla de carga
  loading=false; await fadeTo(0,300);
  if(ENV.prewarmMap){ ENV.prewarmMap(); WARMED.add('map'); }
  warmLater(WARM_ALL);
  if(PXP.warm && !AUTO){ const ex=['n','h','a','s','o','m','t']; setTimeout(()=>{ PXP.warm(['ilian','nach','maela','bertram','lina','agnes','encap','peregrino'].flatMap(id=>ex.map(e=>id+':'+e))); },4000); }
  await preloadArt();
  if(bootRec){ await loadSlot(boot,bootRec); return; } // «Cargar» desde la pausa: directo a la partida
  const titleOpts=()=>{ const lat=SAVES.latest(), met=lat&&lat.rec.g.flags&&lat.rec.g.flags.met;
    const o=[{label:'Comenzar',sub:'Desde el prólogo',value:'new',cls:'primary',auto:true,icon:'go'}];
    if(lat && ORDER.includes(lat.rec.cp)) o.push({label:'Continuar',sub:SLOTNAME(lat.id)+' · '+(lat.rec.place||STEPNAME[lat.rec.cp]||lat.rec.cp)+' · '+fmtDate(lat.rec.ts),value:'cont',icon:'go'});
    if(SAVES.any()) o.push({label:'Cargar partida',sub:'Autoguardado y 3 ranuras',value:'load',icon:'banner'});
    o.push({label:'Opciones',sub:'Texto, sonido, pantalla y teclas',value:'opts',icon:'light'});
    if(met) o.push({label:'Libro de retratos',sub:'Los personajes que ya conociste',value:'book',icon:'chat'});
    return {o,lat,met}; };
  let v, pick=null; while(true){ const T_=titleOpts(); v=await choose(T_.o,'Las Doce Coronas');
    if(v==='book'){ await openBook(T_.met); continue; }
    if(v==='opts'){ await openOptionsLayer(); continue; }
    if(v==='load'){ const id=await openSlotsLayer(); if(id){ pick=id; break; } continue; }
    if(v==='cont'){ pick=T_.lat&&T_.lat.id; }
    break; }
  AU.init(); AU.resume();
  if(pick&&await loadSlot(pick)) return;
  SAVES.fresh(); await fadeTo(1,400); runFrom('prologo');
}
